bool BuilderCmd_ShowUserMapDensity(CUserSocket* const socket, User*, char16_t*) {
    // Current L2Server 0x004d8c4c.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return false;
    }

    const double xValue = user->m_data->m_Pos.x;
    const double yValue = user->m_data->m_Pos.y;
    const SharedLong count = SharedUserMapDensity::Inst().CountByPos(user->m_data->m_Pos);
    const std::int32_t shiftedY = runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(yValue), 0x40000);
    const std::int32_t shiftedX = runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(xValue), 0x50000);
    const std::int32_t cellY = shiftedY / 0x800;
    const std::int32_t cellX = shiftedX / 0x800;
    const std::int32_t mapNumber =
        runtime::Int32FromBits(static_cast<std::uint32_t>(cellY) * 0x140U + static_cast<std::uint32_t>(cellX));

    std::array<char16_t, 104> message{};
    FormatUtf16To(message.data(), message.size(), u"UserMapDensity --> MapNum : %d , Count : %d", mapNumber, count);
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

