bool BuilderCmd_Vtest(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server 0x0056f9e8, original owner BuilderCmdHandler.cpp.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 5> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//vtest cmd item inten gem gemcount");
        return false;
    }

    const int commandId = WindowsWtol(tokens[0].data());
    const int itemId = WindowsWtol(tokens[1].data());
    const int intensiveId = WindowsWtol(tokens[2].data());
    const int gemId = WindowsWtol(tokens[3].data());
    const int gemCount = WindowsWtol(tokens[4].data());

    CPacketHelperEx<20480> packet;
    if (commandId == 0) {
        if (g_TestNPC == nullptr) {
            return false;
        }

        g_TestNPC->m_data->SetPos(user->GetPos());
        user->m_spTalkTarget = g_TestNPC->GetSmartID();
        TalkChannelCache::inst().mChannels[8].Cache(user->Id(), g_TestNPC->Id(), 0);
        socket->SendSystemMessage(u"SYS", u"Make TalkChannel");
        return false;
    }

    UserPacketExCallback callback = &DummyUserPacketEx;
    int packetId = 0;
    const char16_t* message = nullptr;
    switch (commandId) {
        case 1:
            static_cast<void>(packet.Assemble("d", itemId));
            packetId = 0x26;
            message = u"C_EX_TRY_TO_PUT_ITEM_FOR_VARIATION_MAKE";
            break;
        case 2:
            static_cast<void>(packet.Assemble("dd", itemId, intensiveId));
            packetId = 0x27;
            message = u"C_EX_TRY_TO_PUT_INTENSIVE_FOR_VARIATION_MAKE";
            break;
        case 3:
            static_cast<void>(packet.Assemble("dddQ", itemId, intensiveId, gemId, static_cast<std::int64_t>(gemCount)));
            packetId = 0x28;
            message = u"C_EX_TRY_TO_PUT_COMMISSION_FOR_VARIATION_MAKE";
            break;
        case 4:
            static_cast<void>(packet.Assemble("dddQ", itemId, intensiveId, gemId, static_cast<std::int64_t>(gemCount)));
            packetId = 0x3e;
            message = u"C_EX_TRY_TO_MAKE_VARIATION";
            break;
        case 5:
            static_cast<void>(packet.Assemble("d", itemId));
            packetId = 0x3f;
            message = u"C_EX_TRY_TO_PUT_ITEM_FOR_VARIATION_CANCEL";
            break;
        case 6:
            static_cast<void>(packet.Assemble("d", itemId));
            packetId = 0x40;
            message = u"C_EX_CLICK_VARIATION_CANCEL_BUTTON";
            break;
        default:
            if (commandId < 1) {
                return false;
            }
            break;
    }

    if (message != nullptr) {
        socket->SendSystemMessage(u"SYS", message);
        callback = g_UserPacketEx.GetCallback(packetId);
    }
    return callback(static_cast<CSocket*>(socket), reinterpret_cast<const std::uint8_t*>(packet.GetPacket()));
}

