        std::array<char16_t, 15> accountName{};
        static_cast<void>(user->GetDBID());
        static_cast<void>(user->GetAccountID());
        CopyBuilderText(characterName.data(), characterName.size(), user->GetName());
        const std::u16string accountNameText(user->m_sAccountName.data());
        CopyBuilderText(accountName.data(), accountName.size(), accountNameText.c_str());
