bool show_territory(CUserSocket* const socket, User*, char16_t*) {
    // Current L2Server 0x004d8d84, original owner BuilderCmdHandler.cpp.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    CCreature* target = builder->m_spTarget.GetCreature();
    if (target == nullptr) {
        target = builder;
    }

    CTerritory* territory = nullptr;
    if (!target->IsWorldTrap()) {
        CWorld& world = CWorld::Inst();
        const double y = builder->GetPos().y;
        const double x = builder->GetPos().x;
        const std::int32_t zoneX = (runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(x), 0x50000) >> 15) + 10;
        const std::int32_t zoneY = (runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(y), 0x40000) >> 15) + 10;
        territory = world.GetGeo()->GetZone(zoneX, zoneY)->GetNoDropItemTerritory(builder->GetPos());
    } else {
        territory = target->CastWorldTrap()->GetTrapArea();
    }

    if (territory == nullptr) {
        socket->SendSystemMessage(u"SYS", u"Target is not trap");
    } else {
        territory->ShowTerritoryByAdena(*builder);
    }
    return false;
}

