bool trap_detect_all(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server 0x004ffe64, original owner BuilderCmdHandler.cpp.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string account(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, account.c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPosition);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//trap_detect_all range");
        return false;
    }

    class TLMFunc final : public CTLMFunc {
    public:
        explicit TLMFunc(User* const builder) : m_builder(builder) {}

        bool CanDo(CObject* object, double) override {
            if (!object->IsPC() || (!object->IsDeleting() && object->m_Deleted == 0)) {
                static_cast<void>(DetecTrapForBuilderCmd(object->CastCreature(), m_builder));
            }
            return true;
        }

    private:
        User* m_builder;
    };


    const int range = WindowsWtol(tokens[0].data());
    const FVector position = builder->GetPos();
    const unsigned int inZoneId = builder->GetInZoneID();
    CTLMFilterDist filter(static_cast<int>(inZoneId), position, static_cast<double>(range));
    TLMFunc function(builder);
    // Current L2Server.exe 0x00534c48 calls the user-map wrapper at
    // 0x00aea120. Using the creature map can pass NPCs to CastUser().
    FOR_ALL_NEIGHBOR_USER_DIST(&filter, &function);
    return false;
}

