bool skill_test(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x0050bd30.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string account(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, account.c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPosition);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 3, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//skill_test count skill_id skill_level skill_sub_level");
        return false;
    }

    const int count = WindowsWtol(tokens[0].data());
    const int skillId = WindowsWtol(tokens[1].data());
    const int skillLevel = WindowsWtol(tokens[2].data());
    const int skillSubLevel = tokenCount < 4 ? 0 : WindowsWtol(tokens[3].data());
    const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(CSkillKey(skillId, skillLevel, skillSubLevel), builder);
    if (skillInfo == nullptr) {
        std::array<char16_t, 1024> message{};
        FormatUtf16To(
            message.data(), message.size(), u"unregistered skill (id:%d, level:%d sub_level:%d)", skillId, skillLevel,
            skillSubLevel
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }
    CCreature* const target = builder->m_spTarget.GetCreature();
    if (target == nullptr) {
        socket->SendSystemMessage(u"SYS", u"target is not creature");
        return false;
    }
    builder->SkillTest(*target, *const_cast<CSkillInfo*>(skillInfo), count, *builder);
    return false;
}

