bool BuilderCmd_BotCheckItem(CUserSocket* const socket, User*, char16_t*) {
    // Current L2Server.exe 0x0056a460.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    std::optional<std::u16string> account;
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        account.emplace(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, account->c_str());
        builderPosition = builder->GetPos();
    }

    const int itemClassId = g_nBotCheckItemClassID;
    const int count = g_nBotCheckItemCount;
    if (CCursedWeaponMgr::inst().FindConst(itemClassId) != nullptr) {
        socket->SendSystemMessage(u"SYS", u"please use //give_cursed_weapon");
        return false;
    }

    CCreature* const target = builder->m_spTarget.GetCreature();
    if (target == nullptr) {
        socket->SendSystemMessage(u"SYS", u"target null");
        return false;
    }
    if (target->IsSummonOrPet()) {
        socket->SendSystemMessage(u"SYS", u"target is summoned creature");
        return false;
    }
    if (!target->IsNPC()) {
        socket->SendSystemMessage(u"SYS", u"target must be a npc");
        return false;
    }
    if (target->IsNPC() && target->CastNPC()->IsBoss()) {
        socket->SendSystemMessage(u"SYS", u"target is boss!! Not available");
        return false;
    }
    if (target->IsNPC() && target->CastNPC()->IsZzoldagu()) {
        socket->SendSystemMessage(u"SYS", u"Failed to give fakeitem to npc or fakeitem already exists");
        return false;
    }
    if (itemClassId >= 1000001) {
        socket->SendSystemMessage(u"SYS", u"cannot give npc to npc -_-");
        return false;
    }
    if (itemClassId <= 0) {
        return false;
    }

    CObject* const object = g_ObjectDB.GetObjectW(itemClassId, false);
    if (object == nullptr || !object->IsItem()) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Item[%d] is not exist.",
        //     L"BuilderCmdHandler.cpp",
        //     0x52c7,
        //     itemClassId)
        // Previous: L2_LOG_ERROR(Log,
        //     L"[%s][%d] Item[%d] is not exist.",
        //     L"BuilderCmdHandler.cpp", 0x52c7, itemClassId)
        L2_LOG_ERROR(
            Log,
            u"[builder inventory] Item class %d is undefined or is not an "
            u"item; the give-item command is rejected.",
            itemClassId
        );
        return false;
    }
    CItem* const prototype = static_cast<CItem*>(object);
    if (!CSharedItemData::IsStackable(prototype->m_data->m_ItemConsumeType)) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Item[%d] is not stackable.",
        //     L"BuilderCmdHandler.cpp",
        //     0x52ce,
        //     itemClassId)
        // Previous: L2_LOG_ERROR(Log,
        //     L"[%s][%d] Item[%d] is not stackable.",
        //     L"BuilderCmdHandler.cpp", 0x52ce, itemClassId)
        L2_LOG_ERROR(
            Log,
            u"[builder inventory] Item class %d is not stackable; this "
            u"give-item command requires a stackable item and is rejected.",
            itemClassId
        );
        return false;
    }

    std::optional<ItemOptionKey> optionKey;
    std::optional<BaseAttribute> attribute;
    {
        L2_WRITE_GUARD(target->m_inv);
        optionKey.emplace();
        attribute.emplace();
        const bool added = target->AddItemToInventory(
            itemClassId, static_cast<std::int64_t>(count), ItemGetReason::GetFromBuilder, prototype->m_data->GetEnchanted(),
            0, 0, *optionKey, 0, *attribute
        );
        if (added) {
            socket->SendSystemMessage(u"SYS", u"succeed to give botcheckitem to npc -_-");
        }
    }

    // Log.Add(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
    //     L"%I64d,%I64d,,,,,%I64d,,,,%s,%s,,,",
    //     static_cast<long long>(0x20d),
    //     static_cast<long long>(builderDbId),
    //     static_cast<long long>(builderAccountId),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.x)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.z)),
    //     static_cast<long long>(itemClassId),
    //     static_cast<long long>(count),
    //     static_cast<long long>(0),
    //     builderName.data(),
    //     builderAccount.data())
    Log.Add(
        LOG_BOTH,
        u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
        u"%I64d,%I64d,,,,,%I64d,,,,%s,%s,,,",
        static_cast<long long>(0x20d), static_cast<long long>(builderDbId), static_cast<long long>(builderAccountId),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.x)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.y)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.z)), static_cast<long long>(itemClassId),
        static_cast<long long>(count), static_cast<long long>(0), builderName.data(), builderAccount.data()
    );
    return false;
}

