bool BuilderCmd_FakeItemState(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x005047e4.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//fakeitemstate (on|off)");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0) {
        if (!builder->m_bFakeItemState) {
            {
                L2_GUARD(builder->m_FakeItemStateLock);
                builder->m_bFakeItemState = true;
            }
            socket->SendSystemMessage(u"SYS", u"Now, Your FakeItemState is true.");
        } else {
            socket->SendSystemMessage(u"SYS", u"Current FakeItemState is true.");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0) {
        if (builder->m_bFakeItemState) {
            {
                L2_GUARD(builder->m_FakeItemStateLock);
                builder->m_bFakeItemState = false;
            }
            socket->SendSystemMessage(u"SYS", u"Now, Your FakeItemState is False.");
        } else {
            socket->SendSystemMessage(u"SYS", u"Current FakeItemState is False.");
        }
        return false;
    }

    socket->SendSystemMessage(
        u"SYS", builder->m_bFakeItemState ? u"Current FakeItemState is true." : u"Current FakeItemState is False."
    );
    socket->SendSystemMessage(u"SYS", u"//FakeItemState [on|off]");
    return false;
}

void AddBuilderCmdAlias(const char16_t* command, const char16_t* alias) {
    L2_GUARD_FUNCTION();

    const std::u16string commandKey(command);
    const auto commandPosition = g_BuilderCmdMap.find(commandKey);
    if (commandPosition == g_BuilderCmdMap.end()) {
        const std::u16string hostCommand(command);
        // Log.Add(
        //     LOG_ERROR,
        //     L"Builder Cmd [%s] do not exist. Cannot alias!",
        //     hostCommand.c_str())
        // Previous: L2_LOG_ERROR(Log,
        //     L"Builder Cmd [%s] do not exist. Cannot alias!",
        //     hostCommand.c_str())
        // L2_LOG_ERROR(Log,
        //     L"[builder commands] Cannot create an alias for unknown command "
        //     L"'%s'.",
        //     hostCommand.c_str())
        L2_LOG_ERROR(
            Log,
            u"[builder commands] Cannot create an alias for unknown command "
            u"'%s'.",
            hostCommand.c_str()
        );
        return;
    }

    const std::u16string aliasKey(alias);
    if (g_BuilderCmdMap.find(aliasKey) != g_BuilderCmdMap.end()) {
        const std::u16string hostAlias(alias);
        // Log.Add(
        //     LOG_ERROR,
        //     L"Builder Cmd Alias [%s] already exists!",
        //     hostAlias.c_str())
        // Previous: L2_LOG_ERROR(Log,
        //     L"Builder Cmd Alias [%s] already exists!", hostAlias.c_str())
        // L2_LOG_ERROR(Log,
        //     L"[builder commands] Alias '%s' already names a command. The new "
        //     L"alias is ignored.",
        //     hostAlias.c_str())
        L2_LOG_ERROR(
            Log,
            u"[builder commands] Alias '%s' already names a command; the new "
            u"alias is ignored.",
            hostAlias.c_str()
        );
        return;
    }

    g_BuilderCmdMap[aliasKey] = commandPosition->second;
    g_BuilderCmdStrMap[aliasKey] = commandKey;
}

bool BuilderCmd_xmastree(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x004e1f54. The target passes the map's 64-bit size
    // through a %d conversion. Preserve its low 32-bit lane explicitly.
    L2_GUARD_FUNCTION();
    std::array<char16_t, 128> message{};
    const std::int32_t treeCount = runtime::Int32FromBits(static_cast<std::uint32_t>(CTreeLoc::m_treelocs.size()));
    FormatUtf16To(message.data(), 0x7f, u"xmas tree count[%d]", treeCount);
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

