bool BuilderCmd_setskill2(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004e26a0 has no guard frame.
    if (command == nullptr) {
        return false;
    }

    std::array<int, 3> values{};
    if (!ParseBuilderIntList(command, values.data(), values.size())) {
        socket->SendSystemMessage(u"SYS", u"//setskill2 [begin skill id] [end skill id] [level]");
        return false;
    }
    const int beginSkillId = values[0];
    const int endSkillId = values[1];
    const int level = values[2];
    if (beginSkillId > endSkillId) {
        socket->SendSystemMessage(u"SYS", u"[begin skill id] must be less than [end skill id]");
        return false;
    }

    bool missingSkill = false;
    int skillId = beginSkillId;
    do {
        const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(CSkillKey(skillId, level, 0), user);
        if (skillInfo == nullptr) {
            std::array<char16_t, 1024> message{};
            FormatUtf16To(message.data(), message.size(), u"unregistered skill (id:%d, level:%d)", skillId, level);
            socket->SendSystemMessage(u"SYS", message.data());
            missingSkill = true;
        } else if (skillInfo->m_pszName != nullptr) {
            std::array<char16_t, 256> message{};
            FormatUtf16To(message.data(), message.size(), u"Try to set skill [%s]", skillInfo->m_pszName);
            socket->SendSystemMessage(u"SYS", message.data());
        }
        skillId = runtime::AddInt32Wrapping(skillId, 1);
    } while (skillId <= endSkillId);
    if (missingSkill) {
        return false;
    }

    User* target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        target = user;
    }
    if (target == nullptr) {
        return false;
    }
    std::array<char16_t, 32> targetName{};
    CopyBuilderText(targetName.data(), 0x19, target->GetName());
    std::array<char16_t, 16> targetAccount{};
    const std::u16string targetAccountText(target->m_sAccountName.data());
    CopyBuilderText(targetAccount.data(), 0x0f, targetAccountText.c_str());
    const FVector targetPosition = target->GetPos();

    {
        L2_GUARD(target->m_AcquiredSkillsSect);
        skillId = beginSkillId;
        do {
            if (target->AcquireSkill(skillId, level, 0, true, true)) {
                target->SendAcquiredSkillToDB(skillId, level, 0, true);
                std::array<char16_t, 256> result{};
                FormatUtf16To(
                    result.data(), result.size(), u"set skill for (%s : %s) ( %d:%d )", targetName.data(),
                    targetAccount.data(), skillId, level
                );
                socket->SendSystemMessage(u"SYS", result.data());

                const char16_t* const builderName = user->GetName();
                const std::uint32_t builderAccountId = user->GetAccountID();
                const std::uint32_t builderDbId = user->GetDBID();
                const std::u16string builderAccount(user->m_sAccountName.data());
                // Log.Add(
                //     LOG_BOTH,
                //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,"
                //     L"%I64d,,,,%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
                //     static_cast<long long>(0x1f9),
                //     static_cast<long long>(builderDbId),
                //     static_cast<long long>(builderAccountId),
                //     static_cast<long long>(0),
                //     static_cast<long long>(0),
                //     static_cast<long long>(
                //         runtime::Win64CvttDoubleToInt32(
                //             targetPosition.x)),
                //     static_cast<long long>(
                //         runtime::Win64CvttDoubleToInt32(
                //             targetPosition.y)),
                //     static_cast<long long>(
                //         runtime::Win64CvttDoubleToInt32(
                //             targetPosition.z)),
                //     static_cast<long long>(skillId),
                //     static_cast<long long>(level),
                //     builderName,
                //     builderAccount.c_str(),
                //     targetName.data(),
                //     targetAccount.data())
                // Log.Add(
                //     LOG_BOTH,
                //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,"
                //     L"%I64d,,,,%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
                //     static_cast<long long>(0x1f9),
                //     static_cast<long long>(builderDbId),
                //     static_cast<long long>(builderAccountId),
                //     static_cast<long long>(0),
                //     static_cast<long long>(0),
                //     static_cast<long long>(
                //         runtime::Win64CvttDoubleToInt32(
                //             targetPosition.x)),
                //     static_cast<long long>(
                //         runtime::Win64CvttDoubleToInt32(
                //             targetPosition.y)),
                //     static_cast<long long>(
                //         runtime::Win64CvttDoubleToInt32(
                //             targetPosition.z)),
                //     static_cast<long long>(skillId),
                //     static_cast<long long>(level),
                //     Utf16ToWide(builderName).c_str(),
                //     builderAccount.c_str(),
                //     targetName.data(),
                //     targetAccount.data())
                Log.Add(
                    LOG_BOTH,
                    u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,"
                    u"%I64d,,,,%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
                    static_cast<long long>(0x1f9), static_cast<long long>(builderDbId),
                    static_cast<long long>(builderAccountId), static_cast<long long>(0), static_cast<long long>(0),
                    static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.x)),
                    static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.y)),
                    static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.z)),
                    static_cast<long long>(skillId), static_cast<long long>(level), builderName, builderAccount.c_str(),
                    targetName.data(), targetAccount.data()
                );
            }
            skillId = runtime::AddInt32Wrapping(skillId, 1);
        } while (skillId <= endSkillId);
    }
    target->ValidateChanged(VB_MAX);
    target->ParamChanged(std::int64_t{PCB_USER});
    static_cast<void>(target->GetDBID());
    static_cast<void>(target->GetAccountID());
    target->SetMaxMagicLevel();
    target->SendETCBuffStatusInfo();
    return false;
}

bool BuilderCmd_delskill(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004e396c.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }
    int skillId = 0;
    if (!ParseBuilderIntList(command, &skillId, 1)) {
        socket->SendSystemMessage(u"SYS", u"//delskill [skill id]");
        return false;
    }

    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }
    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    {
        L2_GUARD(builder->m_AcquiredSkillsSect);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string builderAccountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, builderAccountText.c_str());
        builderPosition = builder->GetPos();
    }

    User* target = builder->m_spTarget.GetUser();
    if (target == nullptr) {
        target = builder;
    }
    bool deletedAcquiredSkill = false;
    {
        L2_GUARD(target->m_AcquiredSkillsSect);
        deletedAcquiredSkill = target->DeleteAcquireSkill(skillId);
    }
    if (deletedAcquiredSkill) {
        target->SendDeletedSkillToDB(skillId);
        target->ValidateChanged(VB_MAX);
        target->ParamChanged(std::int64_t{PCB_USER});
    }
    const bool deletedHonorsSkill = target->DeleteHonorsSkill(skillId);
    if (deletedHonorsSkill) {
        db.RequestDeleteHonorsSkill(target, skillId);
    }

    const std::uint32_t targetDbId = target->GetDBID();
    const std::uint32_t targetAccountId = target->GetAccountID();
    std::array<char16_t, 28> targetName{};
    CopyBuilderText(targetName.data(), 0x19, target->GetName());
    std::array<char16_t, 16> targetAccount{};
    const std::u16string targetAccountText(target->m_sAccountName.data());
    CopyBuilderText(targetAccount.data(), 0x0f, targetAccountText.c_str());
    const FVector targetPosition = target->GetPos();
    target->SetMaxMagicLevel();
    target->SendETCBuffStatusInfo();

    std::array<char16_t, 256> result{};
    FormatUtf16To(
        result.data(), result.size(), u"delete skill for (%s : %s) ( Id : %d ) result = %d", targetName.data(),
        targetAccount.data(), skillId, deletedHonorsSkill ? 1 : 0
    );
    socket->SendSystemMessage(u"SYS", result.data());

    // Log.Add(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
    //     L"%I64d,,,,,,,,,,%s,%s,%s,%s,",
    //     static_cast<long long>(0x20e),
    //     static_cast<long long>(builderDbId),
    //     static_cast<long long>(builderAccountId),
    //     static_cast<long long>(targetDbId),
    //     static_cast<long long>(targetAccountId),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.x)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.z)),
    //     static_cast<long long>(skillId),
    //     builderName.data(),
    //     builderAccount.data(),
    //     targetName.data(),
    //     targetAccount.data())
    Log.Add(
        LOG_BOTH,
        u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        u"%I64d,,,,,,,,,,%s,%s,%s,%s,",
        static_cast<long long>(0x20e), static_cast<long long>(builderDbId), static_cast<long long>(builderAccountId),
        static_cast<long long>(targetDbId), static_cast<long long>(targetAccountId),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.x)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.y)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.z)), static_cast<long long>(skillId),
        builderName.data(), builderAccount.data(), targetName.data(), targetAccount.data()
    );
    return false;
}

bool BuilderCmd_who(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x004d433c.
    L2_GUARD_FUNCTION();

    // Preserve the current volatile load order, which is the reverse of the
    // four displayed lanes.
    const std::int32_t maxServerUserCount = g_nMaxServerUserCount;
    const std::int32_t storeUserCount = g_nStoreUserCount;
    const std::int32_t playingUserCount = g_nPlayingUserCount;
    const std::int32_t serverUserCount = g_nServerUserCount;

    std::array<char16_t, 128> message{};
    FormatUtf16To(
        message.data(), message.size(), u"current(%d), playing(%d), private store(%d), max(%d)", serverUserCount,
        playingUserCount, storeUserCount, maxServerUserCount
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

