bool BuilderCmd_move_to(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004e3148.
    L2_GUARD_FUNCTION();
    User* const target = socket->GetUser();
    if (command == nullptr) {
        return false;
    }

    char16_t* const xToken = TakeBuilderTextToken(command);
    if (xToken == nullptr) {
        socket->SendSystemMessage(u"SYS", u"//move_to x y [z]");
        return false;
    }
    std::array<char16_t, 256> xText{};
    CopyBuilderText(xText.data(), xText.size(), xToken);

    char16_t* const yToken = TakeBuilderTextToken(command);
    if (yToken == nullptr) {
        socket->SendSystemMessage(u"SYS", u"//move_to x y [z]");
        return false;
    }
    std::array<char16_t, 256> yText{};
    CopyBuilderText(yText.data(), yText.size(), yToken);

    std::array<char16_t, 256> zText{};
    char16_t* const zToken = TakeBuilderTextToken(command);
    if (zToken != nullptr) {
        CopyBuilderText(zText.data(), zText.size(), zToken);
    }

    const int x = WindowsWtol(std::u16string_view(xText.data()));
    const int y = WindowsWtol(std::u16string_view(yText.data()));
    const int z = zToken == nullptr ? CWorld::Inst().GetGeo()->FindGround(x, y, 16000)
                                    : WindowsWtol(std::u16string_view(zText.data()));
    target->StopMove();
    target->MoveToLocation(x, y, z, CCreature::UsePathFind);
    return false;
}

