bool BuilderCmd_ns(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00575f28.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//ns command [options]...");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"situ") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel = 0;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel == 0 || builderLevel > 2) {
            return false;
        }
        CPledge* const pledge = user->GetPledge();
        if (pledge != nullptr) {
            pledge->SendWarReport(socket);
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"nobless") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel = 0;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel == 0 || builderLevel > 3) {
            return false;
        }
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//ns nobless nobless_type[0:none 1:nobless]");
            return false;
        }
        db.RequestSaveNoblessType(user, WindowsWtol(tokens[1].data()));
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"hero") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel = 0;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel == 0 || builderLevel > 2) {
            return false;
        }
        if (tokenCount < 2) {
            socket->SendSystemMessage(
                u"SYS",
                u"//ns hero hero_type[0:none 1:waiting 2:hero "
                u"3:legendary_waiting 4:legendary]"
            );
            return false;
        }

        if (Singleton<WOlympiadServiceConfig>::inst().IsHost()) {
            socket->SendSystemMessage(u"SYS", u"[ns hero] not available in host");
            return false;
        }
        const int heroType = WindowsWtol(tokens[1].data());
        CSPointer<User> retainedUser(user, ObjectRefType::FunctionChain);
        WOlympiadServiceProxy& proxy = Singleton<WOlympiadServiceProxy>::inst();
        const bool accepted = proxy.SetHeroType(std::move(retainedUser), heroType, 0, true);
        socket->SendSystemMessage(u"SYS", accepted ? u"[ns hero] accepted" : u"[ns hero] failed");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"diary") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//ns diary class page");
            return false;
        }
        static_cast<void>(WindowsWtol(tokens[1].data()));
        static_cast<void>(WindowsWtol(tokens[2].data()));
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"info") == 0) {
        CCreature* const selected = user->m_spTarget.GetCreature();
        if (selected != nullptr && selected->IsPC()) {
            user = selected->CastUser();
        }

        const SharedNoblessInfo* info = nullptr;
        if (Singleton<WOlympiadServiceConfig>::inst().IsHost()) {
            const int worldId = user->m_data->m_nWorldId;
            const int databaseId = static_cast<int>(user->GetDBID());
            info = Singleton<WOlympiadUsers>::inst().GetNoblessInfo(std::CDualKey<int, int>(worldId, databaseId));
        } else {
            const int databaseId = static_cast<int>(user->GetDBID());
            info = Singleton<NoblessSystem>::inst().GetNoblessInfo(databaseId);
        }

        if (info == nullptr) {
            socket->SendSystemMessage(u"SYS", u"no nobless yet");
            return false;
        }

        std::array<char16_t, 512> message{};
        FormatUtf16To(
            message.data(), message.size(),
            u"Nobless[%d] Hero[%d] MatchCount[%d] WinCount[%d] "
            u"LoseCount[%d] OlympiadPoint[%d] PreviousPoint[%d] "
            u"OlympiadTradePoint[%d] HeroWinCount[%d]",
            info->nNoblessType, info->nHeroType, info->nMatchCount, info->nOlympiadWinCount, info->nOlympiadLoseCount,
            info->nOlympiadPoint, info->nPreviousPoint, info->nOlympiadTradePoint, info->nWinCount
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"impound") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel = 0;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel == 0 || builderLevel > 2) {
            return false;
        }
        user->ImpoundHeroWeapon();
        user->ImpoundHeroEntryItem(false);
        user->ImpoundHeroEntryItem(true);
        socket->SendSystemMessage(u"SYS", u"[ns impound] accepted");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"match_result") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//ns match_result class page");
            return false;
        }
        const int classType = WindowsWtol(tokens[1].data());
        const int page = WindowsWtol(tokens[2].data());
        if (Singleton<WOlympiadServiceConfig>::inst().IsHost()) {
            socket->SendSystemMessage(u"SYS", u"[ns match_result] not available in host");
            return false;
        }
        CSPointer<User> retainedUser(user, ObjectRefType::FunctionChain);
        WOlympiadServiceProxy& proxy = Singleton<WOlympiadServiceProxy>::inst();
        if (!proxy.SendHeroMatchResult(std::move(retainedUser), classType, page)) {
            socket->SendSystemMessage(u"SYS", u"[ns match_result] failed");
        }
        return false;
    }

    return false;
}

