bool BuilderCmd_set_fatigue_user(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004fd2a0.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//set_fatigue_user [on|off]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"켬") == 0) {
        socket->SetApplyChinaFatigueSystem(true);
        socket->SendSystemMessage(u"SYS", u"Currently, you are applied fatigue user.");
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"끔") == 0) {
        socket->SetApplyChinaFatigueSystem(false);
        socket->SendSystemMessage(u"SYS", u"Currently, you are not applied fatigue user.");
    }
    return false;
}

bool BuilderCmd_check_bot(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004f5d88.
    L2_GUARD_FUNCTION();
    User* const target = user->m_spTarget.GetUser();
    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (command == nullptr || !ParseBuilderTextTokenList(command, 0, tokens, tokenCount)) {
        return false;
    }

    int checkType = 0;
    if (tokenCount > 0 && tokens[0][0] != L'\0') {
        checkType = WindowsWtol(tokens[0].data());
    }
    int tickCount = 0x10;
    if (tokenCount > 1 && tokens[1][0] != L'\0') {
        const int minutes = WindowsWtol(tokens[1].data());
        if (minutes > 0) {
            tickCount = runtime::MultiplyInt32Wrapping(minutes, 0x5a);
        }
    }

    User* const builder = socket->GetUser();
    if (builder != nullptr) {
        static_cast<void>(builder->m_BotChecker.BeginCheck(checkType, target, tickCount));
    }
    return false;
}

