bool BuilderCmd_pccafe(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004fd950.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//pccafe [on|off]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"켬") == 0) {
        if (!user->m_data->m_bPCCafeUser) {
            socket->SetPCCafeCode("111");
            socket->SendSystemMessage(u"SYS", u"Now, you are pccafe user.");
            user->m_data->m_bPCCafeUser = true;
            if (user->CanUsePCCafePoint()) {
                user->ResetPCCafeUseTime(true);
                user->LoadPCCafePoint(1);
                user->LoadPCCafePoint(3);
                user->m_data->m_bCanUsePCCafePoint = true;
            }
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"끔") == 0) {
        if (user->m_data->m_bPCCafeUser) {
            socket->SetPCCafeCode("0000000");
            socket->SendSystemMessage(u"SYS", u"Now, you are not pccafe user.");
            user->SendPCCafePointInfo(0, 0, false, true, 0);
            user->m_data->m_bPCCafeUser = false;
        }
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"//pccafe [on|off]");
    return false;
}

