bool BuilderCmd_add_pledge_namevalue(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0052c854.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//add_pledge_namevalue pledgename namevalue");
        return false;
    }

    const int worldId = user->m_data->m_nWorldId;
    std::u16string pledgeName = std::u16string(tokens[0].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(worldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        db.RequestLoadPledge(worldId, tokens[0].data());
        socket->SendSystemMessage(u"SYS", u"pledge name is not valid or not loaded yet");
        return false;
    }

    const unsigned int pledgeServerId = pledge->Id();
    const int nameValueDelta = WindowsWtol(tokens[1].data());
    const int currentNameValue = pledge->GetNameValue();
    const unsigned int pledgeDatabaseId = pledge->GetDbId();
    db.UpdatePledgeNameValue(pledgeServerId, pledgeDatabaseId, currentNameValue, nameValueDelta, g_nWorldId);
    socket->SendSystemMessage(u"SYS", u"pledge namevalue added");
    const int contributionPoint = WindowsWtol(tokens[1].data());
    PledgeContributionSystem::inst().AddPoint(user, pledge.get(), contributionPoint);
    return false;
}

