bool BuilderCmd_setskilllock(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004fe330 has no guard frame.
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setskilllock [skill id] [level] [subLevel] [on/off]");
        return false;
    }

    const int skillId = WindowsWtol(tokens[0].data());
    const int level = WindowsWtol(tokens[1].data());
    const int subLevel = WindowsWtol(tokens[2].data());
    const bool lock = std::u16string_view(tokens[3].data()).compare(u"on") == 0;
    const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(CSkillKey(skillId, level, subLevel), user);
    if (skillInfo == nullptr) {
        std::array<char16_t, 1024> message{};
        FormatUtf16To(message.data(), message.size(), u"unregistered skill (id:%d, level:%d)", skillId, level);
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }
    if (level > 0x100) {
        socket->SendSystemMessage(u"SYS", u"//setskilllock [skill id] [level] [on/off]");
        return false;
    }

    User* target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        target = user;
    }
    if (target == nullptr) {
        return false;
    }
    if (!target->HaveSkill(skillId, level, subLevel)) {
        socket->SendSystemMessage(u"SYS", u"//unaquired skill");
        return false;
    }

    target->SetSkillLock(skillId, level, subLevel, lock);
    target->ValidateChanged(std::int64_t{VB_MAX});

    std::array<char16_t, 25> targetName{};
    CopyBuilderText(targetName.data(), targetName.size(), target->GetName());
    std::array<char16_t, 15> targetAccount{};
    const std::u16string targetAccountText(target->m_sAccountName.data());
    CopyBuilderText(targetAccount.data(), targetAccount.size(), targetAccountText.c_str());

    std::array<char16_t, 256> message{};
    FormatUtf16To(
        message.data(), message.size(), u"set skill lock for (%s : %s) ( %d:%d )", targetName.data(), targetAccount.data(),
        skillId, level
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

