bool BuilderCmd_NpcUseSkill(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0050348c.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//npc_use_skill skill_id skill_level, skill_sub_level");
        return false;
    }

    const int skillId = WindowsWtol(tokens[0].data());
    const int skillLevel = WindowsWtol(tokens[1].data());
    const int skillSubLevel = tokenCount >= 3 ? WindowsWtol(tokens[2].data()) : 0;

    CCreature* const target = user->m_spTarget.GetCreature();
    if (target == nullptr || !target->IsNPC()) {
        socket->SendSystemMessage(u"SYS", u"target should be NPC");
        return false;
    }

    std::uint64_t packedSkill = static_cast<std::uint64_t>(static_cast<std::int64_t>(skillId));
    packedSkill <<= 16U;
    packedSkill |= static_cast<std::uint64_t>(static_cast<std::int64_t>(skillLevel));
    packedSkill <<= 16U;
    packedSkill |= static_cast<std::uint64_t>(static_cast<std::int64_t>(skillSubLevel));
    std::int64_t skillNameId = 0;
    std::memcpy(&skillNameId, &packedSkill, sizeof(skillNameId));

    static_cast<void>(target->CastNPC()->OnNpcUseSkillPacket(user->m_nId, skillNameId, AMT_STAND, 1, 0, 0));
    return false;
}

