bool BuilderCmd_PathfindTest(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x00505ea0.
    L2_GUARD_FUNCTION();
    User* const initialUser = socket->GetUser();
    if (initialUser == nullptr) {
        return true;
    }

    int builderLevel = 0;
    {
        L2_GUARD(*initialUser->m_lock);
        builderLevel = initialUser->m_data->m_nBuilder;
    }
    if (builderLevel == 0 || builderLevel > 2) {
        return false;
    }

    User* const user = socket->GetUser();
    if (user == nullptr) {
        return false;
    }
    FVector position = user->GetPos();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    static_cast<void>(ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount));
    if (tokenCount >= tokens.size()) {
        position.x = static_cast<double>(WindowsWtol(tokens[0].data()));
        position.y = static_cast<double>(WindowsWtol(tokens[1].data()));
        position.z = static_cast<double>(WindowsWtol(tokens[2].data()));
    }

    const bool accepted = g_pnWorld.FindPathNodeTest(position);
    std::array<char16_t, 256> message{};
    FormatUtf16To(
        message.data(), message.size(), accepted ? u"(%d, %d, %d) is ok" : u"(%d, %d, %d) is NOT o.k",
        runtime::Win64CvttDoubleToInt32(position.x), runtime::Win64CvttDoubleToInt32(position.y),
        runtime::Win64CvttDoubleToInt32(position.z)
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

bool BuilderCmd_reset_mac(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00506150.
    L2_GUARD_FUNCTION();
    if (user == nullptr || socket == nullptr || command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//reset_mac [all | mac address(00-00-00-00-00-00)]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"all") == 0) {
        g_SocketLimiter.DeleteAllMAC();
    } else {
        std::array<unsigned int, 6> scannedValues{};
        const int scannedCount = std::swscanf(
            Utf16ToWide(tokens[0].data()).c_str(), L"%02X-%02X-%02X-%02X-%02X-%02X", &scannedValues[0], &scannedValues[1],
            &scannedValues[2], &scannedValues[3], &scannedValues[4], &scannedValues[5]
        );

        // Current passes six byte-offset pointers into 32-bit %X
        // conversions. Reproduce those overlapping little-endian writes,
        // including the state left by a partial scan, without host UB.
        std::array<std::uint8_t, 6> carrier{};
        const int completed = std::clamp(scannedCount, 0, 6);
        for (int index = 0; index < completed; ++index) {
            const std::uint32_t bits = scannedValues[index];
            for (int byteIndex = 0; byteIndex < 4 && index + byteIndex < 6; ++byteIndex) {
                carrier[static_cast<std::size_t>(index + byteIndex)] = static_cast<std::uint8_t>(bits >> (byteIndex * 8));
            }
        }

        std::uint64_t address = 0;
        for (std::size_t index = 0; index < carrier.size(); ++index) {
            address += static_cast<std::uint64_t>(carrier[index]) << (40U - static_cast<unsigned int>(index) * 8U);
        }
        g_SocketLimiter.DeleteUserSocketPerMAC(static_cast<std::int64_t>(address));
    }

    socket->SendSystemMessage(u"SYS", u"completed to reset mac");
    return false;
}

bool BuilderCmd_reset_ip(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x005063f0.
    L2_GUARD_FUNCTION();
    if (user == nullptr || socket == nullptr || command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//reset_ip [all | ip address(000.000.000.000)]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"all") == 0) {
        g_SocketLimiter.DeleteAllIP();
    } else {
        std::array<int, 4> scannedValues{};
        const int scannedCount = std::swscanf(
            Utf16ToWide(tokens[0].data()).c_str(), L"%d.%d.%d.%d", &scannedValues[0], &scannedValues[1], &scannedValues[2],
            &scannedValues[3]
        );

        // Current likewise writes each 32-bit %d result one byte after the
        // preceding result and ignores the conversion count.
        std::array<std::uint8_t, 4> carrier{};
        const int completed = std::clamp(scannedCount, 0, 4);
        for (int index = 0; index < completed; ++index) {
            const std::uint32_t bits = static_cast<std::uint32_t>(scannedValues[index]);
            for (int byteIndex = 0; byteIndex < 4 && index + byteIndex < 4; ++byteIndex) {
                carrier[static_cast<std::size_t>(index + byteIndex)] = static_cast<std::uint8_t>(bits >> (byteIndex * 8));
            }
        }

        std::uint32_t address = 0;
        for (std::size_t index = 0; index < carrier.size(); ++index) {
            address += static_cast<std::uint32_t>(carrier[index]) << (24U - static_cast<unsigned int>(index) * 8U);
        }
        g_SocketLimiter.DeleteUserSocketPerIP(address);
    }

    socket->SendSystemMessage(u"SYS", u"completed to reset ip");
    return false;
}

