bool BuilderCmd_reset_castle_owner(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0052ee98.
    L2_GUARD_FUNCTION();
    if (user == nullptr) {
        socket->SendSystemMessage(u"SYS", u"User is not valid");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//reset_castle_owner castle");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string name = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(name.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr) {
        return false;
    }

    const auto auditAccepted = [socket, residence](const int) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return false;
        }

        std::uint32_t builderDbId = 0;
        std::uint32_t builderAccountId = 0;
        std::array<char16_t, 28> builderName{};
        std::array<char16_t, 16> builderAccount{};
        FVector builderPosition{};
        {
            L2_GUARD(*builder->m_lock);
            builderDbId = builder->GetDBID();
            builderAccountId = builder->GetAccountID();
            CopyBuilderText(builderName.data(), 0x19, builder->GetName());
            const std::u16string account(builder->m_sAccountName.data());
            CopyBuilderText(builderAccount.data(), 0x0f, account.c_str());
            builderPosition = builder->GetPos();
        }

        // Log.Add(
        //     LOG_BOTH,
        //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,%I64d,%s,"
        //     L",,,,,,,,,,,%s,%s,,,",
        //     static_cast<long long>(0x218),
        //     static_cast<long long>(builderDbId),
        //     static_cast<long long>(builderAccountId),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.x)),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.y)),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.z)),
        //     static_cast<long long>(residence->GetResidenceID()),
        //     L"[NPC]",
        //     builderName.data(),
        //     builderAccount.data())
        // Log.Add(
        //     LOG_BOTH,
        //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,%I64d,%s,"
        //     L",,,,,,,,,,,%s,%s,,,",
        //     static_cast<long long>(0x218),
        //     static_cast<long long>(builderDbId),
        //     static_cast<long long>(builderAccountId),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.x)),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.y)),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.z)),
        //     static_cast<long long>(residence->GetResidenceID()),
        //     L"[NPC]",
        //     builderName.data(),
        //     builderAccount.data())
        Log.Add(
            LOG_BOTH,
            u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,%I64d,%s,"
            u",,,,,,,,,,,%s,%s,,,",
            static_cast<long long>(0x218), static_cast<long long>(builderDbId), static_cast<long long>(builderAccountId),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.x)),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.y)),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.z)),
            static_cast<long long>(residence->GetResidenceID()), u"[NPC]", builderName.data(), builderAccount.data()
        );
        socket->SendSystemMessage(u"SYS", u"builder command[reset_castle_owner] accepted");
        return true;
    };

    const auto rejectNpcOwner = [socket]() {
        socket->SendSystemMessage(u"SYS", u"NPC already owns the castle.");
        return false;
    };

    if (residence->IsCastle()) {
        const int ownerPledgeId = residence->GetResidenceOwnerID();
        const int ownerWorldId = residence->GetResidenceOwnerWorldID();
        if (ownerPledgeId == 0) {
            return rejectNpcOwner();
        }

        CSPointer<CPledge> owner = CPledge::FindPledge(ownerWorldId, ownerPledgeId);
        if (owner) {
            owner->SetCastle(nullptr);
            owner->Save(6);
            owner->UpdatePledgeInfoPacket();
            owner->UpdateInfoWindowPacket();
            owner->UnequipMemberCastleItem();
        }

        CCastle* const castle = static_cast<CCastle*>(residence);
        castle->SetPledge(nullptr);
        db.ReqOwnCastle(castle, 0, castle->m_PreviousOwnerPledgeDbId, 0, 0, castle->m_nPrevOwnerPledgeWorldId);
        castle->BroadcastCastleState();
        db.RequestSetCastleCampaign(castle, -1);
        return !auditAccepted(0x27a3);
    }

    if (residence->IsWorldAgit()) {
        const int ownerPledgeId = residence->GetResidenceOwnerID();
        const int ownerWorldId = residence->GetResidenceOwnerWorldID();
        if (ownerPledgeId == 0) {
            return rejectNpcOwner();
        }

        CSPointer<CPledge> owner = CPledge::FindPledge(ownerWorldId, ownerPledgeId);
        if (owner) {
            owner->SetWorldAgit(nullptr);
            owner->Save(7);
            owner->UpdateInfoWindowPacket();
            owner->UnequipMemberCastleItem();
        }

        CWorldAgit* const worldAgit = static_cast<CWorldAgit*>(residence);
        worldAgit->SetPledge(nullptr);
        if (worldAgit->IsAuctionAgit()) {
            CAuctionAgit* const auctionAgit = worldAgit->CastAuctionAgit();
            if (auctionAgit->GetSaleState() != SALE_ACT) {
                auctionAgit->SetSaleState(SALE_AUTOSELL);
            }
        }
        db.ReqOwnAgit(worldAgit, 0);
        return !auditAccepted(0x27d1);
    }

    if (residence->IsFortress()) {
        if (residence->GetResidenceOwnerID() == 0) {
            return rejectNpcOwner();
        }
        static_cast<CFortress*>(residence)->ResetOwnership();
        socket->SendSystemMessage(u"SYS", u"reset_owner accepted");
        return false;
    }

    if (residence->IsDominion()) {
        socket->SendSystemMessage(
            u"SYS", u"no effect for dominion. you must reset castle's owner to reset dominion's owner."
        );
    }
    return false;
}

namespace BuilderCmd {

bool CSCharacterInfoPacket(CUserSocket* socket, char16_t* command) {
    // Current L2Server 0x00547918.
    L2_GUARD_FUNCTION();

    User* const invokingUser = socket->GetUser();
    if (invokingUser == nullptr) {
        return true;
    }

    int builderLevel = 0;
    {
        L2_GUARD(*invokingUser->m_lock);
        builderLevel = invokingUser->m_data->m_nBuilder;
    }
    // Current accepts negative builder levels and rejects only zero or > 9.
    if (builderLevel == 0 || builderLevel > 9) {
        return false;
    }

    std::u16string lowerName = LowercaseGameName(command);

    if (CompareBuilderTextIgnoreCase(lowerName.c_str(), u".") == 0) {
        User* const selectingUser = socket->GetUser();
        if (selectingUser == nullptr) {
            return false;
        }

        CCreature* const selectedCreature = selectingUser->m_spTarget.GetCreature();
        if (selectedCreature != nullptr) {
            if (selectedCreature->IsNPC()) {
                const FVector position = selectedCreature->GetPos();
                CSharedCreatureData* sharedData = nullptr;
                std::array<char16_t, 512> message{};
                {
                    L2_GUARD(*selectedCreature->m_lock);
                    sharedData = selectedCreature->m_data;

                    const double currentHpValue = sharedData->m_dHP;
                    const double maximumHpValue = sharedData->m_dBaseHP;
                    const double currentMpValue = sharedData->m_dMP;
                    const double maximumMpValue = sharedData->m_dBaseMP;
                    const int inZoneId = static_cast<int>(selectedCreature->GetInZoneID());
                    const char16_t* const npcName = selectedCreature->GetName();

                    FormatUtf16To(
                        message.data(), 0x1ff, u"class id :%d ori name : %s SharedFactoryIndex : %d Inzone : %d",
                        sharedData->m_nClassID, npcName, sharedData->index, inZoneId
                    );
                    socket->SendSystemMessage(u"SYS", message.data());

                    FormatUtf16To(
                        message.data(), 0x1ff,
                        u"HP:%d/%d(%.2f/%.2f) HP_regen:%d MP:%d/%d MP_regen:%d Exp:%I64d SP:%I64d Level:%d Speed:%d Hit:%d "
                        u"Avoid:%d PAttack:%d PDefend:%d MAttack:%d MDefend:%d ",
                        runtime::Win64CvttDoubleToInt32(currentHpValue), runtime::Win64CvttDoubleToInt32(maximumHpValue),
                        currentHpValue, maximumHpValue, runtime::Win64CvttDoubleToInt32(sharedData->m_dHPRegen),
                        runtime::Win64CvttDoubleToInt32(currentMpValue), runtime::Win64CvttDoubleToInt32(maximumMpValue),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dMPRegen), static_cast<long long>(sharedData->m_nExp),
                        static_cast<long long>(sharedData->m_nSP), sharedData->m_nLevel,
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[11]),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[7]),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[14]),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[2]),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[0]),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[3]),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[1])
                    );
                    socket->SendSystemMessage(u"SYS", message.data());

                    std::int64_t acquiredExperience = runtime::Win64CvttDoubleToInt64(sharedData->m_dAcquireExpRate);
                    acquiredExperience = runtime::MultiplyInt64Wrapping(
                        acquiredExperience, static_cast<std::int64_t>(sharedData->m_nLevel)
                    );
                    acquiredExperience = runtime::MultiplyInt64Wrapping(
                        acquiredExperience, static_cast<std::int64_t>(sharedData->m_nLevel)
                    );
                    const int nearbyUsers = SharedUserMapDensity::Inst().CountByPos(sharedData->m_Pos);

                    FormatUtf16To(
                        message.data(), 0x1ff,
                        u"PAttackSpeed:%d MAttackSpeed:%d Exp_acquire:%I64d SP_acquire:%d Weight %d/%d x:%d,y:%d,z:%d "
                        u"resi[%d] manor[%d] (alive:%d active:%d freezed:%d CanAct:%d action:%d) UserMap[%d]",
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[4]),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[5] * 333.0),
                        static_cast<long long>(acquiredExperience),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dAcquireSP),
                        selectedCreature->m_inv.GetCarryingWeight(),
                        runtime::Win64CvttDoubleToInt32(sharedData->m_dCarryWeight),
                        runtime::Win64CvttDoubleToInt32(position.x), runtime::Win64CvttDoubleToInt32(position.y),
                        runtime::Win64CvttDoubleToInt32(position.z), sharedData->m_nResidenceID, sharedData->m_nDomainID,
                        sharedData->m_bIsAlive, sharedData->m_bIsActive ? 1 : 0, sharedData->m_bIsFreezed ? 1 : 0,
                        static_cast<int>(sharedData->m_bCanAct), static_cast<int>(sharedData->m_Action), nearbyUsers
                    );
                    socket->SendSystemMessage(u"SYS", message.data());

                    FormatUtf16To(
                        message.data(), 0x1ff,
                        u"int[%d,%d] str[%d,%d] con[%d,%d] men[%d,%d] dex[%d,%d] wit[%d,%d] luc[%d,%d] cha[%d,%d]",
                        sharedData->m_OriginalStat.m_N[0], sharedData->m_Stat.m_N[0], sharedData->m_OriginalStat.m_N[1],
                        sharedData->m_Stat.m_N[1], sharedData->m_OriginalStat.m_N[2], sharedData->m_Stat.m_N[2],
                        sharedData->m_OriginalStat.m_N[3], sharedData->m_Stat.m_N[3], sharedData->m_OriginalStat.m_N[4],
                        sharedData->m_Stat.m_N[4], sharedData->m_OriginalStat.m_N[5], sharedData->m_Stat.m_N[5],
                        sharedData->m_OriginalStat.m_N[6], sharedData->m_Stat.m_N[6], sharedData->m_OriginalStat.m_N[7],
                        sharedData->m_Stat.m_N[7]
                    );
                    socket->SendSystemMessage(u"SYS", message.data());
                }

                CSharedCreatureData* attributeOwner = sharedData;
                if (selectedCreature->IsSummon()) {
                    User* const master = selectedCreature->GetUserOrMaster();
                    if (master != nullptr) {
                        attributeOwner = master->m_data;
                    }
                }
                std::array<char16_t, 256> attribute{};
                attributeOwner->m_BaseAttribute.GetLogString(attribute.data());
                FormatUtf16To(message.data(), 0x1ff, u"Attribute info : [%s]", attribute.data());
                socket->SendSystemMessage(u"SYS", message.data());
                return false;
            }

            if (selectedCreature->IsPC()) {
                lowerName = LowercaseGameName(selectedCreature->GetName());
            }
        } else {
            CStaticObject* const selectedStaticObject = selectingUser->m_spTarget.GetStaticObject();
            if (selectedStaticObject != nullptr && selectedStaticObject->IsDoor()) {
                CDoor* const door = selectedStaticObject->CastDoor();
                const wchar_t* openMethod = L"OpenMethod Invalid";
                switch (door->m_eDoorOpenMethod) {
                    case DOOROPEN_NPC:
                        openMethod = L"NPC";
                        break;
                    case DOOROPEN_SKILL:
                        openMethod = L"SKILL";
                        break;
                    case DOOROPEN_CLICK:
                        openMethod = L"CLICK";
                        break;
                    case DOOROPEN_TIME:
                        openMethod = L"TIME";
                        break;
                    case DOOROPEN_SUNRISE:
                        openMethod = L"SUNRISE";
                        break;
                    case DOOROPEN_TIME_SKILL:
                        openMethod = L"TIME_SKILL";
                        break;
                    case DOOROPEN_SKILL_ITEM:
                        openMethod = L"SKILL_ITEM";
                        break;
                    case DOOROPEN_ITEM:
                        openMethod = L"ITEM";
                        break;
                    default:
                        break;
                }

                const bool breakable = door->m_data->m_bBreakable;
                const int stealth = door->m_data->m_nStealth;
                const bool targetable = door->IsTargetable();
                const wchar_t* const currentStatus = door->m_data->m_bIsOpen ? L"Open" : L"Close";
                const std::wstring doorName = ::Utf16ToWide(std::u16string_view(door->m_sDoorName));
                std::array<char16_t, 1024> message{};
                FormatUtf16To(
                    message.data(), message.size(),
                    u"[%s] Door Info : Current Status : %s, OpenMethod : %s, OpenTime: %d, CloseTime %d, MaxRandomTime %d. "
                    u"Real [Open/Close] Time = [Open/Close]Time + (0~MaxRandomTime) targetable = %d stealth = %d breakable "
                    u"= %d",
                    currentStatus, doorName.c_str(), openMethod, door->m_nOpenTime / 1000, door->m_nCloseTime / 1000,
                    std::max(0, door->m_nRandomTime) / 1000, targetable ? 1 : 0, stealth, breakable ? 1 : 0
                );
                socket->SendSystemMessage(u"SYS", message.data());
            }
            return false;
        }
    }

    CSPointer<User> targetReference = GetUserFromNameMap(g_nWorldId, lowerName);
    User* const target = targetReference.get();
    if (target == nullptr) {
        return false;
    }

    std::array<char16_t, 24> pledgeName{};
    std::array<char16_t, 25> pledgeMasterName{};
    int pledgeLevel = 0;
    CPledge* const pledge = target->GetPledge();
    if (pledge == nullptr) {
        CopyBuilderText(pledgeName.data(), pledgeName.size(), u" ");
        CopyBuilderText(pledgeMasterName.data(), pledgeMasterName.size(), u" ");
    } else {
        CopyBuilderText(pledgeName.data(), pledgeName.size(), std::u16string(pledge->GetPledgeName()).c_str());
        CopyBuilderText(
            pledgeMasterName.data(), pledgeMasterName.size(), std::u16string(pledge->GetPledgeMasterName()).c_str()
        );
        pledgeLevel = static_cast<int>(pledge->GetPledgeLevel());
    }

    const FVector targetPosition = target->GetPos();
    CSharedCreatureData* sharedData = nullptr;
    std::array<char16_t, 512> message{};
    {
        L2_GUARD(*target->m_lock);
        const std::uint32_t accountId = target->GetAccountID();
        const std::uint32_t characterDbId = target->GetDBID();
        sharedData = target->m_data;
        const int bonusLimitTime = target->m_nBonusTimeLimit;
        const int botReportPoint = target->m_nBotReportPoint;
        const int positionZ = runtime::Win64CvttDoubleToInt32(targetPosition.z);
        const int positionY = runtime::Win64CvttDoubleToInt32(targetPosition.y);
        const int positionX = runtime::Win64CvttDoubleToInt32(targetPosition.x);
        const int currentWeight = target->m_inv.GetCarryingWeight();
        const int vitalityPoint = target->GetVitalPoint();
        const int freezeCountdown = static_cast<int>(target->dwFreezeRemainTime / 60000U);
        const int bonusExperienceRate = runtime::Win64CvttDoubleToInt32(static_cast<double>(target->m_nRate) * 100.0);

        FormatUtf16To(
            message.data(), 0x1ff,
            u"AccountId:%u CharacterDBId:%u HP:%d/%d(%.2f/%.2f) HP_regen:%d CP:%d/%d(%.2f/%.2f) MP:%d/%d MP_regen:%d "
            u"Exp:%I64d SP:%I64d Level:%d Speed:%d Hit:%d Avoid:%d PAttack:%d PDefend:%d MAttack:%d MDefend:%d "
            u"PAttackSpeed:%d MAttackSpeed:%d Weight %d/%d pledge name[%s] master[%s] pledgeLevel[%d] x:%d y:%d z:%d freeze "
            u"countdown:%d VitalityPoint:%dbot reported count:%d (alive:%d active:%d freezed:%d)VoteSystem (BonusExpRate:%d "
            u"BonusLimitTime:%d)",
            accountId, characterDbId, runtime::Win64CvttDoubleToInt32(sharedData->m_dHP),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dBaseHP), sharedData->m_dHP, sharedData->m_dBaseHP,
            runtime::Win64CvttDoubleToInt32(sharedData->m_dHPRegen), runtime::Win64CvttDoubleToInt32(sharedData->m_dCP),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dBaseCP), sharedData->m_dCP, sharedData->m_dBaseCP,
            runtime::Win64CvttDoubleToInt32(sharedData->m_dMP), runtime::Win64CvttDoubleToInt32(sharedData->m_dBaseMP),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dMPRegen), static_cast<long long>(sharedData->m_nExp),
            static_cast<long long>(sharedData->m_nSP), sharedData->m_nLevel,
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[11]),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[7]),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[14]),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[2]),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[0]),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[3]),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[1]),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[4]),
            runtime::Win64CvttDoubleToInt32(sharedData->m_dParam[5] * 333.0), currentWeight,
            runtime::Win64CvttDoubleToInt32(sharedData->m_dCarryWeight), pledgeName.data(), pledgeMasterName.data(),
            pledgeLevel, positionX, positionY, positionZ, freezeCountdown, vitalityPoint, botReportPoint,
            sharedData->m_bIsAlive, sharedData->m_bIsActive ? 1 : 0, sharedData->m_bIsFreezed ? 1 : 0, bonusExperienceRate,
            bonusLimitTime
        );
    }
    socket->SendSystemMessage(u"SYS", message.data());

    const char16_t* const questFirstFormat =
        u"Quest memo:(%d,%d,%d,%d,%d) (%d,%d,%d,%d,%d) (%d,%d,%d,%d,%d) (%d,%d,%d,%d,%d) (%d,%d,%d,%d,%d)";
    const char16_t* const questFormat =
        u"(%d,%d,%d,%d,%d) (%d,%d,%d,%d,%d) (%d,%d,%d,%d,%d) (%d,%d,%d,%d,%d) (%d,%d,%d,%d,%d)";
    const auto formatQuestLine =
        [questFirstFormat, questFormat](std::array<char16_t, 256>& output, const MemoStruct* memos, const bool first) {
            FormatUtf16To(
                output.data(), 0xff, first ? questFirstFormat : questFormat, memos[0].nQuestID, memos[0].nState,
                memos[0].nState2, memos[0].nState3, memos[0].nState4, memos[1].nQuestID, memos[1].nState, memos[1].nState2,
                memos[1].nState3, memos[1].nState4, memos[2].nQuestID, memos[2].nState, memos[2].nState2, memos[2].nState3,
                memos[2].nState4, memos[3].nQuestID, memos[3].nState, memos[3].nState2, memos[3].nState3, memos[3].nState4,
                memos[4].nQuestID, memos[4].nState, memos[4].nState2, memos[4].nState3, memos[4].nState4
            );
        };

    std::array<std::array<char16_t, 256>, 3> questLines{};
    formatQuestLine(questLines[0], &sharedData->m_Memo[0], true);
    formatQuestLine(questLines[1], &sharedData->m_Memo[5], false);
    formatQuestLine(questLines[2], &sharedData->m_Memo[10], false);
    for (const auto& line : questLines) {
        socket->SendSystemMessage(u"SYS", line.data());
    }
    formatQuestLine(questLines[0], &sharedData->m_Memo[15], false);
    formatQuestLine(questLines[1], &sharedData->m_Memo[20], false);
    for (std::size_t index = 0; index < 2; ++index) {
        socket->SendSystemMessage(u"SYS", questLines[index].data());
    }
    formatQuestLine(questLines[0], &sharedData->m_Memo[25], false);
    formatQuestLine(questLines[1], &sharedData->m_Memo[30], false);
    formatQuestLine(questLines[2], &sharedData->m_Memo[35], false);
    for (const auto& line : questLines) {
        socket->SendSystemMessage(u"SYS", line.data());
    }

    socket->SendSystemMessage(u"SYS", u"-- Quest NRMemo --");
    for (std::size_t lineIndex = 0; lineIndex < 4; ++lineIndex) {
        const MemoStruct* const memos = &sharedData->m_NRMemo[lineIndex * 5];
        std::array<char16_t, 256> line{};
        FormatUtf16To(
            line.data(), 0xff, u"(%d,%d,%d) (%d,%d,%d) (%d,%d,%d) (%d,%d,%d) (%d,%d,%d)", memos[0].nQuestID, memos[0].nState,
            memos[0].nState2, memos[1].nQuestID, memos[1].nState, memos[1].nState2, memos[2].nQuestID, memos[2].nState,
            memos[2].nState2, memos[3].nQuestID, memos[3].nState, memos[3].nState2, memos[4].nQuestID, memos[4].nState,
            memos[4].nState2
        );
        socket->SendSystemMessage(u"SYS", line.data());
    }

    const FVector currentPosition = target->GetPos();
    CUserSocket* const targetSocket = target->GetSocket();
    const ::in_addr address = targetSocket->GetAddress();
    std::array<std::uint8_t, 4> addressBytes{};
    std::memcpy(addressBytes.data(), &address.s_addr, addressBytes.size());
    const std::wstring accountName = ::Utf16ToWide(std::u16string_view(target->m_sAccountName.data()));
    FormatUtf16To(
        message.data(), 0x1ff, u"loc(%d,%d,%d) , ip(%d.%d.%d.%d) account(%s), class(%d)",
        runtime::Win64CvttDoubleToInt32(currentPosition.x), runtime::Win64CvttDoubleToInt32(currentPosition.y),
        runtime::Win64CvttDoubleToInt32(currentPosition.z), static_cast<int>(addressBytes[0]),
        static_cast<int>(addressBytes[1]), static_cast<int>(addressBytes[2]), static_cast<int>(addressBytes[3]),
        accountName.c_str(), static_cast<int>(sharedData->m_nClass)
    );
    socket->SendSystemMessage(u"SYS", message.data());

    if (g_nPlayTimeLimit > 0) {
        const int remainingSeconds =
            runtime::SubtractInt32Wrapping(g_nPlayTimeLimit, target->GetSocket()->GetSocketPlayTime());
        const int remainingHours = remainingSeconds / 3600;
        const int remainingMinutes = (remainingSeconds % 3600) / 60;
        const wchar_t* const loginMode = target->GetSocket()->m_bForceLogin ? L"limitless" : L"normal";
        FormatUtf16To(
            message.data(), 0x1ff, u"Remain green time :: [%d] hour [%d] min, %s", remainingHours, remainingMinutes,
            loginMode
        );
        socket->SendSystemMessage(u"SYS", message.data());
    }

    const int containerNumber = target->GetContainerIndex();
    CContainer* container = CContainerDB::Inst().GetContainer(sharedData->container_index);
    int parentContainerNumber = -1;
    int worldContainerX = 0;
    int worldContainerY = 0;
    if (container != nullptr) {
        parentContainerNumber = container->m_Data.m_nParentContainerIndex;
        if (parentContainerNumber != -1) {
            container = CContainerDB::Inst().GetContainer(parentContainerNumber);
        }
        if (container != nullptr) {
            worldContainerX = container->m_nGridX;
            worldContainerY = container->m_nGridY;
        }
    }
    const bool inAirShip = target->IsInAirShip();
    const bool inVehicle = target->IsInVehicle();
    FormatUtf16To(
        message.data(), 0x1ff, u"ContainerNo [%d], %s, %s, ParentContainerNo[%d], worldContainerXY[%d][%d]", containerNumber,
        inVehicle ? L"In Vehicle" : L"Out of Vehicle", inAirShip ? L"In AirShip" : L"Out of AirShip", parentContainerNumber,
        worldContainerX, worldContainerY
    );
    socket->SendSystemMessage(u"SYS", message.data());

    std::array<char16_t, 256> attribute{};
    sharedData->m_BaseAttribute.GetLogString(attribute.data());
    FormatUtf16To(message.data(), 0x1ff, u"Attribute info : [%s]", attribute.data());
    socket->SendSystemMessage(u"SYS", message.data());

    constexpr int kWorldLeft = -0x50000;
    constexpr int kWorldTop = -0x40000;
    const FVector mapPosition = target->GetPos();
    const int mapX = std::clamp(
        runtime::SubtractInt32Wrapping(runtime::Win64CvttDoubleToInt32(mapPosition.x), kWorldLeft) / 0x400, 0, 0x27f
    );
    const int mapY = std::clamp(
        runtime::SubtractInt32Wrapping(runtime::Win64CvttDoubleToInt32(mapPosition.y), kWorldTop) / 0x400, 0, 0x21f
    );
    std::array<char16_t, 256> mapMessage{};
    FormatUtf16To(
        mapMessage.data(), 0xff, u"TLMap [%d][%d] Inzone [%d]", mapX, mapY, static_cast<int>(target->GetInZoneID())
    );
    socket->SendSystemMessage(u"SYS", mapMessage.data());

    if (target->IsBuilder()) {
        target->briefingExDropPorb();
    }

    User* const auditBuilder = socket->GetUser();
    if (auditBuilder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 25> builderName{};
    std::array<char16_t, 15> builderAccount{};
    FVector builderPosition{};
    {
        L2_GUARD(*auditBuilder->m_lock);
        builderDbId = auditBuilder->GetDBID();
        builderAccountId = auditBuilder->GetAccountID();
        CopyBuilderText(builderName.data(), builderName.size(), auditBuilder->GetName());
        const std::u16string builderAccountText = SanitizeUtf16(std::u16string_view(auditBuilder->m_sAccountName.data()));
        CopyBuilderText(builderAccount.data(), builderAccount.size(), builderAccountText.c_str());
        builderPosition = auditBuilder->GetPos();
    }

    const char16_t* const targetName = target->GetName();
    const std::uint32_t targetAccountId = target->GetAccountID();
    const std::uint32_t targetDbId = target->GetDBID();
    const std::wstring targetAccount = ::Utf16ToWide(std::u16string_view(target->m_sAccountName.data()));
    // Log.Add(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,,,,,,,,,%s,%s,%s,%s,",
    //     static_cast<long long>(0x1f5),
    //     static_cast<long long>(builderDbId),
    //     static_cast<long long>(builderAccountId),
    //     static_cast<long long>(targetDbId),
    //     static_cast<long long>(targetAccountId),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.x)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.z)),
    //     builderName.data(),
    //     builderAccount.data(),
    //     targetName,
    //     targetAccount.c_str())
    // Log.Add(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,,,,,,,,,%s,%s,%s,%s,",
    //     static_cast<long long>(0x1f5),
    //     static_cast<long long>(builderDbId),
    //     static_cast<long long>(builderAccountId),
    //     static_cast<long long>(targetDbId),
    //     static_cast<long long>(targetAccountId),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.x)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.z)),
    //     builderName.data(),
    //     builderAccount.data(),
    //     Utf16ToWide(targetName).c_str(),
    //     targetAccount.c_str())
    Log.Add(
        LOG_BOTH, u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,,,,,,,,,%s,%s,%s,%s,",
        static_cast<long long>(0x1f5), static_cast<long long>(builderDbId), static_cast<long long>(builderAccountId),
        static_cast<long long>(targetDbId), static_cast<long long>(targetAccountId),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.x)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.y)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.z)), builderName.data(),
        builderAccount.data(), targetName, targetAccount.c_str()
    );
    return false;
}

} // namespace BuilderCmd

bool BuilderCmd_debug(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x0054dfbc.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//debug [name | .]");
        return false;
    }
    return BuilderCmd::CSCharacterInfoPacket(socket, tokens[0].data());
}

bool BuilderCmd_castleincome(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x004d5190.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    for (int residenceId = 0; residenceId < 10; ++residenceId) {
        CResidence* const residence = g_ResidenceDB.GetResidence(residenceId);
        std::array<char16_t, 64> message{};
        if (residence != nullptr && residence->IsCastle()) {
            FormatUtf16To(
                message.data(), message.size(), u"id[%d] : tax income[%I64d]/[%I64d]", residence->GetResidenceID(),
                static_cast<long long>(residence->m_data->m_nTaxIncome),
                static_cast<long long>(residence->m_data->m_nTaxIncomeTemp)
            );
        }
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

bool BuilderCmd_setcastleincome(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004ea424.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 4, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setcastleincome [id] [0..1] [1] [0..100000000]");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    const int selector = WindowsWtol(tokens[1].data());
    const int requiredOne = WindowsWtol(tokens[2].data());
    const std::int64_t amount = BuilderWindowsWtoi64(tokens[3].data());
    if (requiredOne != 1 || static_cast<std::uint32_t>(selector) > 1U ||
        static_cast<std::uint64_t>(amount) > UINT64_C(2000000000)) {
        socket->SendSystemMessage(u"SYS", u"//setcastleincome [id] [0..1] [1] [0..100000000]");
        return false;
    }

    CResidence* const residence = g_ResidenceDB.GetResidence(residenceId);
    std::array<char16_t, 64> message{};
    if (residence == nullptr) {
        FormatUtf16To(message.data(), message.size(), u"Cannot find residence, id [%d]", residenceId);
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    if (residence->IsCastle()) {
        if (selector == 0) {
            residence->m_data->m_nTaxIncome = amount;
        } else {
            residence->m_data->m_nTaxIncomeTemp = amount;
        }
        residence->SaveIncome(true, 1);
    } else if (residence->IsWorldAgit()) {
        if (selector == 0) {
            residence->m_data->m_nTaxIncome = amount;
        } else {
            residence->m_data->m_nTaxIncomeTemp = amount;
        }
        residence->SaveIncome(true, selector + 2);
    } else {
        return false;
    }

    FormatUtf16To(
        message.data(), message.size(), u"tax income[%I64d]", static_cast<long long>(residence->m_data->m_nTaxIncome)
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

bool BuilderCmd::settax(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004eaa6c.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//settax castle 0...100");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId != 0) {
        residence = g_ResidenceDB.GetResidence(residenceId);
    } else {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    }
    CCastle* const castle = residence != nullptr ? residence->CastCastle() : nullptr;
    if (castle == nullptr) {
        return false;
    }

    const int taxRate = WindowsWtol(tokens[1].data());
    if (static_cast<std::uint32_t>(taxRate) > 100U) {
        socket->SendSystemMessage(u"SYS", u"taxrate must be between 0 and 100");
        return false;
    }

    const int residenceType = castle->m_data->m_ResidenceType;
    castle->m_data->m_TaxInfoData[static_cast<std::size_t>(residenceType)].m_nTaxRate = taxRate;
    castle->SetTaxRates(taxRate, static_cast<CastleType::Enum>(residenceType));

    std::array<char16_t, 1024> message{};
    FormatUtf16To(
        message.data(), message.size(), u"castle[%d] : tax rate[%d]", castle->GetResidenceID(),
        castle->m_data->m_TaxInfoData[static_cast<std::size_t>(residenceType)].m_nTaxRate
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

bool BuilderCmd_updatecastleincome(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004ea140.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 32> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string accountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPosition);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//updatecastleincome castle 0...100");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    const int mode = WindowsWtol(tokens[1].data());
    CResidence* const residence = g_ResidenceDB.GetResidence(residenceId);
    if (residence == nullptr) {
        socket->SendSystemMessage(u"SYS", u"Cannot find residence.");
    } else if (residence->IsCastle()) {
        residence->SendResidenceTaxIncome(mode);
    }
    return false;
}

bool BuilderCmd::version(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x0056cb4c.
    L2_GUARD_FUNCTION();
    socket->SendSystemMessage(u"SYS", u"Server Binary Info");

    std::array<char16_t, 1024> message{};
    const std::wstring updateVersion = ::Utf16ToWide(std::u16string_view(g_BinaryInfo.updateVersion));
    FormatUtf16To(message.data(), message.size(), u"Server Update Version : %s", updateVersion.c_str());
    socket->SendSystemMessage(u"SYS", message.data());

    FormatUtf16To(message.data(), message.size(), u"Build Date : %s", CBuildDate::inst().BuildDateTime());
    socket->SendSystemMessage(u"SYS", message.data());

    FormatUtf16To(message.data(), message.size(), u"L2Protocol : %d", GetProtocolVersion());
    socket->SendSystemMessage(u"SYS", message.data());

    std::vector<std::u16string> parameters;
    parameters.emplace_back(u"version");
    db.RequestBuilderCommand(user->Id(), parameters);
    return false;
}

bool BuilderCmd_servername(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x004d52e0.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user != nullptr) {
        const std::u16string serverName = Utf16Text(std::u16string_view(g_PetitionSetting.wsWorldServerName)).String();
        socket->SendSystemMessage(u"SYS", serverName.c_str());
    }
    return user == nullptr;
}

bool BuilderCmd_show_iobuffer(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x004ead10. The live thread count is intentionally
    // reloaded after every nullable current-L2Server CNewMwsrQueue slot.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    socket->SendSystemMessage(u"SYS", u"Current IO Buffer Count");
    for (int threadId = 0; threadId < CThreadManager::GetThreadCount(); ++threadId) {
        std::array<char16_t, 512> message{};
        CNewMwsrQueue<DefaultIOBuffer>* const pool = g_IOBufferPools[threadId];
        if (pool == nullptr) {
            continue;
        }

        const int totalCount = pool->GetMaxSize();
        const int freeCount = pool->InstantSize();
        FormatUtf16To(message.data(), message.size(), u"T(%d) : Free(%d) / Total(%d)", threadId, freeCount, totalCount);
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

bool BuilderCmd::collision_test(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x004ea7e4.
    L2_GUARD_FUNCTION();
    socket->SendSystemMessage(u"SYS", u"Collision Test :");

    CSharedCreatureData* const data = user->m_data;
    std::array<char16_t, 256> message{};
    const auto sendInteger = [&message, socket](const char16_t* const format, const int value) {
        FormatUtf16To(message.data(), message.size(), format, value);
        socket->SendSystemMessage(u"SYS", message.data());
    };
    sendInteger(u"SubJobId : %d", data->m_nSubJobId);
    sendInteger(u"m_nSubJob0Class : %d", data->m_nSubJob0Class);
    sendInteger(u"m_nSubJob1Class : %d", data->m_nSubJob1Class);
    sendInteger(u"m_nSubJob2Class : %d", data->m_nSubJob2Class);
    sendInteger(u"m_nSubJob3Class : %d", data->m_nSubJob3Class);
    sendInteger(u"m_nClass : %d", static_cast<int>(data->m_nClass));

    FormatUtf16To(message.data(), message.size(), u"m_dCollisionRadius : %f", data->m_dCollisionRadius);
    socket->SendSystemMessage(u"SYS", message.data());
    FormatUtf16To(message.data(), message.size(), u"m_dCollisionHeight : %f", data->m_dCollisionHeight);
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

