bool BuilderCmd_settime(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004e5e28.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//settime hhmm");
        return false;
    }

    const int time = WindowsWtol(tokens[0].data());
    const int hour = time / 100;
    const int minute = time % 100;
    if (static_cast<std::uint32_t>(hour) >= 25U) {
        socket->SendSystemMessage(u"SYS", u"invalid hour");
    } else if (static_cast<std::uint32_t>(minute) >= 60U) {
        socket->SendSystemMessage(u"SYS", u"invalid minute");
    } else {
        g_L2Time.SetTime(static_cast<unsigned int>(hour * 60 + minute));
    }
    return false;
}

