bool BuilderCmd_setonetimequest(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004e44bc.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setonetimequest [quest id] [state]");
        return false;
    }

    const int questId = WindowsWtol(tokens[0].data());
    const int state = WindowsWtol(tokens[1].data());
    const bool lowRange = questId >= 0 && questId <= 0xff;
    const std::uint32_t highRangeOffset = static_cast<std::uint32_t>(questId) - UINT32_C(0x280f);
    if (!lowRange && highRangeOffset > UINT32_C(0x6ff) && questId != 0x2f0f) {
        socket->SendSystemMessage(u"SYS", u"quest id is out of range [0-255] | [10255-11023]");
        return false;
    }

    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string accountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
        static_cast<void>(builder->GetPos());
    }

    User* target = builder->m_spTarget.GetUser();
    if (target == nullptr) {
        target = builder;
    }
    {
        L2_GUARD(*target->m_lock);
        target->m_data->SetOneTimeFlag(questId, state == 1);
        db.SaveQuestInfo(target);
        if (state == 1 && g_ToDoListManager.IsDailyMissionQuest(questId)) {
            g_ToDoListManager.OnDailyMissionCheckAndUpdate(builder, E_DAILY_MISSION_TYPE_QUESTCOUNT);
        }
    }

    const std::uint32_t targetDbId = target->GetDBID();
    const std::uint32_t targetAccountId = target->GetAccountID();
    std::array<char16_t, 28> targetName{};
    std::array<char16_t, 16> targetAccount{};
    CopyBuilderText(targetName.data(), 0x19, target->GetName());
    const std::u16string targetAccountText(target->m_sAccountName.data());
    CopyBuilderText(targetAccount.data(), 0x0f, targetAccountText.c_str());
    const FVector targetPosition = target->GetPos();

    std::array<char16_t, 256> result{};
    FormatUtf16To(
        result.data(), result.size(), u"set onetimequest for (%s : %s) ( %d:%d )", targetName.data(), targetAccount.data(),
        questId, state
    );
    socket->SendSystemMessage(u"SYS", result.data());

    // Log.Add(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
    //     L"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
    //     static_cast<long long>(0x1fb),
    //     static_cast<long long>(builderDbId),
    //     static_cast<long long>(builderAccountId),
    //     static_cast<long long>(targetDbId),
    //     static_cast<long long>(targetAccountId),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.x)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.z)),
    //     static_cast<long long>(questId),
    //     static_cast<long long>(state),
    //     builderName.data(),
    //     builderAccount.data(),
    //     targetName.data(),
    //     targetAccount.data())
    Log.Add(
        LOG_BOTH,
        u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        u"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
        static_cast<long long>(0x1fb), static_cast<long long>(builderDbId), static_cast<long long>(builderAccountId),
        static_cast<long long>(targetDbId), static_cast<long long>(targetAccountId),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.x)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.y)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.z)), static_cast<long long>(questId),
        static_cast<long long>(state), builderName.data(), builderAccount.data(), targetName.data(), targetAccount.data()
    );
    return false;
}

bool BuilderCmd_setquest(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004e49c4.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 5> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setquest quest_id state [state2] [state3] [state4]");
        return false;
    }

    const int questId = WindowsWtol(tokens[0].data());
    const int state = WindowsWtol(tokens[1].data());
    const bool hasState2 = tokenCount > 2 && tokens[2][0] != L'\0';
    const bool hasState3 = tokenCount > 3 && tokens[3][0] != L'\0';
    const bool hasState4 = tokenCount > 4 && tokens[4][0] != L'\0';
    const int state2 = hasState2 ? WindowsWtol(tokens[2].data()) : 0;
    const int state3 = hasState3 ? WindowsWtol(tokens[3].data()) : 0;
    const int state4 = hasState4 ? WindowsWtol(tokens[4].data()) : 0;

    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string accountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
        static_cast<void>(builder->GetPos());
    }

    User* target = builder->m_spTarget.GetUser();
    if (target == nullptr) {
        target = builder;
    }

    bool success = true;
    std::uint32_t targetDbId = 0;
    std::uint32_t targetAccountId = 0;
    std::array<char16_t, 28> targetName{};
    std::array<char16_t, 16> targetAccount{};
    FVector targetPosition{};
    {
        L2_GUARD(*target->m_lock);
        CSharedCreatureData* const data = target->m_data;
        if (!data->HaveMemo(questId)) {
            static_cast<void>(data->SetMemo(questId));
        }
        if (!data->SetMemoState(questId, 0, state)) {
            success = false;
        } else {
            static_cast<void>(builder->AddQuestProgress(questId, 1));
            if (hasState2 && !data->SetMemoState(questId, 1, state2)) {
                success = false;
            } else if (hasState2 && hasState3 && !data->SetMemoState(questId, 2, state3)) {
                success = false;
            } else if (hasState2 && hasState3 && hasState4 && !data->SetMemoState(questId, 3, state4)) {
                success = false;
            }
        }
        if (success) {
            db.SaveQuestInfo(target);
            builder->SendQuestList(nullptr);
        }

        targetDbId = target->GetDBID();
        targetAccountId = target->GetAccountID();
        CopyBuilderText(targetName.data(), 0x19, target->GetName());
        const std::u16string accountText(target->m_sAccountName.data());
        CopyBuilderText(targetAccount.data(), 0x0f, accountText.c_str());
        targetPosition = target->GetPos();
    }

    const char16_t* messageFormat = u"setquest failed (%s : %s) ( %d: %d)";
    if (success) {
        if (!hasState2) {
            messageFormat = u"set quest for (%s : %s) (%d: %d)";
        } else if (!hasState3) {
            messageFormat = u"set quest for (%s : %s) (%d: %d %d)";
        } else if (!hasState4) {
            messageFormat = u"set quest for (%s : %s) (%d: %d %d %d)";
        } else {
            messageFormat = u"set quest for (%s : %s) (%d: %d %d %d %d)";
        }
    }
    std::array<char16_t, 256> result{};
    FormatUtf16To(
        result.data(), result.size(), messageFormat, targetName.data(), targetAccount.data(), questId, state, state2, state3,
        state4
    );
    socket->SendSystemMessage(u"SYS", result.data());

    // Log.Add(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
    //     L"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
    //     static_cast<long long>(0x1fc),
    //     static_cast<long long>(builderDbId),
    //     static_cast<long long>(builderAccountId),
    //     static_cast<long long>(targetDbId),
    //     static_cast<long long>(targetAccountId),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.x)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(targetPosition.z)),
    //     static_cast<long long>(questId),
    //     static_cast<long long>(state),
    //     builderName.data(),
    //     builderAccount.data(),
    //     targetName.data(),
    //     targetAccount.data())
    Log.Add(
        LOG_BOTH,
        u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        u"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
        static_cast<long long>(0x1fc), static_cast<long long>(builderDbId), static_cast<long long>(builderAccountId),
        static_cast<long long>(targetDbId), static_cast<long long>(targetAccountId),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.x)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.y)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(targetPosition.z)), static_cast<long long>(questId),
        static_cast<long long>(state), builderName.data(), builderAccount.data(), targetName.data(), targetAccount.data()
    );
    return false;
}

