bool BuilderCmd_reset_skill(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x0054a020.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    {
        L2_GUARD(*builder->m_lock);
        static_cast<void>(builder->GetDBID());
        static_cast<void>(builder->GetAccountID());
        std::array<char16_t, 28> builderName{};
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        std::array<char16_t, 16> builderAccount{};
        const std::u16string accountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
        static_cast<void>(builder->GetPos());
    }

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    static_cast<void>(ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount));

    User* target = nullptr;
    if (tokenCount == 0) {
        target = builder->m_spTarget.GetUser();
    } else {
        std::array<char16_t, 50> name{};
        CopyBuilderText(name.data(), name.size(), tokens[0].data());
        CSPointer<User> found = GetUserFromNameMap(g_nWorldId, std::u16string(name.data()));
        if (found) {
            target = found->CastUser();
        }
    }
    if (target == nullptr) {
        socket->SendSystemMessage(SystemMessageId::INCORRECT_TARGET);
        return false;
    }

    {
        L2_GUARD(*target->m_lock);
        {
            L2_GUARD(target->m_AcquiredSkillsSect);
            for (const auto& entry : target->m_AcquiredSkills) {
                const AcquiredSkillInfo& acquired = entry.second;
                if (acquired.m_bSaveToDB) {
                    target->SendDeletedSkillToDB(acquired.m_nId);
                }
            }
            target->_DeleteAllAcquireSkills(false);
        }
        // Source bug: the shipping handler grants the race and honor skills
        // to the Builder after clearing the target's skills.
        // See BUILDER-RESETSKILL-001 in docs/SHIPPING_BUG_FIXES.md.
        // builder->AcquireSkills(g_SkillAcquireDB.GetAcquirableRaceSkills(builder->m_data->m_Race), true, false)
        // builder->AcquireAllHonorsSkill()
        target->AcquireSkills(g_SkillAcquireDB.GetAcquirableRaceSkills(target->m_data->m_Race), true, false);
        target->AcquireAllHonorsSkill();
    }
    target->ValidateChanged(VB_MAX);
    target->ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_BUILDERCMD});
    return false;
}

