bool BuilderCmd_diet(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004eb530.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//diet [target]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"켬") == 0) {
        if (user->m_bDietMode) {
            socket->SendSystemMessage(u"SYS", u"Currently, you are on diet mode.");
            return false;
        }
        {
            L2_GUARD(*user->m_lock);
            user->m_bDietMode = true;
            static_cast<void>(user->ValidateCarryWeight());
        }
        socket->SendSystemMessage(u"SYS", u"Diet mode on.");
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"끔") == 0) {
        if (!user->m_bDietMode) {
            socket->SendSystemMessage(u"SYS", u"Currently, you are not on diet mode..");
            return false;
        }
        {
            L2_GUARD(*user->m_lock);
            user->m_bDietMode = false;
            static_cast<void>(user->ValidateCarryWeight());
        }
        socket->SendSystemMessage(u"SYS", u"Diet mode off.");
    }
    return false;
}

