bool BuilderCmd_hide(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x0054d108.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//hide [on|off]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"켬") == 0) {
        if (user->m_data->m_bGMInvisible) {
            socket->SendSystemMessage(u"SYS", u"Currently, you cannot be seen.");
            return false;
        }
        {
            L2_GUARD(*user->m_lock);
            user->m_data->m_bGMInvisible = true;
        }

        // RTTI/vtables at 0x00e89a18 and 0x00e97600 prove this local
        // polymorphic action owner.
        class SummonFunc final : public AbstractSummonFunc {
        public:
            bool Do(CSummon* summon) override {
                // Current L2Server 0x004d55a0.
                if (summon->IsVisible()) {
                    static_cast<void>(summon->SetVisible(false));
                }
                return true;
            }
        } function;
        static_assert(sizeof(SummonFunc) == sizeof(void*));
        FOR_ALL_SUMMON_PET_IN_SUMMON_LIST2(user, function);

        const FVector position = user->GetPos();
        const unsigned int inZoneId = user->GetInZoneID();
        static_cast<void>(user->TeleportToLocation(
            runtime::Win64CvttDoubleToInt32(position.x), runtime::Win64CvttDoubleToInt32(position.y),
            runtime::Win64CvttDoubleToInt32(position.z), inZoneId, 0x10000, TeleportSourceType::BuilderCmd, user, 0
        ));
        socket->SendSystemMessage(u"SYS", u"Now, you cannot be seen.");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") != 0 &&
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"끔") != 0) {
        return false;
    }
    if (!user->m_data->m_bGMInvisible) {
        socket->SendSystemMessage(u"SYS", u"Currently, you can be seen.");
        return false;
    }
    {
        L2_GUARD(*user->m_lock);
        user->m_data->m_bGMInvisible = false;
    }

    FOR_ALL_SUMMON_PET_IN_SUMMON_LIST(user, summon, {
        if (summon->IsAlive()) {
            static_cast<void>(summon->SetVisible(true));
        }
    });

    const FVector position = user->GetPos();
    const unsigned int inZoneId = user->GetInZoneID();
    static_cast<void>(user->TeleportToLocation(
        runtime::Win64CvttDoubleToInt32(position.x), runtime::Win64CvttDoubleToInt32(position.y),
        runtime::Win64CvttDoubleToInt32(position.z), inZoneId, 0x10000, TeleportSourceType::BuilderCmd, user, 0
    ));

    const char16_t* const userName = user->GetName();
    const std::uint32_t accountId = user->GetAccountID();
    const std::uint32_t databaseId = user->GetDBID();
    const std::u16string accountName(user->m_sAccountName.data());
    // Log.Add(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
    //     L",,,,,,,,,,,%s,%s,,,",
    //     static_cast<long long>(0x21c),
    //     static_cast<long long>(databaseId),
    //     static_cast<long long>(accountId),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(position.x)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(position.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(position.z)),
    //     userName,
    //     accountName.c_str())
    // Log.Add(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
    //     L",,,,,,,,,,,%s,%s,,,",
    //     static_cast<long long>(0x21c),
    //     static_cast<long long>(databaseId),
    //     static_cast<long long>(accountId),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(position.x)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(position.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(position.z)),
    //     Utf16ToWide(userName).c_str(),
    //     accountName.c_str())
    Log.Add(
        LOG_BOTH,
        u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
        u",,,,,,,,,,,%s,%s,,,",
        static_cast<long long>(0x21c), static_cast<long long>(databaseId), static_cast<long long>(accountId),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(position.x)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(position.y)),
        static_cast<long long>(runtime::Win64CvttDoubleToInt32(position.z)), userName, accountName.c_str()
    );

    if (g_bUseAutoSoulShotUI) {
        std::memset(user->m_nAutoSoulshotFlags, 0, sizeof(user->m_nAutoSoulshotFlags));
        user->m_nAutoSoulshotFlag = 0;
        for (int index = 0; index < 4; ++index) {
            AutoSoulShotUi& ui = user->m_AutoSoulShotUi[index];
            ui.m_ItemClassID = 0;
            ui.m_IsActiveState = 1;
            user->GetSocket()->Send("chddd", 0xfe, 0x0c, ui.m_ItemClassID, ui.m_IsActiveState, index);
        }
    }
    socket->SendSystemMessage(u"SYS", u"Now, you can be seen.");
    return false;
}

