const char16_t* SendObjectNameToUser(const int objectId, CUserSocket* const socket) {
    // Current L2Server 0x004ed39c.
    L2_GUARD_FUNCTION();
    const char16_t* const objectName = g_ObjectDB.GetName(objectId);
    if (objectName != nullptr) {
        std::array<char16_t, 512> message{};
        FormatUtf16To(message.data(), message.size(), u"Summon [%s]", objectName);
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return objectName;
}

bool _teleport_to_npc(User* const user, CUserSocket* const socket, const int npcClassId) {
    // Current L2Server 0x004ed0f8.
    L2_GUARD_FUNCTION();
    if (npcClassId < 1000001) {
        socket->SendSystemMessage(u"SYS", u"object must be npc");
        return false;
    }

    CNPC* const npc = GetTeleportableNpc(static_cast<int>(user->GetInZoneID()), npcClassId);
    if (npc == nullptr) {
        socket->SendSystemMessage(u"SYS", u"NPC does not exist");
        return false;
    }
    if (!npc->IsBoss() && !npc->m_data->m_bUnique && !npc->IsWorldTrap()) {
        socket->SendSystemMessage(u"SYS", u"invalid NPC");
        return false;
    }

    const FVector npcPosition = npc->GetPos();
    User* const builder = socket->GetUser();
    if (builder != nullptr) {
        if (!builder->m_data->m_bGMInvisible) {
            socket->SendSystemMessage(u"SYS", u"please hide on first");
            return false;
        }
        socket->SendSystemMessage(u"SYS", u"You will teleport to unique npc");

        const double randomX = ::genrand64_real2();
        const double randomY = ::genrand64_real2();
        builder->StopMove();
        const int x = runtime::AddInt32Wrapping(
            runtime::Win64CvttDoubleToInt32(npcPosition.x), runtime::Win64CvttDoubleToInt32(randomX * 21.0 + 0.0)
        );
        const int y = runtime::AddInt32Wrapping(
            runtime::Win64CvttDoubleToInt32(npcPosition.y), runtime::Win64CvttDoubleToInt32(randomY * 21.0 + 0.0)
        );
        const unsigned int inZoneId = builder->GetInZoneID();
        const int z = CWorld::Inst().GetGeo()->FindGround(x, y, runtime::Win64CvttDoubleToInt32(npcPosition.z));
        static_cast<void>(
            builder->TeleportToLocation(x, y, z, inZoneId, 0x10000, TeleportSourceType::BuilderCmd, builder, 0)
        );
    }
    return true;
}

