bool BuilderCmd_worlddebug(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x004e77e0.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    std::array<char16_t, 28> userName{};
    std::array<char16_t, 16> accountName{};
    FVector position{};
    {
        L2_GUARD(*user->m_lock);
        static_cast<void>(user->GetDBID());
        static_cast<void>(user->GetAccountID());
        CopyBuilderText(userName.data(), 0x19, user->GetName());
        const std::u16string accountText(user->m_sAccountName.data());
        CopyBuilderText(accountName.data(), 0x0f, accountText.c_str());
        position = user->GetPos();
    }

    const std::int32_t x = runtime::Win64CvttDoubleToInt32(position.x);
    const std::int32_t y = runtime::Win64CvttDoubleToInt32(position.y);
    const std::int32_t z = runtime::Win64CvttDoubleToInt32(position.z);
    std::array<char16_t, 20480> heading{};
    FormatUtf16To(
        heading.data(), heading.size(), u"worlddata at (%d, %d) : index (%d, %d)", x, y, (x >> 4) & 7, (y >> 4) & 7
    );
    user->SendSystemMessage(u"worlddebug", heading.data());

    const std::int32_t zoneX = (runtime::AddInt32Wrapping(x, 0x50000) >> 15) + 10;
    const std::int32_t zoneY = (runtime::AddInt32Wrapping(y, 0x40000) >> 15) + 10;
    CGeoZone* const zone = CWorld::Inst().GetGeo()->GetZone(zoneX, zoneY);
    if (zone == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     "cannot get zone (%d, %d) at file[%s], line[%d]",
        //     x,
        //     y,
        //     "BuilderCmdHandler.cpp",
        //     0xfdf)
        // Previous: L2_LOG_ERROR(Log,
        //     "cannot get zone (%d, %d) at file[%s], line[%d]",
        //     x, y, "BuilderCmdHandler.cpp", 0xfdf)
        L2_LOG_ERROR(
            Log,
            "[builder geodata] No zone contains world position (%d, %d); "
            "the worlddebug command was aborted.",
            x, y
        );
        return false;
    }

    CGeoSector* const sector = zone->GetSector((x >> 7) & 0xff, (y >> 7) & 0xff);
    if (sector == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     "cannot get sector (%d, %d) at file[%s], line[%d]",
        //     x,
        //     y,
        //     "BuilderCmdHandler.cpp",
        //     0xfe8)
        // Previous: L2_LOG_ERROR(Log,
        //     "cannot get sector (%d, %d) at file[%s], line[%d]",
        //     x, y, "BuilderCmdHandler.cpp", 0xfe8)
        L2_LOG_ERROR(
            Log,
            "[builder geodata] No sector contains world position (%d, %d); "
            "the worlddebug command was aborted.",
            x, y
        );
        return false;
    }

    std::array<char16_t, 20476> detail{};
    if ((sector->m_BooleanFlag & 1U) != 0) {
        FormatUtf16To(detail.data(), detail.size(), u"solid %d", BuilderGeoHeight(sector->m_DefaultCell.m_data));
        user->SendSystemMessage(u"worlddebug", detail.data());
        return false;
    }

    CGeoCell* const cells = CWorld::Inst().GetGeo()->GetCellArray(zoneX, zoneY);
    if (cells == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     "cannot get cell (%d, %d, %d) at file[%s], line[%d]",
        //     x,
        //     y,
        //     z,
        //     "BuilderCmdHandler.cpp",
        //     0xffa)
        // Previous: L2_LOG_ERROR(Log,
        //     "cannot get cell (%d, %d, %d) at file[%s], line[%d]",
        //     x, y, z, "BuilderCmdHandler.cpp", 0xffa)
        L2_LOG_ERROR(
            Log,
            "[builder geodata] Cell data is unavailable at world position "
            "(%d, %d, %d); the worlddebug command was aborted.",
            x, y, z
        );
        return false;
    }

    int firstIndex = 0;
    int lastIndex = 0;
    static_cast<void>(CWorld::Inst().GetGeo()->GetCellIndexes(x, y, firstIndex, lastIndex));
    for (int index = firstIndex; index < lastIndex; ++index) {
        FormatUtf16To(detail.data(), detail.size(), u"%d", BuilderGeoHeight(cells[index].m_data));
        user->SendSystemMessage(u"worlddebug", detail.data());
    }
    return false;
}

