bool BuilderCmd_show(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004e7d70.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    constexpr char16_t usage[] = u"//show (superpoint name | territory | npcpos)";
    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", usage);
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"superpoint") == 0) {
        // The current branch accepts only the cleared second carrier. A
        // normal non-empty superpoint name therefore takes the usage path.
        if (tokenCount < 2 || tokens[1][0] != L'\0') {
            socket->SendSystemMessage(u"SYS", usage);
            return false;
        }
        g_npcserver.Send("cddS", 0x50, static_cast<int>(user->Id()), 1, std::u16string(tokens[1].data()).c_str());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"territory") == 0) {
        g_npcserver.Send("cdd", 0x50, static_cast<int>(user->Id()), 2);
        return false;
    }

    user->SendSystemMessage(u"sys", usage);
    return false;
}

bool BuilderCmd_gotopn(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004e7ff8.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    std::array<char16_t, 28> userName{};
    std::array<char16_t, 16> accountName{};
    FVector builderPosition{};
    {
        L2_GUARD(*user->m_lock);
        static_cast<void>(user->GetDBID());
        static_cast<void>(user->GetAccountID());
        CopyBuilderText(userName.data(), 0x19, user->GetName());
        const std::u16string accountText(user->m_sAccountName.data());
        CopyBuilderText(accountName.data(), 0x0f, accountText.c_str());
        builderPosition = user->GetPos();
    }
    static_cast<void>(builderPosition);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//gotopn PathNodeIndex");
        return false;
    }

    const int signedIndex = WindowsWtol(tokens[0].data());
    if (signedIndex < 0) {
        return false;
    }
    const unsigned int index = static_cast<unsigned int>(signedIndex);
    if (index >= g_pnWorld.GetMaxIndex()) {
        return false;
    }

    const FVector position = g_pnWorld.GetPathNodePos(signedIndex);
    user->MoveToLocation(
        runtime::Win64CvttDoubleToInt32(position.x), runtime::Win64CvttDoubleToInt32(position.y),
        runtime::Win64CvttDoubleToInt32(position.z), CCreature::UsePathFind
    );
    return false;
}

bool BuilderCmd_qmove(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004e84c0.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    std::array<char16_t, 28> userName{};
    std::array<char16_t, 16> accountName{};
    FVector builderPosition{};
    {
        L2_GUARD(*user->m_lock);
        static_cast<void>(user->GetDBID());
        static_cast<void>(user->GetAccountID());
        CopyBuilderText(userName.data(), 0x19, user->GetName());
        const std::u16string accountText(user->m_sAccountName.data());
        CopyBuilderText(accountName.data(), 0x0f, accountText.c_str());
        builderPosition = user->GetPos();
    }
    static_cast<void>(builderPosition);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//qmove [1|2|3]");
        return false;
    }

    const int mode = WindowsWtol(tokens[0].data());
    CNPC* const target = user->m_spTarget.GetNPC();
    if (target == nullptr) {
        return false;
    }
    FVector position = target->GetPos();

    if (mode == 2) {
        {
            CUserSocket* const userSocket = user->GetSocket();
            const std::int32_t z = runtime::Win64CvttDoubleToInt32(position.z);
            const std::int32_t y = runtime::Win64CvttDoubleToInt32(position.y);
            const std::int32_t x = runtime::Win64CvttDoubleToInt32(position.x);
            userSocket->Send(
                "cddddddd", 0x2f, static_cast<int>(target->Id()), x, runtime::AddInt32Wrapping(y, 100), z, x, y, z
            );
        }
        {
            CUserSocket* const userSocket = user->GetSocket();
            const std::int32_t z = runtime::Win64CvttDoubleToInt32(position.z);
            const std::int32_t y = runtime::Win64CvttDoubleToInt32(position.y);
            const std::int32_t x = runtime::Win64CvttDoubleToInt32(position.x);
            userSocket->Send(
                "cddddddd", 0x2f, static_cast<int>(target->Id()), x, runtime::AddInt32Wrapping(y, 50), z,
                runtime::AddInt32Wrapping(x, 100), runtime::AddInt32Wrapping(y, 50), z
            );
        }
        {
            CUserSocket* const userSocket = user->GetSocket();
            const std::int32_t z = runtime::Win64CvttDoubleToInt32(position.z);
            const std::int32_t y = runtime::Win64CvttDoubleToInt32(position.y);
            const std::int32_t x = runtime::Win64CvttDoubleToInt32(position.x);
            userSocket->Send(
                "cddddddd", 0x2f, static_cast<int>(target->Id()), runtime::AddInt32Wrapping(x, 50),
                runtime::SubtractInt32Wrapping(y, 50), z, runtime::AddInt32Wrapping(x, 50),
                runtime::AddInt32Wrapping(y, 50), z
            );
        }
        {
            CUserSocket* const userSocket = user->GetSocket();
            const std::int32_t z = runtime::Win64CvttDoubleToInt32(position.z);
            const std::int32_t y = runtime::Win64CvttDoubleToInt32(position.y);
            const std::int32_t x = runtime::Win64CvttDoubleToInt32(position.x);
            userSocket->Send(
                "cddddddd", 0x2f, static_cast<int>(target->Id()), runtime::AddInt32Wrapping(x, 50), y, z, x, y, z
            );
        }
        return false;
    }

    std::array<FVector, 2> offsets{};
    if (mode == 1) {
        offsets[0] = FVector{0.0, 100.0, 0.0};
        offsets[1] = FVector{100.0, 0.0, 0.0};
    } else if (mode == 3) {
        offsets[0] = FVector{0.0, 100.0, 0.0};
        offsets[1] = FVector{0.0, -20.0, 0.0};
    } else {
        return false;
    }

    for (std::size_t iteration = 0; iteration < 3; ++iteration) {
        const FVector previous = position;
        const FVector& offset = offsets[iteration & 1U];
        position.x = position.x + offset.x;
        position.y = position.y + offset.y;
        position.z = position.z + offset.z;
        CUserSocket* const userSocket = user->GetSocket();
        userSocket->Send(
            "cddddddd", 0x2f, static_cast<int>(target->Id()), runtime::Win64CvttDoubleToInt32(position.x),
            runtime::Win64CvttDoubleToInt32(position.y), runtime::Win64CvttDoubleToInt32(position.z),
            runtime::Win64CvttDoubleToInt32(previous.x), runtime::Win64CvttDoubleToInt32(previous.y),
            runtime::Win64CvttDoubleToInt32(previous.z)
        );
    }
    return false;
}

