bool BuilderCmd_setclass(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004e8e40.
    L2_GUARD_FUNCTION();
    User* builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    int builderLevel = 0;
    {
        L2_GUARD(*builder->m_lock);
        builderLevel = builder->m_data->m_nBuilder;
    }
    if (builderLevel == 0 || builderLevel > 2) {
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setclass classId");
        return false;
    }

    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        user->SendSystemMessage(u"SYS", u"Target is not user.");
        return false;
    }

    const int classId = WindowsWtol(tokens[0].data());
    const std::uint32_t classIdBits = static_cast<std::uint32_t>(classId);
    if (classIdBits >= 0xc0U) {
        user->SendSystemMessage(u"SYS", u"classid is out of range.");
        return false;
    }
    if (classIdBits - 0x3aU < 0x1eU || classIdBits - 0x77U < 4U || classIdBits == 0x89U || classIdBits == 0x8aU) {
        user->SendSystemMessage(u"SYS", u"classid is NPC.");
        return false;
    }
    if (target->m_data->m_nSubJobId == 0 && (classIdBits == 0x87U || classIdBits == 0x88U)) {
        user->SendSystemMessage(u"SYS", u"Inspector or Judicator is not enough for main job");
        return false;
    }

    builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }
    std::array<char16_t, 32> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    {
        L2_GUARD(*builder->m_lock);
        static_cast<void>(builder->GetDBID());
        static_cast<void>(builder->GetAccountID());
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string accountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderPosition);

    static_cast<void>(target->ChangeClass(static_cast<ClassType>(classId), 0));
    // Source bug: the shipping handler updates the Builder's mentor state and
    // saves the Builder's own class, sub job and DB ID instead of the target's.
    // See BUILDER-SETCLASS-001 in docs/SHIPPING_BUG_FIXES.md.
    // if (target->m_data->m_nLevel > 84 && classId > 0x8a) builder->UpdateMentorByLevelUp(true, 0)
    // DxSetClass packet(builder->GetDBID(), builder->m_data->m_nSubJobId, builder->m_data->m_nClass)
    // db.RequestTPacketProcess(builder->m_data->m_nWorldId, 0x23, 0x0c, packet)
    if (target->m_data->m_nLevel > 84 && classId > 0x8a) {
        target->UpdateMentorByLevelUp(true, 0);
    }

    const int targetClass = static_cast<int>(target->m_data->m_nClass);
    const int targetSubJobId = target->m_data->m_nSubJobId;
    const int targetDbId = static_cast<int>(target->GetDBID());
    DxSetClass packet(targetDbId, targetSubJobId, targetClass);
    db.RequestTPacketProcess(target->m_data->m_nWorldId, 0x23, 0x0c, packet);
    return false;
}

