bool BuilderCmd_teleport(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004e9c34.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//teleport x y [z]");
        return false;
    }

    const int x = WindowsWtol(tokens[0].data());
    const int y = WindowsWtol(tokens[1].data());
    int z = CWorld::Inst().GetGeo()->FindGround(x, y, 16000);
    if (tokenCount > 2 && tokens[2][0] != L'\0') {
        z = WindowsWtol(tokens[2].data());
    }

    user->StopMove();
    if (user->m_data->m_moveType == CMT_FLY || user->m_AreaMod.m_bIsUnderWater) {
        const unsigned int inZoneId = user->GetInZoneID();
        static_cast<void>(user->TeleportToLocation(x, y, z, inZoneId, 0x10000, TeleportSourceType::BuilderCmd, user, 0));
    } else {
        CWorld& world = CWorld::Inst();
        const unsigned int inZoneId = user->GetInZoneID();
        const int groundedZ = world.GetGeo()->FindGround(x, y, z);
        static_cast<void>(
            user->TeleportToLocation(x, y, groundedZ, inZoneId, 0x10000, TeleportSourceType::BuilderCmd, user, 0)
        );
    }
    return false;
}

