bool BuilderCmd_Dice(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x0054e174.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPositionSnapshot{};
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string accountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
        builderPositionSnapshot = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPositionSnapshot);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//dice dice_classid number");
        return false;
    }

    const int diceClassId = WindowsWtol(tokens[0].data());
    int number = WindowsWtol(tokens[1].data());
    if (number < 1 || number > 6) {
        const int projected = runtime::Win64CvttDoubleToInt32(::genrand64_real1() * 100.0 + 0.0);
        number = projected % 6 + 1;
    }

    FVector dicePosition(builder->m_data->m_Pos);
    dicePosition.z = static_cast<double>(CWorld::Inst().GetGeo()->FindGround(
        runtime::Win64CvttDoubleToInt32(dicePosition.x), runtime::Win64CvttDoubleToInt32(dicePosition.y),
        runtime::Win64CvttDoubleToInt32(dicePosition.z)
    ));
    const int angleDegrees = runtime::Win64CvttDoubleToInt32(::genrand64_real2() * 360.0 + 0.0);
    const double angle = (static_cast<double>(angleDegrees) * 3.14) / 360.0;
    const int distance = runtime::Win64CvttDoubleToInt32(::genrand64_real2() * 16.0 + 30.0);
    dicePosition =
        FVector{static_cast<double>(runtime::Win64CvttDoubleToInt32(std::cos(angle) * static_cast<double>(distance))) +
                dicePosition.x,
            static_cast<double>(runtime::Win64CvttDoubleToInt32(std::sin(angle) * static_cast<double>(distance))) +
                dicePosition.y,
            dicePosition.z + 0.0};

    const int broadcastDistance = builder->GetBroadcastDist(0x1000);
    const int diceZ = runtime::Win64CvttDoubleToInt32(dicePosition.z);
    const std::uint32_t serverId = builder->GetServerId();
    const FVector broadcastPosition = builder->GetPos();
    g_ptlUserMap->BroadcastToNeighborDist(
        builder, 0x5000, broadcastPosition, broadcastDistance, "cdddddd", 0xda, serverId, diceClassId, number,
        runtime::Win64CvttDoubleToInt32(dicePosition.x), runtime::Win64CvttDoubleToInt32(dicePosition.y), diceZ
    );
    return false;
}

