bool BuilderCmd_time_limit(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004f5880.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string accountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPosition);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//time_limit char_name (Add | Del) min");
        return false;
    }

    const int minutes = WindowsWtol(tokens[2].data());
    if (minutes <= 0) {
        builder->SendSystemMessage(u"SYS", u"//time_limit char_name (Add | Del) min");
        return false;
    }

    std::array<char16_t, 1025> characterName{};
    std::array<char16_t, 10> action{};
    CopyBuilderText(characterName.data(), characterName.size(), tokens[0].data());
    const std::size_t actionLength =
        std::min<std::size_t>(std::char_traits<char16_t>::length(tokens[1].data()), action.size() - 1U);
    std::char_traits<char16_t>::copy(action.data(), tokens[1].data(), actionLength);

    int requestType = 0;
    if (CompareBuilderTextPrefixIgnoreCase(action.data(), u"Add", 3) == 0) {
        requestType = 1;
    } else if (CompareBuilderTextPrefixIgnoreCase(action.data(), u"Del", 3) == 0) {
        requestType = 2;
    } else {
        builder->SendSystemMessage(u"SYS", u"//time_limit char_name (Add | Del) min");
        return false;
    }

    const std::uint32_t serverId = builder->GetServerId();
    db.RequestChangeTimeLimit(
        builder, std::u16string(characterName.data()).c_str(), requestType, minutes, static_cast<int>(serverId)
    );
    return false;
}

bool BuilderCmd_time_info(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x0054e610.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        const std::u16string accountText(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPosition);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//time_info [char_name | .(target)]");
        return false;
    }

    std::array<char16_t, 1025> characterName{};
    CopyBuilderText(characterName.data(), characterName.size(), tokens[0].data());
    if (characterName[0] == L'.') {
        CCreature* const selected = builder->m_spTarget.GetCreature();
        if (selected == nullptr || !selected->IsPC()) {
            builder->SendSystemMessage(u"SYS", u"//time_info [char_name | .(target)]");
            return false;
        }
        CopyBuilderText(characterName.data(), characterName.size(), selected->GetName());
    }

    const std::u16string targetName = std::u16string(characterName.data());
    const std::u16string hostLowerNameUtf16 = LowercaseGameName(targetName);
    CSPointer<User> targetReference = GetUserFromNameMap(g_nWorldId, hostLowerNameUtf16);
    User* const target = targetReference.get();
    if (target != nullptr && g_nPlayTimeLimit > 0) {
        std::array<char16_t, 512> message{};
        CUserSocket* const playTimeSocket = target->GetSocket();
        const int socketPlayTime = playTimeSocket->GetSocketPlayTime();
        const int remaining = runtime::SubtractInt32Wrapping(g_nPlayTimeLimit, socketPlayTime);
        FormatUtf16To(
            message.data(), 0x1ff, u"Remain green time :: [%d] hour [%d] min", remaining / 3600, (remaining % 3600) / 60
        );
        socket->SendSystemMessage(u"SYS", message.data());

        CUserSocket* const characterTimeSocket = target->GetSocket();
        const int characterPlayTime = characterTimeSocket->GetCharacterPlayTime();
        CUserSocket* const modeSocket = target->GetSocket();
        const wchar_t* const mode = modeSocket->m_bForceLogin ? L"[limitless]" : L"";
        FormatUtf16To(
            message.data(), 0x1ff, u"this char play time :: [%d] hour [%d] min, %s", characterPlayTime / 3600,
            (characterPlayTime % 3600) / 60, mode
        );
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

