bool BuilderCmd_register_tb_pledge(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0052f7ec.
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do register_tb_pledge command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//register_tb_pledge agit pledge npctype");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid residence");
        return false;
    }

    CTeamBattleAgit* teamBattle = nullptr;
    if (residence->IsWorldAgit()) {
        teamBattle = residence->CastWorldAgit()->CastTeamBattleAgit();
    }
    if (teamBattle == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid team battle pledge");
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[1].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        socket->SendSystemMessage(u"SYS", u"you can use this command only after the pledge is loaded");
        return false;
    }
    if (pledge->IsWaitingTransferMaster()) {
        socket->SendSystemMessage(u"SYS", u"cannot register while waiting to transfer master");
        return false;
    }

    const int npcType = WindowsWtol(tokens[2].data());
    bool alreadyRegistered = false;
    const TEAM_BATTLE_COLOR color = teamBattle->GetColor(runtime::Int32FromBits(pledge->GetDbId()), alreadyRegistered);
    if (color == TBC_NOT_DETERMINED) {
        socket->SendSystemMessage(u"SYS", u"team battle entry list is full");
        return false;
    }

    if (!alreadyRegistered) {
        db.RequestNewTeamBattleAgitPledge(teamBattle, pledge.get(), user, nullptr, static_cast<int>(color), npcType);
    } else {
        socket->SendSystemMessage(u"SYS", u"you are already registered");
    }
    socket->SendSystemMessage(u"SYS", u"builder command[register_tb_pledge] accepted");
    return false;
}

