bool BuilderCmd_set_tb(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00529f80.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do set_tb command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//set_tb agit field value");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    CWorldAgit* const worldAgit = residence != nullptr ? residence->CastWorldAgit() : nullptr;
    CTeamBattleAgit* const teamBattle = worldAgit != nullptr ? worldAgit->CastTeamBattleAgit() : nullptr;
    if (teamBattle == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid agit or not team battle agit");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"battle_royal_time") == 0) {
        teamBattle->m_nBattleRoyalTimeout = WindowsWtol(tokens[2].data());
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"final_time") == 0) {
        teamBattle->m_nFinalTimeout = WindowsWtol(tokens[2].data());
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"waiting_time") == 0) {
        teamBattle->m_nWaitingTimeout = WindowsWtol(tokens[2].data());
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"winner") == 0) {
        std::u16string pledgeName = std::u16string(tokens[2].data());
        CSPointer<CPledge> pledge =
            CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
        if (!pledge) {
            socket->SendSystemMessage(u"SYS", u"invalid pledge name");
            return false;
        }
        static_cast<void>(runtime::raw_atomic::CompareExchangeI32(
            &teamBattle->m_nWinnerPledgeId, runtime::Int32FromBits(pledge->GetDbId()), -1
        ));
    } else {
        socket->SendSystemMessage(u"SYS", u"invalid team battle field");
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"builder command[set_tb] accepted");
    return false;
}

bool BuilderCmd_summon_illusion(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00541e14.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//summon_illusion item_class_id count");
        return false;
    }

    const int itemClassId = runtime::Win64CvttDoubleToInt32(std::wcstod(Utf16ToWide(tokens[0].data()).c_str(), nullptr));
    CObject* const object = g_ObjectDB.GetObjectW(itemClassId, false);
    int remainingCount = WindowsWtol(tokens[1].data());
    if (object == nullptr || !object->IsItem()) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Item[%d] is not exist.",
        //     L"BuilderCmdHandler.cpp",
        //     0x2981,
        //     itemClassId)
        // Previous: L2_LOG_ERROR(Log,
        //     L"[%s][%d] Item[%d] is not exist.",
        //     L"BuilderCmdHandler.cpp", 0x2981, itemClassId)
        L2_LOG_ERROR(
            Log,
            u"[builder inventory] Item class %d is undefined or is not an "
            u"item; the summon-illusion command is rejected.",
            itemClassId
        );
        return false;
    }

    CItem* const prototype = static_cast<CItem*>(object);
    {
        L2_WRITE_GUARD(user->m_inv);
        if (!CSharedItemData::IsStackable(prototype->m_data->m_ItemConsumeType)) {
            while (remainingCount > 0) {
                CItem* const item = g_ObjectDB.CreateItem(itemClassId);
                if (item == nullptr) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[%s][%d] CreateItem Failed. item class[%d] nCount[%d]",
                    //     L"BuilderCmdHandler.cpp",
                    //     0x29c1,
                    //     itemClassId,
                    //     remainingCount)
                    // Previous: L2_LOG_ERROR(Log,
                    //     L"[%s][%d] CreateItem Failed. item class[%d] nCount[%d]",
                    //     L"BuilderCmdHandler.cpp", 0x29c1, itemClassId,
                    //     remainingCount)
                    L2_LOG_ERROR(
                        Log,
                        u"[builder inventory] Cannot create item class %d "
                        u"while %d items remain; this item is not delivered.",
                        itemClassId, remainingCount
                    );
                } else if (!user->m_inv.Push(item->m_data->index)) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     "inven push failed at file[%s], line[%d]",
                    //     "BuilderCmdHandler.cpp",
                    //     0x29c7)
                    // Previous: L2_LOG_ERROR(Log,
                    //     "inven push failed at file[%s], line[%d]",
                    //     "BuilderCmdHandler.cpp", 0x29c7)
                    L2_LOG_ERROR(
                        Log,
                        "[builder inventory] Cannot add item class %d "
                        "(object %d) to character %u; this item was not "
                        "delivered.",
                        itemClassId, item->m_data->index, user->GetDBID()
                    );
                }
                --remainingCount;
            }
        } else {
            CSharedItemData* itemData = user->m_inv.GetFirst();
            while (itemData != nullptr) {
                if (remainingCount < 1) {
                    break;
                }

                CSharedItemData* const next = itemData->Next();
                CSPointer<CItem> item = CItemFactory::Inst().FindObjectSP(itemData->index);
                if (!item) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[%s][%d]ERROR, Cannot Find item object. "
                    //     L"item classid[%d][%s]",
                    //     L"BuilderCmdHandler.cpp",
                    //     0x2994,
                    //     itemData->m_nClassID,
                    //     user->GetName())
                    // Previous: L2_LOG_ERROR(Log,
                    //     L"[%s][%d]ERROR, Cannot Find item object. "
                    //     L"item classid[%d][%s]", L"BuilderCmdHandler.cpp",
                    //     0x2994, itemData->m_nClassID, user->GetName())
                    // L2_LOG_ERROR(Log,
                    //     L"[builder inventory] Character '%s' has inventory "
                    //     L"record for item class %d whose object is missing. "
                    //     L"the scan continues.",
                    //     user->GetName(),
                    //     itemData->m_nClassID)
                    L2_LOG_ERROR(
                        Log,
                        u"[builder inventory] Character '%s' has inventory "
                        u"record for item class %d whose object is missing; "
                        u"the scan continues.",
                        user->GetName(), itemData->m_nClassID
                    );
                } else if (itemData->m_nClassID == itemClassId) {
                    {
                        L2_GUARD(*item->m_lock);
                        itemData->m_nCount =
                            runtime::AddInt64Wrapping(itemData->m_nCount, static_cast<std::int64_t>(remainingCount));
                    }
                    remainingCount = 0;
                }
                itemData = next;
            }

            if (remainingCount > 0) {
                CItem* const item = g_ObjectDB.CreateItem(itemClassId);
                if (item == nullptr) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[%s][%d] CreateItem Failed. item class[%d] nCount[%d]",
                    //     L"BuilderCmdHandler.cpp",
                    //     0x29b5,
                    //     itemClassId,
                    //     remainingCount)
                    // Previous: L2_LOG_ERROR(Log,
                    //     L"[%s][%d] CreateItem Failed. item class[%d] nCount[%d]",
                    //     L"BuilderCmdHandler.cpp", 0x29b5, itemClassId,
                    //     remainingCount)
                    L2_LOG_ERROR(
                        Log,
                        u"[builder inventory] Cannot create stackable item "
                        u"class %d with amount %d; it is not delivered.",
                        itemClassId, remainingCount
                    );
                } else {
                    if (!item->SetAmount(remainingCount)) {
                        // Log.Add(
                        //     LOG_ERROR,
                        //     L"[%S][%d] item amount is invalid[%d][%d]",
                        //     "BuilderCmdHandler.cpp",
                        //     0x29a9,
                        //     runtime::Int32FromBits(
                        //         static_cast<std::uint32_t>(
                        //             item->m_data->m_nCount)),
                        //     remainingCount)
                        // Previous: L2_LOG_ERROR(Log,
                        //     L"[%S][%d] item amount is invalid[%d][%d]",
                        //     "BuilderCmdHandler.cpp", 0x29a9,
                        //     runtime::Int32FromBits(static_cast<std::uint32_t>(
                        //         item->m_data->m_nCount)), remainingCount)
                        L2_LOG_ERROR(
                            Log,
                            u"[builder inventory] Item class %d rejected amount "
                            u"%d (stored amount %d); inventory insertion is "
                            u"still attempted.",
                            itemClassId, remainingCount,
                            runtime::Int32FromBits(static_cast<std::uint32_t>(item->m_data->m_nCount))
                        );
                    }
                    if (!user->m_inv.Push(item->m_data->index)) {
                        // Log.Add(
                        //     LOG_ERROR,
                        //     "inven push failed at file[%s], line[%d]",
                        //     "BuilderCmdHandler.cpp",
                        //     0x29b0)
                        // Previous: L2_LOG_ERROR(Log,
                        //     "inven push failed at file[%s], line[%d]",
                        //     "BuilderCmdHandler.cpp", 0x29b0)
                        L2_LOG_ERROR(
                            Log,
                            "[builder inventory] Cannot add stackable item "
                            "class %d (object %d) to character %u; this item "
                            "was not delivered.",
                            itemClassId, item->m_data->index, user->GetDBID()
                        );
                    }
                }
            }
        }
    }
    return false;
}

