bool BuilderCmd_get_petition_disable_time(CUserSocket*, User* user, char16_t*) {
    // Current L2Server 0x004d67bc.
    L2_GUARD_FUNCTION();
    if (petitionCli.disabletime1 == petitionCli.disabletime2) {
        user->GetSocket()->SendSystemMessage(u"SYS", u"petition is always possible");
    } else {
        const runtime::SystemTime now = runtime::GetLocalTimeNow();
        std::array<char16_t, 20476> message{};
        FormatUtf16To(
            message.data(), message.size(),
            u"petition system is disabled from %d to %d. "
            u"current time %d:%d",
            petitionCli.disabletime1, petitionCli.disabletime2, static_cast<int>(now.wHour), static_cast<int>(now.wMinute)
        );
        user->GetSocket()->SendSystemMessage(u"SYS", message.data());
    }

    user->SendSystemMessage(u"SYS", petitionCli.IsDisableTime() ? u"petition disabled now" : u"petition enabled now");
    return false;
}

bool BuilderCmd_tutorial_event(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004f710c.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//tutorial_event (move|view_change|...)");
        return false;
    }

    const char16_t* const eventName = tokens[0].data();
    int event = 0;
    if (CompareBuilderTextIgnoreCase(eventName, u"move") == 0) {
        event = 0x00000001;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"view_change") == 0) {
        event = 0x00000002;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"wheel_scroll") == 0) {
        event = 0x00000004;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"right_click") == 0) {
        event = 0x00000008;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"wheel_click") == 0) {
        event = 0x00000010;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"hp1_3") == 0) {
        event = 0x00000100;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"die1_9") == 0) {
        event = 0x00000200;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"level5") == 0) {
        event = 0x00000400;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"level7") == 0) {
        event = 0x00000800;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"level15") == 0) {
        event = 0x04000000;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"level20") == 0) {
        event = 0x00001000;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"level35") == 0) {
        event = 0x01000000;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"level75") == 0) {
        event = 0x02000000;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"level39") == 0) {
        event = 0x00004000;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"level76") == 0) {
        event = 0x00008000;
    } else if (CompareBuilderTextIgnoreCase(eventName, u"questtab") == 0) {
        event = 0x00002000;
    } else {
        user->SendSystemMessage(u"[TUTORIAL]", u"invalid event");
        return false;
    }

    g_npcserver.Send("cdd", 0x34, user->m_data->index, event);
    return false;
}

