bool BuilderCmd_spawn_npcs(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004f7eec.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//spawn_npcs count ai");
        return false;
    }

    std::uint32_t remaining = static_cast<std::uint32_t>(WindowsWtol(tokens[0].data()));
    std::int32_t spawned = 0;
    while (remaining != 0) {
        --remaining;

        std::int32_t npcIndex = 0;
        do {
            npcIndex = std::rand() % runtime::SubtractInt32Wrapping(CNPC::s_nMaxID, 1000000);
            if (npcIndex < 0 || static_cast<std::uint32_t>(npcIndex) >= g_bRegisteredNpcID.size()) {
                throw std::out_of_range("invalid xarray<T> subscript");
            }
        } while (g_bRegisteredNpcID[static_cast<std::uint32_t>(npcIndex)] == 0);

        const FVector currentPosition = user->m_data->m_Pos;
        const char16_t* const npcName = g_ObjectDB.GetName(npcIndex + 1000000);
        const std::int32_t z = runtime::Win64CvttDoubleToInt32(currentPosition.z);
        const std::int32_t y = runtime::Win64CvttDoubleToInt32(currentPosition.y);
        const std::int32_t x = runtime::Win64CvttDoubleToInt32(currentPosition.x);
        const int randomY = std::rand();
        const int randomX = std::rand();
        const FVector spawnPosition(
            static_cast<double>(runtime::AddInt32Wrapping(x, randomX % 500 - 250)),
            static_cast<double>(runtime::AddInt32Wrapping(y, randomY % 500 - 250)), static_cast<double>(z)
        );
        const char16_t* const aiName = tokens[1][0] != u'\0' ? tokens[1].data() : u"default_npc";
        const int inZoneId = static_cast<int>(user->GetInZoneID());
        NpcServerUtil::SendRequestNpcSpawn(npcName, spawnPosition, inZoneId, aiName, 0x10000);

        spawned = runtime::AddInt32Wrapping(spawned, 1);
        if (spawned % 1000 == 0) {
            std::this_thread::sleep_for(std::chrono::milliseconds(2000));
        }
    }
    return false;
}

bool BuilderCmd_spawn_all_npc(CUserSocket*, User* user, char16_t*) {
    // Current L2Server 0x004f8274.
    L2_GUARD_FUNCTION();
    const FVector basePosition = user->m_data->m_Pos;
    int column = 0;
    int row = 0;
    int spawned = 0;
    std::int32_t classId = 1000000;
    std::uint32_t npcIndex = 0;
    do {
        if (npcIndex >= g_bRegisteredNpcID.size()) {
            throw std::out_of_range("invalid xarray<T> subscript");
        }
        if (g_bRegisteredNpcID[npcIndex] != 0) {
            const double z = basePosition.z + 0.0;
            const double gridY = basePosition.y + static_cast<double>(row) * 50.0;
            const double gridX = static_cast<double>(column) * 50.0 + basePosition.x;
            ++column;
            if (column == 40) {
                column = 0;
                ++row;
            }

            const char16_t* const npcName = g_ObjectDB.GetName(classId);
            const int randomY = std::rand();
            const int randomX = std::rand();
            const FVector spawnPosition(
                static_cast<double>(
                    runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(gridX), randomX % 500 - 250)
                ),
                static_cast<double>(
                    runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(gridY), randomY % 500 - 250)
                ),
                static_cast<double>(runtime::Win64CvttDoubleToInt32(z))
            );
            const int inZoneId = static_cast<int>(user->GetInZoneID());
            NpcServerUtil::SendRequestNpcSpawn(npcName, spawnPosition, inZoneId, u"default_npc", 0x10000);

            ++spawned;
            if (spawned == (spawned / 1000) * 1000) {
                std::this_thread::sleep_for(std::chrono::milliseconds(5000));
            }
        }
        ++classId;
        ++npcIndex;
    } while (classId < 0x0fde80);
    return false;
}

bool BuilderCmd_show_clan_info(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0052fdfc.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//show_clan_info pledge_name");
        return false;
    }

    const int worldId = user->m_data->m_nWorldId;
    std::u16string pledgeName = std::u16string(tokens[0].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(worldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        db.RequestLoadPledge(worldId, tokens[0].data());
        socket->SendSystemMessage(u"SYS", u"pledge name is not valid or not loaded yet");
        return false;
    }

    const int oustTime = pledge->GetFieldValue(4);
    const int challengeTime = pledge->GetFieldValue(1);
    const int dbMemberCount = pledge->GetDbMemberCount();
    const int memberCount = pledge->GetMemberCount();
    const int nameValue = pledge->GetNameValue();
    const int totalLevel = pledge->GetTotalLevel();
    const int pledgeLevel = static_cast<int>(pledge->GetPledgeLevel());
    const char16_t* const masterName = pledge->GetPledgeMasterName();
    const char16_t* const currentPledgeName = pledge->GetPledgeName();

    std::array<char16_t, 1024> message{};
    FormatUtf16To(
        message.data(), message.size(),
        u"name[%s], master[%s], level[%d], member level sum[%d], "
        u"namevalue[%d], connected no[%d/%d(total)], "
        u"challengeTime[%d], oustTime[%d]",
        currentPledgeName, masterName, pledgeLevel, totalLevel, nameValue, memberCount, dbMemberCount, challengeTime,
        oustTime
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

