bool BuilderCmd_reset_clan_leader(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0054fdd8.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do reset_clan_leader command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//reset_clan_leader pledge_name leader_name");
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[0].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        db.RequestLoadPledge(g_nWorldId, tokens[0].data());
        socket->SendSystemMessage(u"SYS", u"pledge name is not valid or not loaded yet");
        return false;
    }

    CSPointer<User> newLeader = GetUserFromNameMap(g_nWorldId, std::u16string(tokens[1].data()));
    if (!newLeader) {
        socket->SendSystemMessage(u"SYS", u"user is not in l2 world");
        return false;
    }

    CPledge* const userPledge = newLeader->GetPledge();
    if (userPledge == nullptr || pledge->GetDbId() != userPledge->GetDbId()) {
        socket->SendSystemMessage(u"SYS", u"user is not pledge member");
        return false;
    }

    User* const oldMaster = pledge->GetMaster();
    if (oldMaster != nullptr) {
        oldMaster->m_data->m_bPledgeMaster = false;
        oldMaster->ParamChanged(PCB_USER | PCB_CHAR_BUILDERCMD);
    }
    pledge->SetMasterDbId(newLeader->GetDBID());
    pledge->SetPledgeMasterName(Utf16ToWide(newLeader->GetName()).c_str());
    pledge->SetMaster(newLeader.get());
    newLeader->SetPledge(pledge.get());
    newLeader->ParamChanged(PCB_USER | PCB_CHAR_BUILDERCMD);
    pledge->Save(0x13);
    pledge->OpenAllWindowPacket();
    socket->SendSystemMessage(u"SYS", u"builder command[reset_clan_leader] accepted");
    return false;
}

