bool BuilderCmd_declare_truce(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00531568.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do declare_truce command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//declare_truce clan_1 clan2");
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[0].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        db.RequestLoadPledge(g_nWorldId, tokens[0].data());
        socket->SendSystemMessage(u"SYS", u"pledge name is not valid or not loaded yet");
        return false;
    }

    std::u16string enemyPledgeName = std::u16string(tokens[1].data());
    CSPointer<CPledge> enemyPledge =
        CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(enemyPledgeName.data()));
    if (!enemyPledge) {
        db.RequestLoadPledge(g_nWorldId, tokens[1].data());
        socket->SendSystemMessage(u"SYS", u"pledge name is not valid or not loaded yet");
        return false;
    }

    if (!pledge->DidDeclareWar(static_cast<int>(enemyPledge->Id()))) {
        socket->Send(
            "chccS", 0x62, SystemMessageId::WAR_NOT_DECLARED_ON_NAMED_CLAN, 1, 0, std::u16string(tokens[1].data()).c_str()
        );
        return false;
    }
    if (pledge->IsInCombatMode() || enemyPledge->IsInCombatMode()) {
        socket->SendSystemMessage(SystemMessageId::CANNOT_CANCEL_WAR_DECLARATION_CLAN_MEMBER_IN_COMBAT);
        return false;
    }

    int transaction = 3;
    if (!pledge->BeginTransaction(&transaction)) {
        socket->SendSystemMessage(SystemMessageId::CLAN_OPERATION_ALREADY_IN_PROGRESS);
        return false;
    }

    DxCancelWar packet(
        static_cast<int>(pledge->Id()), static_cast<int>(pledge->GetDbId()), static_cast<int>(enemyPledge->Id()),
        static_cast<int>(enemyPledge->GetDbId()), static_cast<int>(socket->GetServerId()), runtime::crt::Time32Now(),
        true, 0
    );
    db.RequestTPacketProcess(g_nWorldId, 0x20, static_cast<int>(sizeof(packet)), packet);
    return false;
}

bool BuilderCmd_disband(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00531cc0.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do disband command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//disband clan_name");
        return false;
    }

    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::u16string pledgeName = std::u16string(tokens[0].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        db.RequestLoadPledge(g_nWorldId, tokens[0].data());
        socket->SendSystemMessage(u"SYS", u"clan name is invalid or not loaded yet, retry later please.");
        return false;
    }

    const char16_t* message = nullptr;
    if (pledge->GetAllianceDbId() != 0) {
        message = u"cannot dismiss clan, the clan is alliance member.";
    } else if (pledge->IsInWar()) {
        message = u"cannot dismiss clan, the clan is in war.";
    } else if (pledge->GetWorldAgit() != nullptr) {
        message = u"cannot dismiss clan, the clan has an agit.";
    } else if (pledge->GetCastle() != nullptr) {
        message = u"cannot dismiss clan, the clan has a castle.";
    } else if (pledge->GetFortress() != nullptr) {
        message = u"cannot dismiss clan, the clan has a fortress.";
    } else if (CCastle::IsCastleSiegeRegistered(pledge.get(), builder->m_data->m_nWorldId)) {
        message = u"cannot dismiss clan, the clan is implicated in castle siege";
    } else {
        db.RequestDeletePledgeByTimer(pledge.get());
        message = u"builder command[disband] accepted";
    }
    socket->SendSystemMessage(u"SYS", message);
    return false;
}

