bool BuilderCmd_snoop(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x005509e0.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//snoop [char name | .] [ON | OFF]");
        return false;
    }

    std::array<char16_t, 25> characterName{};
    CopyBuilderText(characterName.data(), characterName.size(), tokens[0].data());
    auto lowerCharacterName = [&characterName]() { return LowercaseGameName(characterName.data()); };
    std::u16string lookupName = lowerCharacterName();

    if (CompareBuilderTextIgnoreCase(lookupName.c_str(), u".") == 0) {
        CCreature* const selected = user->m_spTarget.GetCreature();
        if (selected == nullptr) {
            socket->SendSystemMessage(u"SYS", u"target is not in the world.");
            socket->SendSystemMessage(u"SYS", u"//snoop [char name | .] [no | off]");
            return false;
        }
        CopyBuilderText(characterName.data(), characterName.size(), selected->GetName());
        lookupName = lowerCharacterName();
    }

    CSPointer<User> target = GetUserFromNameMap(g_nWorldId, lookupName);
    std::array<char16_t, 512> message{};
    if (!target) {
        FormatUtf16To(message.data(), message.size(), u"(snp)%s is not in the world.", lookupName.c_str());
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"on") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[1].data(), u"켬") == 0) {
        if (user->m_nSnoopClientId > 0) {
            CCreature* const currentClient =
                g_CreatureSmartIdManager.GetObjectW(static_cast<std::uint32_t>(user->m_nSnoopClientId));
            if (currentClient != nullptr && currentClient->IsPC()) {
                FormatUtf16To(
                    message.data(), message.size(), u"(snp)you are already snooping %s.%s", lookupName.c_str(),
                    currentClient->GetName()
                );
                socket->SendSystemMessage(u"SYS", message.data());
                return false;
            }
            user->m_nSnoopClientId = 0;
        }

        if (target->m_nSnoopGmId > 0) {
            CCreature* const currentSnoopGm =
                g_CreatureSmartIdManager.GetObjectW(static_cast<std::uint32_t>(target->m_nSnoopGmId));
            const bool currentSnoopGmIsPc = currentSnoopGm != nullptr && currentSnoopGm->IsPC();
            if (currentSnoopGmIsPc) {
                FormatUtf16To(
                    message.data(), message.size(), u"(snp)%s is being snooped by %s.", lookupName.c_str(),
                    currentSnoopGm->GetName()
                );
            } else {
                FormatUtf16To(
                    message.data(), message.size(),
                    u"(snp)%s was being snooped, now snooper's not exist. please retry snooping.", lookupName.c_str()
                );
            }
            socket->SendSystemMessage(u"SYS", message.data());
            if (!currentSnoopGmIsPc) {
                target->SetSnoop(0);
            }
            return false;
        }

        const std::uint32_t targetBuilderLevel = static_cast<std::uint32_t>(target->CastUser()->m_data->m_nBuilder);
        const std::uint32_t builderLevel = static_cast<std::uint32_t>(user->m_data->m_nBuilder);
        if (targetBuilderLevel == 0 || builderLevel <= targetBuilderLevel) {
            FormatUtf16To(message.data(), message.size(), u"Now, you are snooping %s.", lookupName.c_str());
            socket->SendSystemMessage(u"SYS", message.data());
            target->SetSnoop(static_cast<int>(user->Id()));
        } else {
            FormatUtf16To(message.data(), message.size(), u"You cannot snoop higher GM.");
            socket->SendSystemMessage(u"SYS", message.data());
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"off") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[1].data(), u"끔") == 0) {
        if (target->m_nSnoopGmId == 0) {
            FormatUtf16To(message.data(), message.size(), u"(snp)%s is snooped by no one.", lookupName.c_str());
            socket->SendSystemMessage(u"SYS", message.data());
            return false;
        }
        if (target->m_nSnoopGmId == static_cast<int>(user->Id())) {
            FormatUtf16To(message.data(), message.size(), u"Now, you end snooping %s.", lookupName.c_str());
            socket->SendSystemMessage(u"SYS", message.data());
            target->SetSnoop(0);
            return false;
        }

        CCreature* const currentSnoopGm =
            g_CreatureSmartIdManager.GetObjectW(static_cast<std::uint32_t>(target->m_nSnoopGmId));
        if (currentSnoopGm != nullptr && currentSnoopGm->IsPC()) {
            FormatUtf16To(
                message.data(), message.size(), u"(snp)%s's snoop on %s is closed.", user->GetName(), lookupName.c_str()
            );
            socket->SendSystemMessage(u"SYS", message.data());
        }
        target->SetSnoop(0);
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"//snoop [char name | .] [no | off]");
    return false;
}

bool BuilderCmd_quiet(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004f8a20.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//quiet (on|off)");
        return false;
    }

    const char16_t* result = nullptr;
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"켬") == 0) {
        if (!g_bQuietWorld) {
            g_bQuietWorld = true;
            result = u"Quiet world ON";
        } else {
            result = u"Already quiet world ON";
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"끔") == 0) {
        if (g_bQuietWorld) {
            g_bQuietWorld = false;
            result = u"Quiet world OFF";
        } else {
            result = u"Already quiet world OFF";
        }
    } else {
        socket->SendSystemMessage(u"SYS", g_bQuietWorld ? u"Currently, Quiet world ON" : u"Currently, Quiet world OFF");
        result = u"//quiet [on|off]";
    }
    socket->SendSystemMessage(u"SYS", result);
    return false;
}

