bool BuilderCmd_blockuser(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00551298.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//blockuser flag target_name");
        return false;
    }

    const int requestType = WindowsWtol(tokens[0].data());
    if (requestType == 0) {
        CSPointer<User> target = GetUserFromNameMap(g_nWorldId, std::u16string(tokens[1].data()));
        if (target) {
            user->GetSocket()->SendSystemMessage(u"SYS", u"cannot block GM");
        } else if (static_cast<int>(user->m_BlockListMap.size()) < 0x201) {
            db.RequestAddBlockList(user, tokens[1].data(), false);
        } else {
            // Log.Add(
            //     LOG_ERROR,
            //     L"block list overflow. char id [%d]",
            //     static_cast<int>(user->GetDBID()))
            // Previous: L2_LOG_ERROR(Log,
            //     L"block list overflow. char id [%d]",
            //     static_cast<int>(user->GetDBID()))
            L2_LOG_ERROR(
                Log,
                u"[builder block list] Character %d already has 513 blocked "
                u"names; the new entry is not added.",
                static_cast<int>(user->GetDBID())
            );
        }
        return false;
    }
    if (requestType == 1) {
        if (user->IsInBlockList(tokens[1].data())) {
            db.RequestDeleteBlockList(user, tokens[1].data());
        } else {
            // Log.Add(
            //     LOG_ERROR,
            //     L"remove block list cannot find char. char name [%d][%S]",
            //     static_cast<int>(user->GetDBID()),
            //     tokens[1].data())
            // Previous: L2_LOG_ERROR(Log,
            //     L"remove block list cannot find char. char name [%d][%S]",
            //     static_cast<int>(user->GetDBID()), tokens[1].data())
            // L2_LOG_ERROR(Log,
            //     L"[builder block list] Character %d cannot remove '%S': the "
            //     L"name is not blocked.",
            //     static_cast<int>(user->GetDBID()),
            //     tokens[1].data())
            L2_LOG_ERROR(
                Log,
                u"[builder block list] Character %d cannot remove '%s': the "
                u"name is not blocked.",
                static_cast<int>(user->GetDBID()), tokens[1].data()
            );
        }
        return false;
    }
    if (requestType == 2) {
        user->SendBlockList();
        return false;
    }

    // Log.Add(
    //     LOG_ERROR,
    //     L"user[%d] request blockpacket but unknown type [%d]",
    //     static_cast<int>(user->GetDBID()),
    //     requestType)
    // Previous: L2_LOG_ERROR(Log,
    //     L"user[%d] request blockpacket but unknown type [%d]",
    //     static_cast<int>(user->GetDBID()), requestType)
    L2_LOG_ERROR(
        Log,
        u"[builder block list] Character %d requested unsupported operation "
        u"%d; no block-list action was performed.",
        static_cast<int>(user->GetDBID()), requestType
    );
    return false;
}

bool BuilderCmd_disband2(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x00558e10.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//disband2 alliance_name");
        return false;
    }

    if (socket->GetUser() == nullptr) {
        return true;
    }

    CSPointer<CAlliance> alliance = g_AllianceNameMap.FindObject(g_nWorldId, std::u16string(tokens[0].data()));
    if (!alliance) {
        socket->SendSystemMessage(u"SYS", u"alliance name is invalid.");
        return false;
    }

    std::vector<CPledge*> memberPledges;
    alliance->GetAllMemberPledge(memberPledges);
    for (CPledge* const memberPledge : memberPledges) {
        if (memberPledge->HaveCastleUnderSiege() || memberPledge->GetFortressUnderDefenceSiege() != nullptr ||
            memberPledge->GetFortressUnderOffenceSiege() != nullptr) {
            socket->SendSystemMessage(u"SYS", u"member pledge is now participating in castle siege");
            return false;
        }
    }

    CPledge* const masterPledge = alliance->GetMasterPledge();
    db.RequestDismissAlliance(nullptr, alliance.get(), masterPledge);
    socket->SendSystemMessage(u"SYS", u"builder command[disband2] accepted");
    return false;
}

