bool BuilderCmd_show_alliance_info(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00559d00.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//show_alliance_info alliance_name");
        return false;
    }

    CSPointer<CAlliance> alliance = g_AllianceNameMap.FindObject(g_nWorldId, std::u16string(tokens[0].data()));
    if (!alliance) {
        socket->SendSystemMessage(u"SYS", u"alliance name is not valid");
        return false;
    }

    int totalDatabaseMembers = 0;
    int totalLiveMembers = 0;
    int memberPledgeCount = 0;
    int memberBlobLength = 0;
    const char16_t* const allianceName = alliance->m_data->m_sAllianceName;
    std::u16string targetMasterPledgeName;
    std::u16string targetMasterName;
    std::array<char, 0x5000> memberBlob;
    std::vector<CPledge*> memberPledges;
    alliance->GetAllMemberPledge(memberPledges);

    for (CPledge* const memberPledge : memberPledges) {
        const char16_t* const pledgeName = memberPledge->GetPledgeName();
        const char16_t* const pledgeMasterName = memberPledge->GetPledgeMasterName();
        const std::u16string targetPledgeName = std::u16string(pledgeName);
        const std::u16string targetPledgeMasterName = std::u16string(pledgeMasterName);
        const int databaseMemberCount = memberPledge->GetDbMemberCount();
        const int liveMemberCount = memberPledge->GetMemberCount();
        if (memberPledge->GetDbId() == alliance->m_data->m_nMasterPledgeDbId) {
            targetMasterPledgeName = targetPledgeName;
            targetMasterName = targetPledgeMasterName;
        }

        const std::uint32_t pledgeLevelBits = memberPledge->GetPledgeLevel();
        const int pledgeStatus = memberPledge->GetStatus();
        const int assembledLength = ::Assemble(
            memberBlob.data() + memberBlobLength, runtime::SubtractInt32Wrapping(0x5000, memberBlobLength), "SddSdd",
            targetPledgeName.c_str(), pledgeStatus, runtime::Int32FromBits(pledgeLevelBits),
            targetPledgeMasterName.c_str(), databaseMemberCount, liveMemberCount
        );
        memberBlobLength = runtime::AddInt32Wrapping(memberBlobLength, assembledLength);
        totalDatabaseMembers = runtime::AddInt32Wrapping(totalDatabaseMembers, databaseMemberCount);
        totalLiveMembers = runtime::AddInt32Wrapping(totalLiveMembers, liveMemberCount);
        memberPledgeCount = runtime::AddInt32Wrapping(memberPledgeCount, 1);
    }

    CUserSocket* const outputSocket = user->GetSocket();
    if (outputSocket == nullptr) {
        return false;
    }

    outputSocket->SendSystemMessage(SystemMessageId::ALLIANCE_INFORMATION_HEADING);
    outputSocket->Send("chccS", 0x62, SystemMessageId::ALLIANCE_NAME_ENTRY, 1, 0, allianceName);
    outputSocket->Send(
        "chccScS", 0x62, SystemMessageId::ALLIANCE_LEADER_AND_CLAN_ENTRY, 2, 0, targetMasterPledgeName.c_str(), 0x0c,
        targetMasterName.c_str()
    );
    outputSocket->Send(
        "chcchch", 0x62, SystemMessageId::ONLINE_AND_TOTAL_MEMBER_COUNTS, 2, 0x15,
        runtime::Int16FromBits(static_cast<std::uint32_t>(totalLiveMembers)), 0x15,
        runtime::Int16FromBits(static_cast<std::uint32_t>(totalDatabaseMembers))
    );
    outputSocket->SendSystemMessage_d(SystemMessageId::ALLIANCE_CLAN_COUNT_ENTRY, memberPledgeCount);
    outputSocket->SendSystemMessage(SystemMessageId::AFFILIATED_CLAN_INFORMATION_HEADING);

    const std::uint8_t* memberCursor = reinterpret_cast<const std::uint8_t*>(memberBlob.data());
    for (int index = 0; index < memberPledgeCount; ++index) {
        std::array<char16_t, 28> pledgeName;
        std::array<char16_t, 28> pledgeMasterName;
        std::memset(pledgeName.data(), 0, 0x32);
        std::memset(pledgeMasterName.data(), 0, 0x32);
        int pledgeStatus = 0;
        int pledgeLevel = 0;
        int databaseMemberCount = 0;
        int liveMemberCount = 0;
        memberCursor = ::Disassemble(
            memberCursor, "SddSdd", 0x32, pledgeName.data(), &pledgeStatus, &pledgeLevel, 0x32, pledgeMasterName.data(),
            &databaseMemberCount, &liveMemberCount
        );
        static_cast<void>(pledgeStatus);

        outputSocket->Send("chccS", 0x62, SystemMessageId::CLAN_NAME_ENTRY, 1, 0, pledgeName.data());
        outputSocket->Send("chccS", 0x62, SystemMessageId::CLAN_LEADER_ENTRY, 1, 0x0c, pledgeMasterName.data());
        outputSocket->SendSystemMessage_d(SystemMessageId::CLAN_LEVEL_ENTRY, pledgeLevel);
        outputSocket->Send(
            "chcchch", 0x62, SystemMessageId::ONLINE_AND_TOTAL_MEMBER_COUNTS, 2, 0x15,
            runtime::Int16FromBits(static_cast<std::uint32_t>(liveMemberCount)), 0x15,
            runtime::Int16FromBits(static_cast<std::uint32_t>(databaseMemberCount))
        );
        if (index != memberPledgeCount - 1) {
            outputSocket->SendSystemMessage(SystemMessageId::ALLIANCE_CLAN_ENTRY_SEPARATOR);
        }
    }
    outputSocket->SendSystemMessage(SystemMessageId::ALLIANCE_OR_CLAN_WAR_LIST_FOOTER);
    return false;
}

bool BuilderCmd_delete_alliance_member(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x005597a4.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do delete_alliance_member command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//delete_alliance_member alliance_name pledge_name");
        return false;
    }

    CSPointer<CAlliance> alliance = g_AllianceNameMap.FindObject(g_nWorldId, std::u16string(tokens[0].data()));
    if (!alliance) {
        socket->SendSystemMessage(u"SYS", u"alliance name is not valid");
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[1].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        db.RequestLoadPledge(g_nWorldId, tokens[1].data());
        socket->SendSystemMessage(u"SYS", u"pledge name is not valid or not loaded yet");
        return false;
    }

    // Source bug: the shipping handler compares with CObject::GetDBID, which
    // is 0 for an alliance, so a real member is always rejected.
    // See BUILDER-ALLIANCE-MEMBER-001 in docs/SHIPPING_BUG_FIXES.md.
    // const unsigned int allianceDatabaseId = alliance->GetDBID()
    const unsigned int allianceDatabaseId = alliance->m_data->m_nDbId;
    if (pledge->GetAllianceDbId() != static_cast<int>(allianceDatabaseId)) {
        socket->SendSystemMessage(u"SYS", u"pledge is not alliance member");
        return false;
    }

    const std::uint32_t pledgeDatabaseId = pledge->GetDbId();
    alliance->DeleteMemberPledge(pledgeDatabaseId);
    pledge->SetAlliance(nullptr, true);
    return false;
}

