bool BuilderCmd_ssqinfo(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x005515e8.
    L2_GUARD_FUNCTION();
    socket->SendSystemMessage(u"SYS", u"[status of seven sign quest]");

    std::array<wchar_t, 256> winnerText;
    const SSQPart::type winner = SSQSystem::inst().GetWinner();
    if (winner == SSQPart::NONE) {
        std::wcscpy(winnerText.data(), L"none");
    } else if (winner == SSQPart::TWILIGHT) {
        std::wcscpy(winnerText.data(), L"twilight");
    } else if (winner == SSQPart::DAWN) {
        std::wcscpy(winnerText.data(), L"dawn");
    }

    std::array<wchar_t, 256> statusText{};
    const SSQStatus::type status = SSQSystem::inst().GetCurrentStatus();
    if (status == SSQStatus::EVENT) {
        std::wcscpy(statusText.data(), L"event");
    } else if (status == SSQStatus::ACCOUNTING) {
        std::wcscpy(statusText.data(), L"accounting");
    } else if (status == SSQStatus::SEAL_EFFECT) {
        std::wcscpy(statusText.data(), L"seal_effect");
    } else {
        std::wcscpy(statusText.data(), L"none");
    }

    std::array<char16_t, 2044> message;
    FormatUtf16To(
        message.data(), 0x800, u" + round number=[%d], current status=[%s], winner=[%s]", SSQSystem::inst().GetRoundNumber(),
        statusText.data(), winnerText.data()
    );
    socket->SendSystemMessage(u"SYS", message.data());

    const int cycleMode = SSQSystem::inst().GetCycleMode();
    if (cycleMode == 0) {
        const int fullCycleDays = static_cast<int>(
            static_cast<double>(runtime::MultiplyInt32Wrapping(SSQSystem::inst().GetHalfCycleInterval(), 2)) / 86400.0
        );
        FormatUtf16To(message.data(), 0x800, u" + cycle mode : default, full cycle : %d day", fullCycleDays);
    } else if (cycleMode == 1) {
        FormatUtf16To(
            message.data(), 0x800, u" + cycle mode : quick, half cycle = %d minute",
            SSQSystem::inst().GetHalfCycleInterval() / 60
        );
    } else if (cycleMode == 2) {
        FormatUtf16To(message.data(), 0x800, u" + cycle mode : manual");
    }
    socket->SendSystemMessage(u"SYS", message.data());

    const DateTime eventStart = TimeValueToDateTime(TimeValue(SSQSystem::inst().GetEventStartTime(), 0));
    const DateTime eventEnd = TimeValueToDateTime(TimeValue(SSQSystem::inst().GetEventEndTime(), 0));
    const DateTime sealStart = TimeValueToDateTime(TimeValue(SSQSystem::inst().GetSealEffectTime(), 0));
    const DateTime sealEnd = TimeValueToDateTime(TimeValue(SSQSystem::inst().GetSealEffectEndTime(), 0));

    if (SSQSystem::inst().GetEventStartTime() == 0) {
        FormatUtf16To(message.data(), 0x800, u" + event start=[is not set]");
    } else {
        const std::wstring text = eventStart.ToString();
        FormatUtf16To(message.data(), 0x800, u" + event start=[%s]", text.c_str());
    }
    socket->SendSystemMessage(u"SYS", message.data());

    if (SSQSystem::inst().GetEventEndTime() == 0) {
        FormatUtf16To(message.data(), 0x800, u" + event end=[is not set]");
    } else {
        const std::wstring text = eventEnd.ToString();
        FormatUtf16To(message.data(), 0x800, u" + event end=[%s]", text.c_str());
    }
    socket->SendSystemMessage(u"SYS", message.data());

    if (SSQSystem::inst().GetSealEffectTime() == 0) {
        FormatUtf16To(message.data(), 0x800, u" + seal start=[is not set]");
    } else {
        const std::wstring text = sealStart.ToString();
        FormatUtf16To(message.data(), 0x800, u" + seal start=[%s]", text.c_str());
    }
    socket->SendSystemMessage(u"SYS", message.data());

    if (SSQSystem::inst().GetSealEffectEndTime() == 0) {
        FormatUtf16To(message.data(), 0x800, u" + seal end=[is not set]");
    } else {
        const std::wstring text = sealEnd.ToString();
        FormatUtf16To(message.data(), 0x800, u" + seal end=[%s]", text.c_str());
    }
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

