bool BuilderCmd_loadhtml(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00532904.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//loadhtml [html name] ...");
        return false;
    }

    std::u16string targetName = std::u16string(tokens[0].data());
    if (targetName.size() >= 256) {
        // Current wcscpy_s clears its 256-unit carrier on range failure.
        runtime::process::HandleInvalidParameter();
        targetName.clear();
    }
    const std::u16string hostName = LowercaseGameName(targetName);

    std::u16string html;
    if (!g_HTMLCache.GetHTMLFile(hostName.c_str(), html, user->m_data->m_CountryCode)) {
        socket->SendSystemMessage(u"HTML", u"No HTML");
        return false;
    }

    user->GetSocket()->Send("cdS", 0x19, 0, html.c_str());
    if (user->IsBuilder()) {
        user->GetSocket()->SendSystemMessage(u"HTML", hostName.c_str());
    }
    return false;
}

bool BuilderCmd_dropitem(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x004fb09c.
    L2_GUARD_FUNCTION();
    CNPC* const target = user->m_spTarget.GetNPC();
    if (target == nullptr || !target->IsNPC()) {
        socket->SendSystemMessage(u"SYS", u"target char first");
        return false;
    }

    std::array<char16_t, 5000> message{};
    std::array<char16_t, 5000> list{};
    std::array<char16_t, 256> itemText{};

    const auto appendItem = [&](const ItemDropStruct& item) {
        message.fill(L'\0');
        FormatUtf16To(
            itemText.data(), itemText.size(), u"{[%d];%d;%d;%f}", item.ItemClassId,
            runtime::Int32FromBits(static_cast<std::uint32_t>(item.DropMin)),
            runtime::Int32FromBits(static_cast<std::uint32_t>(item.DropMax)), item.DropProb
        );
        AppendBuilderText(list.data(), list.size(), std::u16string(itemText.data()).c_str());
        AppendBuilderText(list.data(), list.size(), u", ");
    };

    socket->SendSystemMessage(u"SYS", u"DropList : ");
    for (const ItemDropMultiStruct& group : target->m_pClassConst->m_ItemAdditionalMakeListMulti) {
        message.fill(L'\0');
        list.fill(L'\0');
        CopyBuilderText(list.data(), list.size(), u"{ ");
        for (const ItemDropStruct* const item : *group.pItemDropList) {
            appendItem(*item);
        }
        AppendBuilderText(list.data(), list.size(), u" }");
        FormatUtf16To(message.data(), message.size(), u"prob : %f ( %s )", group.DropProb, list.data());
        socket->SendSystemMessage(u"SYS", message.data());
    }

    socket->SendSystemMessage(u"SYS", u"Ex DropList");
    for (const ItemDropMultiStruct& group : target->m_pClassConst->m_ExItemDropListMulti) {
        message.fill(L'\0');
        list.fill(L'\0');
        CopyBuilderText(list.data(), list.size(), u"{ ");
        for (const ItemDropStruct* const item : *group.pItemDropList) {
            appendItem(*item);
        }
        AppendBuilderText(list.data(), list.size(), u" }");
        FormatUtf16To(message.data(), message.size(), u"prob : %f ( %s )", group.DropProb, list.data());
        socket->SendSystemMessage(u"SYS", message.data());
    }

    message.fill(L'\0');
    list.fill(L'\0');
    socket->SendSystemMessage(u"SYS", u"SpoilList : ");
    CopyBuilderText(list.data(), list.size(), u"{ ");
    for (const ItemDropStruct& item : target->m_pClassConst->m_CorpseMakeList) {
        appendItem(item);
    }
    AppendBuilderText(list.data(), list.size(), u" }");
    FormatUtf16To(message.data(), message.size(), u"( %s )", list.data());
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

