bool BuilderCmd_defend_register(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0052d894.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do defend_register command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//defend_register castle pledge");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr || !residence->IsCastle()) {
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[1].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    User* const requestUser = socket->GetUser();
    if (!pledge || requestUser == nullptr) {
        return false;
    }

    const int pledgeWorldId = pledge->GetWorldId();
    const unsigned int pledgeId = pledge->GetDbId();
    db.RequestConfirmCastleDefence(requestUser, static_cast<CCastle*>(residence), pledgeId, 1, pledgeWorldId);
    socket->SendSystemMessage(u"SYS", u"builder command[defend_register] accepted");
    return false;
}

