bool BuilderCmd_agitdeco(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x00572e80.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//agitdeco command [options]...");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//agitdeco set agit deco_id");
            return false;
        }

        const int residenceId = WindowsWtol(tokens[1].data());
        CResidence* residence = nullptr;
        if (residenceId == 0) {
            const std::u16string residenceName = std::u16string(tokens[1].data());
            residence = g_ResidenceDB.GetResidence(residenceName.c_str());
        } else {
            residence = g_ResidenceDB.GetResidence(residenceId);
        }
        CResidence* const agit = residence != nullptr ? residence->CastResidence() : nullptr;
        if (agit == nullptr) {
            socket->SendSystemMessage(u"SYS", u"invalid agit");
            return false;
        }

        CResidenceDeco* const deco =
            CResidenceDecoDb::Inst().FindResidenceDeco(static_cast<std::uint32_t>(WindowsWtol(tokens[2].data())));
        if (deco == nullptr) {
            socket->SendSystemMessage(u"SYS", u"invalid deco id");
            return false;
        }

        const std::int32_t now = runtime::crt::Time32Now();
        std::tm* const localTime = runtime::crt::LocalTime32(now);
        const std::int32_t periodDays = runtime::Int32FromBits(deco->m_lstCost.front().first);
        const std::int32_t expiration = runtime::AddInt32Wrapping(
            runtime::SubtractInt32Wrapping(
                runtime::MultiplyInt32Wrapping(
                    runtime::AddInt32Wrapping(
                        runtime::SubtractInt32Wrapping(
                            runtime::MultiplyInt32Wrapping(periodDays, 1440), localTime->tm_min
                        ),
                        60
                    ),
                    60
                ),
                localTime->tm_sec
            ),
            now
        );
        const int agitId = agit->m_data != nullptr ? agit->m_data->m_nResidenceID : 0;
        CSetResidenceDeco packet(
            -1, -1, agitId, deco->m_nType, deco->m_nDecoId, deco->m_sDecoName, deco->m_nLevel, expiration, 0
        );
        db.RequestTPacketProcess(g_nWorldId, 1, static_cast<int>(sizeof(packet)), packet);
        socket->SendSystemMessage(u"SYS", u"[agitdeco set] command accepted");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"reset") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//agitdeco reset agit deco_type");
            return false;
        }

        const int residenceId = WindowsWtol(tokens[1].data());
        CResidence* residence = nullptr;
        if (residenceId == 0) {
            const std::u16string residenceName = std::u16string(tokens[1].data());
            residence = g_ResidenceDB.GetResidence(residenceName.c_str());
        } else {
            residence = g_ResidenceDB.GetResidence(residenceId);
        }
        CResidence* const agit = residence != nullptr ? residence->CastResidence() : nullptr;
        if (agit == nullptr) {
            socket->SendSystemMessage(u"SYS", u"invalid agit");
            return false;
        }

        const int agitId = agit->m_data != nullptr ? agit->m_data->m_nResidenceID : 0;
        CResetResidenceDeco packet(-1, -1, agitId, WindowsWtol(tokens[2].data()), 0);
        db.RequestTPacketProcess(g_nWorldId, 2, static_cast<int>(sizeof(packet)), packet);
        socket->SendSystemMessage(u"SYS", u"[agitdeco reset] command accepted");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"list") != 0) {
        return false;
    }
    if (tokenCount < 2) {
        socket->SendSystemMessage(u"SYS", u"//agitdeco list agit");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[1].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[1].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    CResidence* const agit = residence != nullptr ? residence->CastResidence() : nullptr;
    if (agit == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid agit");
        return false;
    }

    const std::int32_t now = runtime::crt::Time32Now();
    bool hasDecoration = false;
    std::array<char16_t, 2048> message{};
    for (int type = 1; type <= 32; ++type) {
        CResidenceData* const data = agit->m_data;
        const Deco& decoration = data->m_aDeco[static_cast<std::size_t>(type - 1)];
        if (decoration.nId == 0) {
            continue;
        }

        hasDecoration = true;
        const std::int32_t remaining = runtime::SubtractInt32Wrapping(runtime::Int32FromBits(decoration.nExpire), now);
        const int hours = remaining / 3600;
        const int minutes =
            runtime::SubtractInt32Wrapping(remaining, runtime::MultiplyInt32Wrapping(hours, 3600)) / 60;
        const int seconds =
            runtime::SubtractInt32Wrapping(remaining, runtime::MultiplyInt32Wrapping(remaining / 60, 60));
        const int currentResidenceId = data != nullptr ? data->m_nResidenceID : 0;
        FormatUtf16To(
            message.data(), message.size(), u"agit[%d] deco {type=%d level=%d id=%d remain=%02d:%02d:%02d}",
            currentResidenceId, type, decoration.nLevel, decoration.nId, hours, minutes, seconds
        );
        socket->SendSystemMessage(u"SYS", message.data());
    }
    if (!hasDecoration) {
        const int currentResidenceId = agit->m_data != nullptr ? agit->m_data->m_nResidenceID : 0;
        FormatUtf16To(message.data(), message.size(), u"agit[%d] has no decoitem", currentResidenceId);
    }
    return false;
}

