bool agitdeconpc(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x005737dc.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//agitdeconpc command [options]...");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set") == 0) {
        if (tokenCount < 4) {
            socket->SendSystemMessage(u"SYS", u"//agitdeconpc set agit_id agit_slot deco_id");
            return false;
        }

        protocol::C_EX_DECO_NPC_SET request{};
        request.nAgitCID = ConvertToAgitCID(tokens[1].data());
        request.cSlot = static_cast<char>(std::max(WindowsWtol(tokens[2].data()), 0));
        request.nDecoCID = WindowsWtol(tokens[3].data());
        CPacketHelperEx<20480> packet;
        network::Stream stream(reinterpret_cast<unsigned char*>(packet.GetPacket()), 0x5000);
        if (!request.Encode(&stream)) {
            socket->SendSystemMessage(u"SYS", u"fail to encode at agitdeconpc");
            return false;
        }

        UserPacketEx::Request_C_EX_DECO_NPC_SET(socket, reinterpret_cast<const std::uint8_t*>(packet.GetPacket()));
        socket->SendSystemMessage(u"SYS", u"[agitdeconpc set] command accepted");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"info") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//agitdeconpc info agit");
            return false;
        }

        protocol::C_EX_DECO_NPC_INFO request{};
        request.nAgitCID = ConvertToAgitCID(tokens[1].data());
        CPacketHelperEx<20480> packet;
        network::Stream stream(reinterpret_cast<unsigned char*>(packet.GetPacket()), 0x5000);
        static_cast<void>(request.Encode(&stream));
        UserPacketEx::Request_C_EX_DECO_NPC_INFO(socket, reinterpret_cast<const std::uint8_t*>(packet.GetPacket()));
        socket->SendSystemMessage(u"SYS", u"[agitdeconpc info] command accepted");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"info_msg") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//agitdeconpc info_msg agit");
            return false;
        }

        CSPointer<User> retainedUser(socket->GetUser(), ObjectRefType::FunctionChain);
        if (InstantAgitUtil::IsInInstantAgit(retainedUser)) {
            CInstantAgit* const agit =
                CInstantAgitManager::inst().GetInstantAgit(static_cast<int>(retainedUser->m_data->m_nPledgeID));
            if (agit == nullptr) {
                socket->SendSystemMessage(u"SYS", u"agit is not exist");
                return false;
            }
            agit->SendDecoNpcInfoAsMsg(retainedUser);
        } else {
            CResidence* const residence = FindResidence(tokens[1].data());
            if (residence == nullptr) {
                socket->SendSystemMessage(u"SYS", u"agit is not exist");
                return false;
            }

            std::array<char16_t, 1024> message{};
            const std::int32_t now = runtime::crt::Time32Now();
            CResidenceData* data = residence->m_data;
            for (int slot = 0; slot < data->m_nDecoNpcSlotCount; ++slot) {
                const DecoNpc& decoration = data->m_aDecoNpc[static_cast<std::size_t>(slot)];
                const std::int32_t remaining =
                    decoration.nCID == 0 ? 0 : runtime::SubtractInt32Wrapping(decoration.tExpire, now);
                FormatUtf16To(
                    message.data(), message.size(), u"Deco(%d) : %d, %d, %d", slot, decoration.nCID, remaining,
                    decoration.nNpcSID
                );
                socket->SendSystemMessage(u"SYS", message.data());
                data = residence->m_data;
            }
        }

        socket->SendSystemMessage(u"SYS", u"[agitdeconpc info] command accepted");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"expire") == 0) {
        if (tokenCount < 4) {
            socket->SendSystemMessage(u"SYS", u"//agitdeconpc expire agit_id agit_slot seconds");
            return false;
        }

        CSPointer<User> retainedUser(socket->GetUser(), ObjectRefType::FunctionChain);
        if (InstantAgitUtil::IsInInstantAgit(retainedUser)) {
            const int slot = std::max(WindowsWtol(tokens[2].data()), 0);
            const int seconds = std::max(WindowsWtol(tokens[3].data()), 1);
            CInstantAgitManager::inst().SetDecoNpcExpireTime(
                static_cast<int>(retainedUser->m_data->m_nPledgeID), slot, seconds
            );
        } else {
            CResidence* const residence = FindResidence(tokens[1].data());
            if (residence == nullptr) {
                socket->SendSystemMessage(u"SYS", u"agit is not exist");
                return false;
            }

            const int slot = std::max(WindowsWtol(tokens[2].data()), 0);
            const int seconds = std::max(WindowsWtol(tokens[3].data()), 1);
            CResidenceData* const data = residence->m_data;
            if (slot < 0 || slot >= data->m_nDecoNpcSlotCount) {
                socket->SendSystemMessage(u"SYS", u"invalid slot");
                return false;
            }
            DecoNpc& decoration = data->m_aDecoNpc[static_cast<std::size_t>(slot)];
            if (decoration.nCID != 0) {
                decoration.tExpire = runtime::AddInt32Wrapping(runtime::crt::Time32Now(), seconds);
            }
        }

        socket->SendSystemMessage(u"SYS", u"[agitdeconpc expire] command accepted");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"reload") == 0) {
        CDecoNpcDB::Inst().Load();
        socket->SendSystemMessage(u"SYS", u"[agitdeconpc reload] command accepted");
    }
    return false;
}

