bool BuilderCmd_move_cell(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x004f87c8.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//move_cell dir cellcount");
        return false;
    }

    const int direction = WindowsWtol(tokens[0].data()) % 4;
    const int cellCount = WindowsWtol(tokens[1].data());
    const FVector position = user->GetPos();
    int x = runtime::Win64CvttDoubleToInt32(position.x);
    int y = runtime::Win64CvttDoubleToInt32(position.y);
    const int z = runtime::Win64CvttDoubleToInt32(position.z);

    switch (direction) {
        case 0:
            x = runtime::AddInt32Wrapping(x, runtime::MultiplyInt32Wrapping(cellCount, 16));
            break;
        case 1:
            x = runtime::AddInt32Wrapping(
                x, runtime::MultiplyInt32Wrapping(runtime::NegateInt32Wrapping(cellCount), 16)
            );
            break;
        case 2:
            y = runtime::AddInt32Wrapping(y, runtime::MultiplyInt32Wrapping(cellCount, 16));
            break;
        case 3:
            y = runtime::AddInt32Wrapping(
                y, runtime::MultiplyInt32Wrapping(runtime::NegateInt32Wrapping(cellCount), 16)
            );
            break;
        default:
            break;
    }

    static_cast<void>(user->TeleportToLocation(x, y, z, 0, 0x10000, TeleportSourceType::BuilderCmd, user, 0));
    return false;
}

