bool BuilderCmd_ps_cancel(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x004d752c.
    L2_GUARD_FUNCTION();
    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr || !target->IsPC()) {
        socket->SendSystemMessage(u"SYS", u"target char first");
        return false;
    }
    if (target->m_data->m_StopMode == STP_SIT ||
        (!target->IsShopOpen() && target->GetPrivateStoreType() != PST_RECIPE_SHOP_OPEN) || target->IsNowTrade() ||
        !target->IsItemUsable(0) || target->IsRiding()) {
        return false;
    }

    if (target->GetPrivateStoreType() == PST_OPEN || target->GetPrivateStoreType() == PST_WHOLESALE_OPEN) {
        const int storeType = target->m_data->m_nPrivateStoreType;
        const bool wholesale = storeType == PST_WHOLESALE_OPEN || storeType == PST_WHOLESALE_MANAGE;
        static_cast<void>(target->SendPrivateStoreManageList(wholesale, nullptr));
    } else if (target->GetPrivateStoreType() == PST_BUY_OPEN) {
        static_cast<void>(target->SendPrivateStoreBuyManageList(nullptr));
    } else {
        target->SendRecipeStoreManageList();
    }
    return false;
}

