bool BuilderCommandUseSkill(CUserSocket* socket, User* user, char16_t* command, std::vector<CWorldObject*>& targets) {
    // Current L2Server 0x00542358.
    L2_GUARD_FUNCTION();
    if (targets.size() > 500) {
        targets.erase(targets.begin() + 500, targets.end());
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//use_skill [skill_id] [skill_level] [skill_sub_level/none]");
        return false;
    }

    const int skillId = WindowsWtol(tokens[0].data());
    const int skillLevel = WindowsWtol(tokens[1].data());
    const int skillSubLevel = tokenCount == 3 ? WindowsWtol(tokens[2].data()) : 0;
    const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(CSkillKey(skillId, skillLevel, skillSubLevel), user);
    if (skillInfo == nullptr) {
        std::array<char16_t, 1024> message{};
        FormatUtf16To(
            message.data(), 1023, u"Invalid Skill ID (id:%d-level:%d-sublevel:%d)", skillId, skillLevel, skillSubLevel
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    if (targets.size() > 1) {
        const CSkillInfo::SkillEffects* const effects = skillInfo->GetEffects(CSkillInfo::EAT_SUCCESS);
        if (effects != nullptr) {
            for (CSkillEffect* const effect : *effects) {
                if (typeid(*effect) == typeid(CSkillEffect_i_summon_npc)) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"You cannot summon npc by use_skill_all")
                    // Previous: L2_LOG_ERROR(Log,
                    //     L"You cannot summon npc by use_skill_all")
                    L2_LOG_ERROR(
                        Log,
                        u"[builder skills] use_skill_all rejected skill %d "
                        u"level %d: it contains an NPC-summoning effect.",
                        skillId, skillLevel
                    );
                    socket->SendSystemMessage(u"SYS", u"You cannot summon npc by use_skill_all");
                    return false;
                }
            }
        }
    }

    for (CWorldObject* const target : targets) {
        static_cast<void>(skillInfo->ActivateSkill(user, target, 0.0, nullptr, CSkillInfo::EAT_SUCCESS, false));
    }
    return false;
}

