bool BuilderCmd_party_teleport(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x00553a9c.
    L2_GUARD_FUNCTION();
    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr || !target->IsPC()) {
        socket->SendSystemMessage(u"SYS", u"target char first");
        return false;
    }

    CParty* const party = target->GetParty();
    if (party == nullptr) {
        static_cast<void>(target->Restart(RESTART_VILLAGE, 0));
        return false;
    }

    std::vector<User*> members;
    party->GetAllMember(members);
    for (User* const member : members) {
        if (member->IsAlive()) {
            static_cast<void>(member->Restart(RESTART_VILLAGE, 0));
        }
    }
    return false;
}

