bool BuilderCmd_show_party(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x00553f68.
    L2_GUARD_FUNCTION();
    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        socket->SendSystemMessage(u"SYS", u"target creature first");
        return false;
    }

    user->GetSocket()->SendSystemMessage(u"SYS", u"======================");
    CParty* const party = target->GetParty();
    if (party == nullptr) {
        std::array<char16_t, 512> message{};
        FormatUtf16To(message.data(), 511, u"[%s] is not in party.", target->GetName());
        user->GetSocket()->SendSystemMessage(u"SYS", message.data());
    } else {
        std::vector<User*> members;
        party->GetAllMember(members);
        for (User* const member : members) {
            const std::u16string ipAddress = member->GetSocket()->GetIPAddressString();
            const std::u16string account(member->m_sAccountName.data());
            std::array<char16_t, 512> message{};
            FormatUtf16To(
                message.data(), 511, u"[%s/%s] : lev[%d], cls[%d], ip[%s]", member->GetName(), account.c_str(),
                member->m_data->m_nLevel, member->m_data->m_nClass, ipAddress.c_str()
            );
            user->GetSocket()->SendSystemMessage(u"SYS", message.data());
        }
    }
    user->GetSocket()->SendSystemMessage(u"SYS", u"======================");
    return false;
}

bool BuilderCmd_disconnect_party(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x0055424c.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    int builderLevel = 0;
    {
        L2_GUARD(*builder->m_lock);
        builderLevel = builder->m_data->m_nBuilder;
    }
    if (builderLevel != 0 && builderLevel < 2) {
        User* const target = user->m_spTarget.GetUser();
        if (target == nullptr) {
            socket->SendSystemMessage(u"SYS", u"target creature first");
            return false;
        }

        user->GetSocket()->SendSystemMessage(u"SYS", u"======================");
        CParty* const party = target->GetParty();
        if (party == nullptr) {
            std::array<char16_t, 512> message{};
            FormatUtf16To(message.data(), 511, u"[%s] is not in party.", target->GetName());
            user->GetSocket()->SendSystemMessage(u"SYS", message.data());
        } else {
            user->GetSocket()->SendSystemMessage(u"SYS", u"disconnect all party member");
            std::vector<User*> members;
            party->GetAllMember(members);
            for (User* const member : members) {
                if (member != user) {
                    member->GetSocket()->Close();
                }
            }
            user->GetSocket()->Close();
        }
        user->GetSocket()->SendSystemMessage(u"SYS", u"======================");
    }
    return false;
}

