bool BuilderCmd_DeleteBuff(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x0053f790.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return false;
    }

    User* target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        target = user;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//delete_buff [all | good | bad]");
        return false;
    }

    bool accepted = false;
    {
        L2_GUARD(target->m_InfectedSkillsSect);
        if (std::u16string_view(tokens[0].data()).substr(0, 3).compare(u"all") == 0) {
            while (!target->m_InfectedSkills.empty()) {
                const CSkillInfo* const skillInfo = target->m_InfectedSkills.front().pSkillInfo;
                target->_DeleteAbnormalStatus(0, target, skillInfo, true, SPET_DISPEL, true);
            }
            accepted = true;
        } else {
            const bool deleteGood = std::u16string_view(tokens[0].data()).substr(0, 4).compare(u"good") == 0;
            const bool deleteBad = !deleteGood && std::u16string_view(tokens[0].data()).substr(0, 3).compare(u"bad") == 0;
            if (deleteGood || deleteBad) {
                while (true) {
                    std::size_t index = 0;
                    while (index < target->m_InfectedSkills.size()) {
                        const int effectPoint =
                            runtime::CheckedVectorAt(target->m_InfectedSkills, index).pSkillInfo->m_nEffectPoint;
                        const bool matches =
                            deleteGood ? effectPoint == 0 : effectPoint == 1 || effectPoint == 2 || effectPoint == 3;
                        if (matches) {
                            break;
                        }
                        ++index;
                    }
                    if (index == target->m_InfectedSkills.size()) {
                        break;
                    }
                    const CSkillInfo* const skillInfo = runtime::CheckedVectorAt(target->m_InfectedSkills, index).pSkillInfo;
                    target->_DeleteAbnormalStatus(static_cast<int>(index), target, skillInfo, true, SPET_DISPEL, true);
                    accepted = true;
                }
            } else {
                socket->SendSystemMessage(u"SYS", u"//delete_buff [all|good|bad]");
            }
        }
    }

    if (accepted) {
        socket->SendSystemMessage(u"SYS", u"builder command [delete_buff] accepted");
        target->ValidateChanged(VB_WEAPONARMOR | VB_SKILLMOD | VB_HPMPCP | VB_SIM | VB_SPEED);
        target->m_bAbnormalStatusChanged = true;
        target->m_NeedUpdatePacketBits |= 2U;
        if (target->IsPC()) {
            target->CastUser()->SendShortBuffStatusInfo();
        }
    }
    return false;
}

