bool BuilderCmd_clan_advent_up(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x004d58a4.
    L2_GUARD_FUNCTION();
    CObject* const object = user->m_spTarget.GetObjectW();
    if (object == nullptr || !object->IsPC()) {
        socket->SendSystemMessage(u"SYS", u"target is not pc");
        return false;
    }

    User* const target = object->CastUser();
    CPledge* const pledge = target->GetPledge();
    if (pledge == nullptr) {
        socket->SendSystemMessage(u"SYS", u"target is not pledge member");
    } else if (!target->IsPledgeMaster()) {
        socket->SendSystemMessage(u"SYS", u"target is not pledge master");
    } else {
        pledge->AddPledgeSkillByEliteTo(target);
        socket->SendSystemMessage(u"SYS", u"pledge skill up completed");
    }
    return false;
}

