bool BuilderCmd_setarea(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004ef7e8.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setarea area_name [on|off|buff_on|buff_off]");
        return false;
    }

    const std::u16string areaName = std::u16string(tokens[0].data());
    CArea* const area = CAreaDB::inst().FindArea(areaName.c_str());
    if (area == nullptr) {
        socket->SendSystemMessage(u"SYS", u"unknown area name");
        return false;
    }

    if (std::u16string_view(tokens[1].data()).compare(u"on") != 0 &&
        std::u16string_view(tokens[1].data()).compare(u"off") != 0) {
        if (std::u16string_view(tokens[1].data()).compare(u"buff_on") == 0) {
            area->SetShowDangerZone(true);
        } else if (std::u16string_view(tokens[1].data()).compare(u"buff_off") == 0) {
            area->SetShowDangerZone(false);
        }
        return false;
    }

    const bool on = std::u16string_view(tokens[1].data()).compare(u"on") == 0;
    if (area->m_InstantZoneKey.typeId == 0) {
        area->SetOnOff(on);
        return false;
    }

    CInstantZone* const zone = user->GetInstantZone();
    if (zone != nullptr) {
        zone->SetAreaOnOff(area, on);
    } else {
        socket->SendSystemMessage(u"SYS", u"area are in inzone, but you are not");
    }
    return false;
}

bool BuilderCmd_setarea_all(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x005616f8.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setarea_all [areaType:all or type(0~11)] [on|off]");
        return false;
    }

    const AreaTypeEnum type = std::u16string_view(tokens[0].data()).compare(u"all") == 0
        ? AREAT_MAX
        : static_cast<AreaTypeEnum>(WindowsWtol(tokens[0].data()));
    const FVector position = user->GetPos();
    CAreaDB::AreaList areas = CAreaDB::inst().FindAllAreaList(position, type);
    for (CArea* const area : areas) {
        const bool on = std::u16string_view(tokens[1].data()).compare(u"on") == 0;
        if (area->m_InstantZoneKey.typeId == 0) {
            area->SetOnOff(on);
        } else {
            CInstantZone* const zone = user->GetInstantZone();
            if (zone == nullptr) {
                socket->SendSystemMessage(u"SYS", u"area are in inzone, but you are not");
                return false;
            }
            zone->SetAreaOnOff(area, on);
        }

        std::array<char16_t, 2048> message{};
        const std::wstring name = Utf16ToWide(runtime::StringView(area->m_FieldTerritory.sName));
        FormatUtf16To(message.data(), message.size(), u"[%s] is %s", name.c_str(), tokens[1].data());
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

bool BuilderCmd_areaname(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x0055d0d4.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    const FVector position = user->GetPos();
    CAreaDB::AreaList areas = CAreaDB::inst().FindAllAreaList(position);
    for (CArea* const area : areas) {
        const bool on = area->IsOn(0);
        std::array<char16_t, 2048> message{};
        const std::wstring name = Utf16ToWide(runtime::StringView(area->m_FieldTerritory.sName));
        FormatUtf16To(message.data(), message.size(), u"area : [%s][%s]", name.c_str(), on ? L"on" : L"off");
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

