bool BuilderCmd_auction_close(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004f05f8.
    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//auction_close agit_name");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr) {
        return false;
    }
    CWorldAgit* const worldAgit = residence->CastWorldAgit();
    if (worldAgit == nullptr) {
        return false;
    }
    CAuctionAgit* const auction = worldAgit->CastAuctionAgit();
    if (auction != nullptr && auction->GetSaleState() == SALE_ACT && auction->CanDoAuction()) {
        auction->EnterDoAuction();
        db.RequestSetAgitAuction(auction->m_data->m_nResidenceID, auction->m_nAuctionId);
    }
    return false;
}

