bool BuilderCmd_set_controltower_status(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00572720.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//set_controltower_status control_tower_name "
            u"[idle|dest|work|breakable|unbreakable]"
        );
        return false;
    }

    const std::u16string towerName = std::u16string(tokens[0].data());
    CControlTower* const tower = CControlTowerDB::Inst().GetControlTower(towerName.c_str());
    if (tower == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid controltower name");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"idle") == 0) {
        tower->SetStatus(ControlTowerStatusEnum::Idle);
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"dest") == 0) {
        tower->SetStatus(ControlTowerStatusEnum::Destroyed);

        const int displayNpcId = tower->m_eStatus == ControlTowerStatusEnum::Working ? tower->m_nDisplayNPCID_Working
                                                                                     : tower->m_nDisplayNPCID_NotWorking;
        int residenceId = 0;
        if (tower->m_pOwningResidence->m_data != nullptr) {
            residenceId = tower->m_pOwningResidence->m_data->m_nResidenceID;
        }
        const FVector xPosition = tower->GetPos();
        const std::int64_t x = runtime::Win64CvttDoubleToInt64(xPosition.x);
        const FVector zPosition = tower->GetPos();
        const std::int64_t z = runtime::Win64CvttDoubleToInt64(zPosition.z);
        const FVector yPosition = tower->GetPos();
        const std::int64_t y = runtime::Win64CvttDoubleToInt64(yPosition.y);
        CLogFormatter formatter;
        formatter.WriteLog2(0x7ee, user, nullptr, x, y, z, residenceId, displayNpcId, 0, 0);
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"work") == 0) {
        tower->SetStatus(ControlTowerStatusEnum::Working);
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"breakable") == 0) {
        tower->SetBreakable(true);
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"unbreakable") == 0) {
        tower->SetBreakable(false);
    } else {
        socket->SendSystemMessage(u"SYS", u"invlaid controltower status");
        return false;
    }

    db.RequestSaveControlTowerStatus(tower);
    socket->SendSystemMessage(u"SYS", u"builder command[set_controltower_status] accepted");
    return false;
}

bool BuilderCmd_setIntervalAnnounce(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x0052ab3c.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//set_interval_announce [start|end|add|del|reload] "
            u"interval announce_id announce_msg"
        );
        return false;
    }

    std::array<char16_t, 64> operation{};
    const std::size_t operationLength = std::min(std::char_traits<char16_t>::length(tokens[0].data()), operation.size() - 1);
    std::char_traits<char16_t>::copy(operation.data(), tokens[0].data(), operationLength);
    operation[operationLength] = L'\0';

    if (CompareBuilderTextIgnoreCase(operation.data(), u"start") == 0) {
        CAnnounceTimer::Inst()->bShowIntervalAnnounce = false;
        socket->SendSystemMessage(u"SYS", u"Interval announce is stoped");
        return false;
    }
    if (CompareBuilderTextIgnoreCase(operation.data(), u"end") == 0) {
        CAnnounceTimer::Inst()->bShowIntervalAnnounce = true;
        db.ShowIntervalAnnounce(socket, 1);
        socket->SendSystemMessage(u"SYS", u"Interval announce is restarted");
        return false;
    }

    const bool add = CompareBuilderTextIgnoreCase(operation.data(), u"add") == 0;
    const bool remove = !add && CompareBuilderTextIgnoreCase(operation.data(), u"del") == 0;
    if (add || remove) {
        if (CAnnounceTimer::Inst()->bShowIntervalAnnounce) {
            socket->SendSystemMessage(u"SYS", u"interval announce is not stopped.");
            socket->SendSystemMessage(
                u"SYS",
                u"After interval announce is stopped, "
                u"you can change interval announce."
            );
            return false;
        }

        if (tokenCount < 3) {
            socket->SendSystemMessage(
                u"SYS",
                u"//set_interval_announce [start|end|add|del|reload] "
                u"interval announce_id announce_msg"
            );
            return false;
        }

        const int interval = WindowsWtol(tokens[1].data());
        const bool validInterval = interval == 10 || interval == 20 || interval == 30 || interval == 40 || interval == 50 ||
            interval == 60 || interval == 120 || interval == 240 || interval == 360;
        if (!validInterval) {
            socket->SendSystemMessage(u"SYS", u"// [type][interval] [ANNOUNCE_ID] [ANNOUNCE_MESSAGE]");
            socket->SendSystemMessage(u"SYS", u"interval : 10 20 30 40 50 60 120 240 360");
            socket->SendSystemMessage(u"SYS", u"type : start | end | add | del");
            socket->SendSystemMessage(u"SYS", u"0 < announce id < 6");
            socket->SendSystemMessage(
                u"SYS",
                CAnnounceTimer::Inst()->bShowIntervalAnnounce ? u"currently. Interval announce is showing"
                                                              : u"currently. Interval announce is stoped"
            );
            return false;
        }

        const int announceId = WindowsWtol(tokens[2].data());
        if (static_cast<std::uint32_t>(announceId - 1) >= 5U) {
            socket->SendSystemMessage(u"SYS", u"// [interval] [ANNOUNCE_ID] [ANNOUNCE_MESSAGE]");
            socket->SendSystemMessage(u"SYS", u"interval : 10 20 30 40 50 60 120 240 360");
            socket->SendSystemMessage(u"SYS", u"interval 0 means end change");
            socket->SendSystemMessage(u"SYS", u"interval -1 means delete announce id");
            socket->SendSystemMessage(u"SYS", u"0 < announce id < 6");
            socket->SendSystemMessage(
                u"SYS",
                CAnnounceTimer::Inst()->bShowIntervalAnnounce ? u"currently. Interval announce is showing"
                                                              : u"currently. Interval announce is stoped"
            );
            return false;
        }

        if (remove) {
            db.DelIntervalAnnounce(socket, interval, announceId);
            return false;
        }
        if (tokenCount < 4) {
            socket->SendSystemMessage(
                u"SYS",
                u"//set_interval_announce [start|end|add|del|reload] "
                u"interval announce_id announce_msg"
            );
            return false;
        }

        std::array<char16_t, 64> message{};
        const std::size_t messageLength = std::min<std::size_t>(std::char_traits<char16_t>::length(tokens[3].data()), 50);
        std::char_traits<char16_t>::copy(message.data(), tokens[3].data(), messageLength);
        message[messageLength] = L'\0';
        db.SetIntervalAnnounce(socket, interval, announceId, message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(operation.data(), u"reload") == 0) {
        db.ShowIntervalAnnounce(socket, 1);
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"// [type][interval] [ANNOUNCE_ID] [ANNOUNCE_MESSAGE]");
    socket->SendSystemMessage(u"SYS", u"interval : 10 20 30 40 50 60 120 240 360");
    socket->SendSystemMessage(u"SYS", u"type : start | end | add | del");
    socket->SendSystemMessage(u"SYS", u"0 < announce id < 6");
    socket->SendSystemMessage(
        u"SYS",
        CAnnounceTimer::Inst()->bShowIntervalAnnounce ? u"currently. Interval announce is showing"
                                                      : u"currently. Interval announce is stoped"
    );
    return false;
}

