bool BuilderCmd_mid_victory(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0052be5c.
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do mid_victory command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//mid_victory castle pledge "
            u"castle_type(0:not castle 1:good 2:bad)"
        );
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid residence");
        return false;
    }
    if (!residence->IsUnderSiege()) {
        socket->SendSystemMessage(u"SYS", u"not in siege state");
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[1].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        socket->SendSystemMessage(u"SYS", u"you can use this command only after the pledge is loaded");
        return false;
    }

    if (residence->IsCastle()) {
        const int firstResidenceId = residence->GetResidenceID();
        const int siegeResidenceId = pledge->GetCurrentCastleSiegeDbId(firstResidenceId);
        const int secondResidenceId = residence->GetResidenceID();
        bool isAttacker = siegeResidenceId == secondResidenceId;
        if (isAttacker) {
            const int thirdResidenceId = residence->GetResidenceID();
            isAttacker = pledge->GetCurrentCastleSiegeStatus(thirdResidenceId) == 1;
        }
        if (!isAttacker) {
            socket->SendSystemMessage(u"SYS", u"this pledge is not an attacker");
            return false;
        }
    }

    residence->ChangeOwner(pledge.get(), WindowsWtol(tokens[2].data()), true);
    socket->SendSystemMessage(u"SYS", u"builder command[mid_victory] accepted");
    return false;
}

