bool BuilderCmd_door_levelup(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x00564f84.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//door_levelup [doorname|all] level(total%)");
        return false;
    }

    std::vector<CDoor*> doors;
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"all") == 0) {
        for (const auto& entry : g_DoorDB.m_DoorNameMap) {
            if (entry.second != nullptr) {
                doors.push_back(entry.second);
            }
        }
    } else {
        const int doorId = WindowsWtol(tokens[0].data());
        CDoor* const door = doorId == 0 ? g_DoorDB.GetDoor(tokens[0].data(), 0) : g_DoorDB.GetDoor(doorId);
        if (door != nullptr) {
            doors.push_back(door);
        }
    }

    const int level = WindowsWtol(tokens[1].data());
    if (level < 1) {
        socket->SendSystemMessage(u"SYS", u"new door hp level is not valid");
        return false;
    }
    if (doors.empty()) {
        socket->SendSystemMessage(u"SYS", u"door name is not valid");
        return false;
    }

    for (CDoor* const door : doors) {
        const double maximumHp = door->m_dBaseHp * static_cast<double>(level) / 100.0;
        door->m_data->m_dMaxHP = maximumHp;
        door->SetHP(maximumHp);
        db.RequestSaveDoorStatus(door);
    }
    socket->SendSystemMessage(u"SYS", u"builder command[door_levelup] accepted");
    return false;
}

