bool BuilderCmd_killFakeNPC(CUserSocket* socket, User*, char16_t*) {
    // Current L2Server 0x0053ff14.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    class TLMFilter final : public CTLMFilterDist {
    public:
        TLMFilter(const int inZoneId, const FVector& position) : CTLMFilterDist(inZoneId, position, 1000.0) {}

        bool CanDo(CObject* object) override {
            if (!CTLMFilterDist::CanDo(object)) {
                return false;
            }
            CCreature* const creature = object != nullptr ? object->CastCreature() : nullptr;
            CNPC* const npc = creature != nullptr && creature->IsNPC() ? creature->CastNPC() : nullptr;
            return npc != nullptr && npc->IsFakeNPC() && !creature->m_data->m_bIsFakeDeath;
        }
    };

    class TLMFunc final : public CTLMFunc {
    public:
        explicit TLMFunc(User* const builder) : m_builder(builder) {}

        bool CanDo(CObject* object, double) override {
            if (!object->IsPC() || (!object->IsDeletingObject() && object->m_Deleted == 0)) {
                m_builder->Action(object->CastCreature(), false, false);
            }
            return true;
        }

    private:
        User* m_builder;
    };

    const FVector position = builder->m_data->m_Pos;
    TLMFilter filter(static_cast<int>(builder->GetInZoneID()), position);
    TLMFunc function(builder);
    FOR_ALL_NEIGHBOR_CREATURE_DIST(&filter, &function);
    return false;
}

