    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.y)),
    //     static_cast<long long>(
    //         runtime::Win64CvttDoubleToInt32(
    //             builderPosition.z)),
    //     tokens[0].data(),
    //     tokens[1].data(),
    //     builderName.data(),
