bool BuilderCmd_RemoveCachingHTML(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x005012d0.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//remove_caching_html [html name] ...");
        return false;
    }

    std::u16string targetName = std::u16string(tokens[0].data());
    if (targetName.size() >= 256) {
        // Current wcscpy_s clears its 256-unit carrier on range failure.
        runtime::process::HandleInvalidParameter();
        targetName.clear();
    }
    const std::u16string hostName = LowercaseGameName(targetName);

    const bool removed = g_HTMLCache.RemoveCachingHTMLFile(hostName.c_str(), 0);
    const char16_t* const messageFormat = removed ? u"[%s] is deleted" : u"[%s] is not in HTML Cache";
    std::array<char16_t, 104> message{};
    FormatUtf16To(message.data(), message.size(), messageFormat, hostName.c_str());
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

bool BuilderCmd_SetStaticMeshStatus(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004f1684.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//set_static_mesh_status [doorname|doorId] "
            u"[targetable:on|off] [stealth:on|off]"
        );
        return false;
    }

    const int doorId = WindowsWtol(tokens[0].data());
    CDoor* const door = doorId == 0 ? g_DoorDB.GetDoor(tokens[0].data(), 0) : g_DoorDB.GetDoor(doorId);
    if (door == nullptr) {
        return false;
    }

    static_cast<void>(door->SetTargetable(CompareBuilderTextIgnoreCase(tokens[1].data(), u"on") == 0, true));
    door->m_data->m_nStealth = CompareBuilderTextIgnoreCase(tokens[2].data(), u"on") == 0 ? 1 : 0;
    door->SendDoorStatus(socket);

    if (door->m_pEventController != nullptr && door->m_data->m_nStealth > 0) {
        door->m_pEventController->SetOnOff(!door->m_data->m_bIsOpen);
        door->m_pEventController->SendEventControllerInfo(socket, true);
    }
    return false;
}

