bool _set_quick_siege(User* user, CUserSocket* socket, CResidence* residence, const int seconds) {
    // Current L2Server 0x004eeea0.
    L2_GUARD_FUNCTION();
    const std::int32_t siegeTime = runtime::AddInt32Wrapping(runtime::crt::Time32Now(), seconds);
    if (residence->m_data != nullptr) {
        residence->m_data->m_NextSiege = siegeTime;
    }
    if (residence->IsCastle()) {
        CCastle* const castle = residence->CastCastle();
        db.RequestSetNextCastleSiege(user, castle, siegeTime);
        const int castleId = castle->m_data != nullptr ? castle->m_data->m_nResidenceID : 0;
        static_cast<void>(CCastle::ReserveSiegeTime(castleId, siegeTime));
        static_cast<void>(castle->SetSiegeDate(siegeTime));
        castle->ChangeResidenceState(RS_REGISTRATION);
        castle->BroadcastSetSiegeTime();
    } else if (residence->IsWorldAgit()) {
        residence->ChangeResidenceState(RS_REGISTRATION);
        db.RequestSetNextAgitBattleTime(residence->CastWorldAgit());
    }

    User* const builder = socket->GetUser();
    if (builder != nullptr) {
        std::uint32_t builderDbId = 0;
        std::uint32_t builderAccountId = 0;
        std::array<char16_t, 28> builderName{};
        std::array<char16_t, 16> builderAccount{};
        FVector builderPosition{};
        {
            L2_GUARD(*builder->m_lock);
            builderDbId = builder->GetDBID();
            builderAccountId = builder->GetAccountID();
            CopyBuilderText(builderName.data(), 0x19, builder->GetName());
            const std::u16string accountText(builder->m_sAccountName.data());
            CopyBuilderText(builderAccount.data(), 0x0f, accountText.c_str());
            builderPosition = builder->GetPos();
        }
        const int residenceId = residence->m_data != nullptr ? residence->m_data->m_nResidenceID : 0;
        // Log.Add(
        //     LOG_BOTH,
        //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
        //     L"%I64d,%I64d,,,,,,,,,%s,%s,,,",
        //     static_cast<long long>(0x214),
        //     static_cast<long long>(builderDbId),
        //     static_cast<long long>(builderAccountId),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.x)),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.y)),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.z)),
        //     static_cast<long long>(residenceId),
        //     static_cast<long long>(seconds),
        //     builderName.data(),
        //     builderAccount.data())
        Log.Add(
            LOG_BOTH,
            u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
            u"%I64d,%I64d,,,,,,,,,%s,%s,,,",
            static_cast<long long>(0x214), static_cast<long long>(builderDbId), static_cast<long long>(builderAccountId),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.x)),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.y)),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.z)), static_cast<long long>(residenceId),
            static_cast<long long>(seconds), builderName.data(), builderAccount.data()
        );
        socket->SendSystemMessage(u"SYS", u"builder command[set_quick_siege] accepted");
    }
    return true;
}

