bool serverstat(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x004e2bac has no guard frame and
    // evaluates several reporting inputs more than once.
    std::array<char16_t, 20480> message;

    const wchar_t* const buildTime = CBuildDate::inst().BuildTime();
    const wchar_t* const buildDate = CBuildDate::inst().BuildDate();
    const int minuteTime = g_L2Time.GetTime();
    const int hourTime = g_L2Time.GetTime();
    const int protocolVersion = GetProtocolVersion();
    FormatUtf16To(
        message.data(), 0x4fff,
        u"Server Build date : %s %s Protocol Version : %d "
        u"World Time : %02d:%02d",
        buildDate, buildTime, protocolVersion, (hourTime / 60) % 24, minuteTime % 60
    );
    socket->SendSystemMessage(u"SYS", message.data());

    const std::int32_t now = runtime::crt::Time32Now();
    const double elapsed = std::difftime(static_cast<std::time_t>(now), static_cast<std::time_t>(server_up_time));
    const std::int32_t days = runtime::Win64CvttDoubleToInt32(elapsed / 86400.0);
    double remainder = elapsed - static_cast<double>(runtime::MultiplyInt32Wrapping(days, 86400));
    const std::int32_t hours = runtime::Win64CvttDoubleToInt32(remainder / 3600.0);
    remainder -= static_cast<double>(runtime::MultiplyInt32Wrapping(hours, 3600));
    const std::int32_t minutes = runtime::Win64CvttDoubleToInt32(remainder / 60.0);
    const std::int32_t seconds =
        runtime::Win64CvttDoubleToInt32(remainder - static_cast<double>(runtime::MultiplyInt32Wrapping(minutes, 60)));
    FormatUtf16To(
        message.data(), 0x4fff, u"Elapsed Time : %d days %d hours %d minutes %d seconds", days, hours, minutes, seconds
    );
    socket->SendSystemMessage(u"SYS", message.data());

    const auto load = [](const std::atomic<std::int32_t>& value) { return value.load(std::memory_order_relaxed); };

    // Current right-to-left active-count evaluation order.
    const std::int32_t airShip = load(g_ServerContext.AirShip);
    const std::int32_t activeAirShip = runtime::SubtractInt32Wrapping(airShip, load(g_ServerContext.NotReleasedAirShip));
    const std::int32_t auction = load(g_ServerContext.Auction);
    const std::int32_t activeAuction = runtime::SubtractInt32Wrapping(auction, load(g_ServerContext.NotReleasedAuction));
    const std::int32_t trade = load(g_ServerContext.Trade);
    const std::int32_t activeTrade = runtime::SubtractInt32Wrapping(trade, load(g_ServerContext.NotReleasedTrade));
    const std::int32_t inZone = load(g_ServerContext.InZone);
    const std::int32_t activeInZone = runtime::SubtractInt32Wrapping(inZone, load(g_ServerContext.NotReleasedInZone));
    const std::int32_t door = load(g_ServerContext.Door);
    const std::int32_t activeDoor = runtime::SubtractInt32Wrapping(door, load(g_ServerContext.NotReleasedDoor));
    const std::int32_t userSocket = load(g_ServerContext.UserSocket);
    const std::int32_t activeUserSocket =
        runtime::SubtractInt32Wrapping(userSocket, load(g_ServerContext.NotReleasedUserSocket));
    const std::int32_t npc = load(g_ServerContext.Npc);
    const std::int32_t activeNpc = runtime::SubtractInt32Wrapping(npc, load(g_ServerContext.NotReleasedNpc));
    const std::int32_t item = load(g_ServerContext.Item);
    const std::int32_t activeItem = runtime::SubtractInt32Wrapping(item, load(g_ServerContext.NotReleasedItem));
    const std::int32_t userCount = load(g_ServerContext.User);
    const std::int32_t activeUser = runtime::SubtractInt32Wrapping(userCount, load(g_ServerContext.NotReleasedUser));

    // Each release-failure lane is read a second time.
    const std::int32_t maxSerializerTime = load(g_ServerContext.MaxSerializerTime);
    const std::int32_t notReleasedAirShip = load(g_ServerContext.NotReleasedAirShip);
    const std::int32_t notReleasedAuction = load(g_ServerContext.NotReleasedAuction);
    const std::int32_t notReleasedTrade = load(g_ServerContext.NotReleasedTrade);
    const std::int32_t notReleasedInZone = load(g_ServerContext.NotReleasedInZone);
    const std::int32_t notReleasedDoor = load(g_ServerContext.NotReleasedDoor);
    const std::int32_t notReleasedUserSocket = load(g_ServerContext.NotReleasedUserSocket);
    const std::int32_t notReleasedNpc = load(g_ServerContext.NotReleasedNpc);
    const std::int32_t notReleasedItem = load(g_ServerContext.NotReleasedItem);
    const std::int32_t notReleasedUser = load(g_ServerContext.NotReleasedUser);

    FormatUtf16To(
        message.data(), 0x4fff,
        u"Context : [Active:Not Released] User[%d:%d] Item[%d:%d] "
        u"NPC[%d:%d] UserSocket[%d:%d] Door[%d:%d] InZone[%d:%d] "
        u"Trade[%d:%d] Auction[%d:%d] AirShip[%d:%d] "
        u"MaxSerializerTime[%d]",
        activeUser, notReleasedUser, activeItem, notReleasedItem, activeNpc, notReleasedNpc, activeUserSocket,
        notReleasedUserSocket, activeDoor, notReleasedDoor, activeInZone, notReleasedInZone, activeTrade, notReleasedTrade,
        activeAuction, notReleasedAuction, activeAirShip, notReleasedAirShip, maxSerializerTime
    );
    socket->SendSystemMessage(u"SYS", message.data());

    g_npcserver.Send(
        "cddSS", 0x99, 0, runtime::Int32FromBits(static_cast<std::uint32_t>(user->m_nId)),
        // Current Windows wchar_t is the UTF-16 wire type consumed by `S`.
        // Use the equivalent target code units on hosts whose
        // wchar_t is four bytes, passing L"npcserver_stat" there truncates
        // the command to one code unit at the variadic packet boundary.
        u"npcserver_stat", static_cast<const char16_t*>(nullptr)
    );
    return false;
}

