bool quest_npc_log(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0053a13c.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//quest_npc_log [get/inc/del/npc_get/npc_inc] quest_id npc_id log_type");
        return false;
    }

    const int questId = WindowsWtol(tokens[1].data());
    const int npcId = WindowsWtol(tokens[2].data());
    const UserNPCLogType logType = static_cast<UserNPCLogType>(WindowsWtol(tokens[3].data()));

    std::u16string joinedText(tokens[0].data());
    for (std::size_t index = 1; index < tokens.size(); ++index) {
        joinedText.push_back(L' ');
        joinedText.append(tokens[index].data());
    }
    std::array<char16_t, 128> joinedCommand{};
    const std::size_t joinedLength = std::min(joinedText.size(), joinedCommand.size() - 1);
    std::copy_n(joinedText.data(), joinedLength, joinedCommand.data());

    std::array<char16_t, 256> result{};
    std::array<char16_t, 28> targetName{};
    std::array<char16_t, 16> targetAccount{};
    User* target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        target = user;
    }
    if (target == nullptr) {
        return false;
    }
    CopyBuilderText(targetName.data(), 0x19, target->GetName());
    const std::u16string targetAccountText(target->m_sAccountName.data());
    CopyBuilderText(targetAccount.data(), 0x0f, targetAccountText.c_str());
    CSharedCreatureData* const data = target->m_data;
    if (data == nullptr) {
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"get") == 0) {
        const int count = data->GetUserNPCLog(QUEST_NORMAL, questId, npcId, logType);
        const char16_t* const messageFormat =
            count == 0 ? u"get failed (%s : %s) ( quest_id:%d, npc_id:%d)" : u"(%s : %s) (quest_id:%d, npc_id:%d) count: %d";
        FormatUtf16To(
            result.data(), result.size(), messageFormat, targetName.data(), targetAccount.data(), questId, npcId, count
        );
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"inc") == 0) {
        const int increased = target->IncreaseQuestNPCLog(questId, logType, npcId, 0);
        if (increased == 0) {
            FormatUtf16To(
                result.data(), result.size(), u"increase failed (%s : %s) ( quest_id:%d, npc_id:%d)", targetName.data(),
                targetAccount.data(), questId, npcId
            );
        } else {
            const int count = data->GetUserNPCLog(QUEST_NORMAL, questId, npcId, logType);
            FormatUtf16To(
                result.data(), result.size(), u"(%s : %s) (quest_id:%d, npc_id:%d) count: %d", targetName.data(),
                targetAccount.data(), questId, npcId, count
            );
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"del") == 0) {
        const bool deleted = data->DeleteUserNPCLog(QUEST_NORMAL, questId, npcId, logType);
        const char16_t* const messageFormat =
            deleted ? u"(%s : %s) (quest_id:%d, npc_id:%d) deleted" : u"delete failed (%s : %s) ( quest_id:%d, npc_id:%d)";
        FormatUtf16To(result.data(), result.size(), messageFormat, targetName.data(), targetAccount.data(), questId, npcId);
    } else {
        const bool npcGet = CompareBuilderTextIgnoreCase(tokens[0].data(), u"npc_get") == 0;
        const bool npcInc = !npcGet && CompareBuilderTextIgnoreCase(tokens[0].data(), u"npc_inc") == 0;
        if (npcGet || npcInc) {
            CNPC* const npc = user->m_spTarget.GetNPC();
            if (npc == nullptr) {
                FormatUtf16To(result.data(), result.size(), u"Target is not a NPC");
            } else {
                CPacketHelperEx<20480> packet;
                packet.Assemble("ddd", 0, questId, static_cast<int>(logType));
                const int packetSize = packet.GetLength();
                const std::uint32_t objectId = npc->Id();
                const CSmartID smartId = npc->GetSmartID();
                const char16_t* const npcCommand = npcGet ? u"quest_npc_log npc_get" : u"quest_npc_log npc_inc";
                const std::u16string targetCommand = std::u16string(joinedCommand.data());
                g_npcserver.Send(
                    "cddSSb", 0x99, smartId.Sid(), objectId, npcCommand, targetCommand.c_str(), packetSize,
                    packet.GetPacket()
                );
                const int actualNpcId = npc->GetNPCId();
                const char16_t* const messageFormat = npcGet
                    ? u"(%s : %s) (quest_id:%d, npc_id:%d) npc_get sent to NPC Server"
                    : u"(%s : %s) (quest_id:%d, npc_id:%d) npc_inc sent to NPC Server";
                FormatUtf16To(
                    result.data(), result.size(), messageFormat, targetName.data(), targetAccount.data(), questId,
                    actualNpcId
                );
            }
        }
    }

    socket->SendSystemMessage(u"SYS", result.data());
    return false;
}

