bool ResetBeautyItem(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0053c85c.
    L2_GUARD_FUNCTION();
    if (user == nullptr) {
        return false;
    }

    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        socket->SendSystemMessage(u"SYS", u"Target is NULL!!]");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 3, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//resetbeautyitem [hair_id] [face_id] [color_id]");
        return false;
    }

    const int hairId = WindowsWtol(tokens[0].data());
    const int faceId = WindowsWtol(tokens[1].data());
    const int colorId = WindowsWtol(tokens[2].data());
    CPacketHelperEx<20480> packet;
    std::int64_t adenaPrice = 0;
    std::int64_t beautyCoinPrice = 0;
    if (runtime::raw_atomic::ExchangeI32(&target->m_lWaitItemJob, 1) == 1) {
        return false;
    }

    const auto resetItem = [&target, &packet, &adenaPrice,
                               &beautyCoinPrice](const Beauty::BeautyState state, const int primary, const int secondary) {
        CBeautyManager* const manager = CBeautyManager::Inst();
        const int targetDatabaseId = static_cast<int>(target->GetDBID());
        return manager->ResetBeautyItem(state, primary, secondary, targetDatabaseId, packet, adenaPrice, beautyCoinPrice, 1);
    };
    if (!resetItem(Beauty::HAIR, 0, hairId) || !resetItem(Beauty::FACE, 0, faceId) ||
        !resetItem(Beauty::COLOR, hairId, colorId)) {
        runtime::raw_atomic::ExchangeI32(&target->m_lWaitItemJob, 0);
        return false;
    }

    db.RequestResetBeautyItem(target, 1, 0, packet);
    return false;
}

bool BuyBeautyItem(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0053bf50.
    L2_GUARD_FUNCTION();
    if (user == nullptr) {
        return false;
    }

    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        socket->SendSystemMessage(u"SYS", u"Target is NULL!!]");
        return false;
    }
    if (target->m_BeautyPurchase.m_nLoaded != 1) {
        CBeautyManager::Inst()->RequestBeautyPurchaseList(*target, 0);
        socket->SendSystemMessage(u"SYS", u"Wait until load beauty purchase list");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 3, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//buybeautyitem [hair_id] [face_id] [color_id]");
        return false;
    }

    const int hairId = WindowsWtol(tokens[0].data());
    const int faceId = WindowsWtol(tokens[1].data());
    const int colorId = WindowsWtol(tokens[2].data());
    CPacketHelperEx<20480> boughtPacket;
    CPacketHelperEx<20480> ownedPacket;
    std::int64_t adenaPrice = 0;
    std::int64_t beautyCoinPrice = 0;
    if (runtime::raw_atomic::ExchangeI32(&target->m_lWaitItemJob, 1) == 1) {
        socket->SendSystemMessage(u"SYS", u"//buybeautyitem fail!!");
        return false;
    }

    const auto appendItem = [&](const Beauty::BeautyState state, const int primary, const int secondary) {
        if (target->HaveBeautyItem(static_cast<int>(state), primary, secondary)) {
            ownedPacket.Assemble("dd", static_cast<int>(state), secondary);
            return true;
        }
        CBeautyManager* const manager = CBeautyManager::Inst();
        const int targetDatabaseId = static_cast<int>(target->GetDBID());
        return manager->BuyBeautyItem(
            state, primary, secondary, targetDatabaseId, boughtPacket, adenaPrice, beautyCoinPrice, 1
        );
    };

    if (!appendItem(Beauty::HAIR, 0, hairId) || !appendItem(Beauty::FACE, 0, faceId) ||
        !appendItem(Beauty::COLOR, hairId, colorId)) {
        runtime::raw_atomic::ExchangeI32(&target->m_lWaitItemJob, 0);
        return false;
    }

    CPacketHelperEx<20480> packet;
    const auto appendSection = [&packet](CPacketHelperEx<20480>& section) {
        const int count = section.GetAssembledCount();
        if (count == 0) {
            packet.Assemble("d", 0);
        } else {
            packet.Assemble("db", count, section.GetLength(), section.GetPacket());
        }
    };
    appendSection(ownedPacket);
    appendSection(boughtPacket);
    db.RequestBuyBeautyItem(target, 1, 0, 0, packet);
    socket->SendSystemMessage(u"SYS", u"//buybeautyitem success!!");
    return false;
}

