bool RewardSkillEnchant(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x00545528.
    L2_GUARD_FUNCTION();
    CObject* const selected = user->m_spTarget.GetObjectW();
    if (selected == nullptr || !selected->IsPC()) {
        socket->SendSystemMessage(u"SYS", u"Invalid Target!!");
        return false;
    }

    User* const target = selected->CastUser();
    std::int32_t rewardSp = 0;
    std::int32_t rewardItemCount = 0;
    {
        L2_GUARD(target->m_AcquiredSkillsSect);
        for (const auto& entry : target->m_AcquiredSkills) {
            const AcquiredSkillInfo& skill = entry.second;
            if (skill.m_nLevel <= 100) {
                continue;
            }
            rewardSp = runtime::AddInt32Wrapping(
                rewardSp, g_SkillEnchantDB.GetRewardSP(entry.first, skill.m_nLevel, target->GetClass())
            );
            rewardItemCount = runtime::AddInt32Wrapping(
                rewardItemCount, g_SkillEnchantDB.GetRewardItemCount(entry.first, skill.m_nLevel, target->Level())
            );
        }
    }

    if (rewardSp < 0) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"reward sp invalid! [%s][%d]",
        //     target->GetName(),
        //     rewardSp)
        // Previous: L2_LOG_ERROR(Log,
        //     L"reward sp invalid! [%s][%d]", target->GetName(), rewardSp)
        // L2_LOG_ERROR(Log,
        //     L"[builder rewards] Negative SP reward %d for '%s' was replaced "
        //     L"with zero.",
        //     rewardSp,
        //     target->GetName())
        L2_LOG_ERROR(
            Log,
            u"[builder rewards] Negative SP reward %d for '%s' was replaced "
            u"with zero.",
            rewardSp, target->GetName()
        );
        rewardSp = 0;
    }
    if (rewardItemCount < 0 || rewardItemCount > 8000) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"reward item count invalid! [%s][%d]",
        //     target->GetName(),
        //     rewardItemCount)
        // Previous: L2_LOG_ERROR(Log,
        //     L"reward item count invalid! [%s][%d]",
        //     target->GetName(), rewardItemCount)
        // L2_LOG_ERROR(Log,
        //     L"[builder rewards] Item reward count %d for '%s' is outside "
        //     L"0..8000 and was replaced with zero.",
        //     rewardItemCount,
        //     target->GetName())
        L2_LOG_ERROR(
            Log,
            u"[builder rewards] Item reward count %d for '%s' is outside "
            u"0..8000 and was replaced with zero.",
            rewardItemCount, target->GetName()
        );
        rewardItemCount = 0;
    }

    const std::int64_t newSp = target->SPInc(rewardSp);
    target->GetSocket()->Send("chccQ", 0x62, SystemMessageId::OBTAINED_SP, 1, 6, newSp);

    CObject* const rewardObject = g_ObjectDB.GetObjectW(0x7662, false);
    if (rewardObject != nullptr && rewardObject->IsItem()) {
        std::optional<ItemOptionKey> optionKey;
        std::optional<BaseAttribute> attribute;
        {
            L2_WRITE_GUARD(target->m_inv);
            optionKey.emplace();
            attribute.emplace();
            static_cast<void>(target->AddItemToInventory(
                0x7662, static_cast<std::int64_t>(rewardItemCount), ItemGetReason::GetFromNpc, 0, 0, 0, *optionKey, 0,
                *attribute
            ));
        }
    }

    target->DeleteAllAcquireSkills(true);
    user->AcquireAllHonorsSkill();
    target->ValidateChanged(VB_MAX);
    target->ParamChanged(PCB_USER | PCB_CHAR_BUILDERCMD);
    return false;
}

bool mentor(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x00555038.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//mentor command blablabla...");
        return false;
    }

    const auto checkAccess = [socket](const int maximum, const int) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return -1;
        }
        int builderLevel = 0;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        return builderLevel != 0 && builderLevel <= maximum ? 1 : 0;
    };

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"add_mentee") == 0) {
        const int access = checkAccess(2, 0x8198);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//mentor add_mentee mentee_name");
            return false;
        }
        const std::u16string lowerName = LowerUntruncatedMentorCharacterName(tokens[1].data());
        CSPointer<User> target = GetUserFromNameMap(g_nWorldId, lowerName);
        if (!target) {
            socket->SendSystemMessage(u"SYS", u"target is not in the world.");
            return false;
        }
        user->AddMentee(target.get());
        socket->SendSystemMessage(u"SYS", u"[add_mentee] cmd accept");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"delete_mentee") == 0) {
        const int access = checkAccess(2, 0x81b3);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (!user->IsHaveMentee()) {
            socket->SendSystemMessage(u"SYS", u"[delete_mentee] you are not mentor");
            return false;
        }
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//mentor delete_mentee mentee_name");
            return false;
        }
        const std::u16string lowerName = LowerUntruncatedMentorCharacterName(tokens[1].data());
        CSPointer<User> target = GetUserFromNameMap(g_nWorldId, lowerName);
        if (!target) {
            socket->SendSystemMessage(u"SYS", u"target is not in the world.");
            return false;
        }
        user->EndMentoring(static_cast<int>(target->GetDBID()), 2);
        socket->SendSystemMessage(u"SYS", u"[delete_mentee] cmd accept");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"reset_mentor") == 0) {
        const int access = checkAccess(2, 0x81d3);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//mentor delete_mentee mentee_char_id");
            return false;
        }
        if (!user->IsAlreadyHaveMentor()) {
            socket->SendSystemMessage(u"SYS", u"[reset_mentor] you are not mentee");
            return false;
        }
        user->EndMentoring(WindowsWtol(tokens[1].data()), 3);
        socket->SendSystemMessage(u"SYS", u"[reset_mentor] cmd accept");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"show_mentee") == 0) {
        user->ShowMenteeList();
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"show_mentor") == 0) {
        user->ShowMentorInfo();
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"reset_penalty") == 0) {
        const int access = checkAccess(4, 0x81f1);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        CObject* const selected = user->m_spTarget.GetObjectW();
        if (selected != nullptr && selected->IsPC()) {
            User* const target = selected->CastUser();
            target->SetMentorPenaltyEndTime(0);
            db.RequestResetMentorPenalty(*target, static_cast<int>(target->GetDBID()));
        }
        socket->SendSystemMessage(u"SYS", u"[reset_penalty] cmd accept");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"show_penalty") == 0) {
        const int access = checkAccess(3, 0x81ff);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        CObject* const selected = user->m_spTarget.GetObjectW();
        if (selected == nullptr || !selected->IsPC()) {
            return false;
        }
        User* const target = selected->CastUser();
        const int penalty = target->GetMentorPenaltyEndTimeLeft();
        if (penalty <= 0) {
            socket->SendSystemMessage(u"SYS", u"target has no penalty");
            return false;
        }
        std::array<char16_t, 20480> message{};
        FormatUtf16To(
            message.data(), message.size(), u"Left Penalty Time : [%d] days [%d] hours [%d] minutes [%d] seconds",
            penalty / 86400, (penalty % 86400) / 3600, (penalty % 3600) / 60, penalty % 60
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    return false;
}

bool m_test(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x0053d090.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 4, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//mtest cmd mentor_name mentee_name param1");
        return false;
    }

    const int commandId = WindowsWtol(tokens[0].data());
    CPacketHelperEx<20480> packet;
    int packetId = -1;
    const char16_t* packetName = nullptr;
    if (commandId == 0) {
        packet.Assemble("S", std::u16string(tokens[2].data()).c_str());
        packetId = 0xb7;
        packetName = u"C_EX_REQUEST_MENTOR_ADD";
    } else if (commandId == 1) {
        packet.Assemble("dS", 1, std::u16string(tokens[1].data()).c_str());
        packetId = 0xb4;
        packetName = u"C_EX_MENTOR_ADD";
    } else if (commandId == 2) {
        packet.Assemble("dS", WindowsWtol(tokens[3].data()), std::u16string(tokens[2].data()).c_str());
        packetId = 0xb5;
        packetName = u"C_EX_MENTOR_CANCEL";
    } else if (commandId == 3) {
        packetId = 0xb6;
        packetName = u"C_EX_MENTOR_LIST";
    }

    UserPacketExCallback callback = &DummyUserPacketEx;
    if (packetId >= 0) {
        socket->SendSystemMessage(u"SYS", packetName);
        callback = g_UserPacketEx.GetCallback(packetId);
    }
    return callback(socket, reinterpret_cast<const std::uint8_t*>(packet.GetPacket()));
}

