bool set_daily_reset_time(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x00575bc4.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//set_daily_reset_time reset_type_name hhmm");
        return false;
    }

    const int resetValue = WindowsWtol(tokens[1].data());
    if (static_cast<std::uint32_t>(resetValue / 100) >= 25U) {
        socket->SendSystemMessage(u"SYS", u"invalid hour");
        return false;
    }
    if (static_cast<std::uint32_t>(resetValue % 100) >= 60U) {
        socket->SendSystemMessage(u"SYS", u"invalid minute");
        return false;
    }

    std::array<char16_t, 8> resetTime{};
    FormatUtf16To(resetTime.data(), resetTime.size(), u"%02d:%02d", resetValue / 100, resetValue % 100);
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"daily_pccafe_point") == 0) {
        CEvent* const event = CEventManager::inst().GetEvent(GAME_EVENT::ET_PCCAFE_SETTING);
        if (event != nullptr) {
            static_cast<CEvent_PCCafe*>(event)->SetDailyResetTime(resetValue);
        }
        std::array<char16_t, 128> message{};
        FormatUtf16To(message.data(), message.size(), u"Current PC Cafe Daily Point Reset Time = %ls", resetTime.data());
        socket->SendSystemMessage(u"SYS", message.data());
    } else {
        socket->SendSystemMessage(u"SYS", u"Not Defined Type Name");
    }

    db.RequestSetDailyResetTime(tokens[0].data(), std::u16string(resetTime.data()).c_str());
    return false;
}

