bool ShowUserLimit(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x0052054c.
    L2_GUARD_FUNCTION();
    std::array<char, 12> narrow{};
    const auto result = std::to_chars(
        narrow.data(), narrow.data() + narrow.size() - 1, static_cast<std::int32_t>(g_nServerUserCountLimit), 10
    );
    std::array<char16_t, 8> text{};
    if (result.ec == std::errc{}) {
        const std::size_t length = static_cast<std::size_t>(result.ptr - narrow.data());
        if (length < text.size()) {
            for (std::size_t index = 0; index < length; ++index) {
                text[index] = static_cast<unsigned char>(narrow[index]);
            }
        }
    }
    if (user != nullptr && socket != nullptr) {
        socket->SendSystemMessage(u"SYS", text.data());
    }
    return false;
}

