bool show_target_pos(CUserSocket* socket, User* user, char16_t*) {
    // Current L2Server 0x004d9b40.
    L2_GUARD_FUNCTION();

    CObject* target = user->m_spTarget.GetObjectW();
    if (target == nullptr) {
        target = user;
    }
    const FVector targetPosition = static_cast<CWorldObject*>(target)->GetPos();
    const FVector userPosition = user->GetPos();
    const double deltaX = userPosition.x - targetPosition.x;
    const double deltaY = userPosition.y - targetPosition.y;
    const double deltaZ = userPosition.z - targetPosition.z;
    const double distance = std::sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);

    std::array<char16_t, 2048> message{};
    FormatUtf16To(
        message.data(), message.size(), u"targetPos [%d, %d, %d] dist[%d]",
        runtime::Win64CvttDoubleToInt32(targetPosition.x), runtime::Win64CvttDoubleToInt32(targetPosition.y),
        runtime::Win64CvttDoubleToInt32(targetPosition.z), runtime::Win64CvttDoubleToInt32(distance)
    );
    socket->SendSystemMessage(u"SYS", message.data());

    CCreature* const targetCreature = user->m_spTarget.GetCreature();
    if (targetCreature != nullptr) {
        FormatUtf16To(
            message.data(), message.size(), u"dir[%d] mydir[%d]",
            static_cast<unsigned int>(static_cast<std::uint16_t>(targetCreature->m_data->GetDirByInt())),
            static_cast<unsigned int>(static_cast<std::uint16_t>(user->m_data->GetDirByInt()))
        );
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

