bool add_residence_skill(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0053532c.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do add_residence_skill command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//add_residence_skill pledge residence_number");
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[0].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        socket->SendSystemMessage(u"SYS", u"Invalid Pledge Name.");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[1].data());
    CResidence* const residence = g_ResidenceDB.GetResidence(residenceId);
    if (residence == nullptr) {
        socket->SendSystemMessage(u"SYS", u"Invalid Residence id.");
        return false;
    }

    if (!residence->IsDominion()) {
        if (residence->GetResidenceOwnerID() != static_cast<int>(pledge->GetDbId())) {
            socket->SendSystemMessage(u"SYS", u"This pledge doesn't own this residence.");
            return false;
        }
        residence->AddResidenceSkill(*pledge.get(), CastleType::CASTLE_NOTHING);
        return false;
    }

    socket->SendSystemMessage(
        u"SYS", u"add_residence_skill of dominion works different from other residence types. use carefully."
    );
    CDominion* const dominion = residence->CastDominion();
    if (dominion == nullptr) {
        return false;
    }
    COwnThing* const ownThing = dominion->GetOwnThing();
    if (ownThing != nullptr && ownThing->GetOwningResidenceID() == dominion->GetResidenceID()) {
        dominion->AddAllResidenceSkill();
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"This pledge doesn't have the ownthing of my dominion.");
    return false;
}

bool remove_residence_skill(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0053576c.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do remove_residence_skill command");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//remove_residence_skill pledge residence_number");
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[0].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        socket->SendSystemMessage(u"SYS", u"Invalid Pledge Name.");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[1].data());
    CResidence* const residence = g_ResidenceDB.GetResidence(residenceId);
    if (residence == nullptr) {
        socket->SendSystemMessage(u"SYS", u"Invalid Residence id.");
        return false;
    }

    if (!residence->IsDominion()) {
        residence->RemoveResidenceSkill(*pledge.get());
    } else {
        residence->CastDominion()->RemoveAllResidenceSkill(pledge);
    }
    return false;
}

