bool _NpcSkill(User* user, CUserSocket* socket) {
    // Current L2Server 0x0050f078.
    L2_GUARD_FUNCTION();
    CNPC* const target = user->m_spTarget.GetNPC();
    if (target == nullptr) {
        socket->SendSystemMessage(u"SYS", u"target should be NPC");
        return false;
    }

    std::array<char16_t, 1024> message{};
    std::vector<std::int64_t>& skills = target->m_pClassConst->m_SkillList;
    FormatUtf16To(message.data(), message.size(), u"Npc Skills [%d]", static_cast<int>(skills.size()));
    socket->SendSystemMessage(u"SYS", message.data());

    std::int32_t index = 0;
    while (static_cast<std::uint64_t>(static_cast<std::int64_t>(index)) < static_cast<std::uint64_t>(skills.size())) {
        const std::uint64_t packed = static_cast<std::uint64_t>(skills.data()[index]);
        const std::int32_t skillId = static_cast<std::int32_t>(packed >> 32U);
        const std::uint16_t level = static_cast<std::uint16_t>(packed >> 16U);
        const std::uint16_t subLevel = static_cast<std::uint16_t>(packed);
        const CSkillInfo* const skillInfo =
            g_SkillDB.GetSkillInfo(CSkillKey(skillId, static_cast<int>(level), static_cast<int>(subLevel)), user);
        if (skillInfo == nullptr) {
            FormatUtf16To(
                message.data(), message.size(), u"unregistered skill (id:%d, level:%d sublevel:%d)", skillId,
                static_cast<int>(level), static_cast<int>(subLevel)
            );
        } else {
            FormatUtf16To(
                message.data(), message.size(), u"skill [name:%s][id:%d][level:%d][sublevel:%d]", skillInfo->m_pszName,
                skillId, static_cast<int>(level), static_cast<int>(subLevel)
            );
        }
        socket->SendSystemMessage(u"SYS", message.data());
        index = runtime::AddInt32Wrapping(index, 1);
    }

    socket->SendSystemMessage(u"SYS", u"Npc Skills End");
    return true;
}

