bool set_auction_status(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x005694ec.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//set_auction_status [auction_id] [none | start | done | done_now | index]");
        return false;
    }

    const int auctionId = WindowsWtol(tokens[0].data());
    CAuction* const auction = CAuctionManager::inst().GetAuction(auctionId);
    if (auction == nullptr) {
        socket->SendSystemMessage(u"SYS", u"cannot find auction");
        return false;
    }

    bool setDurationToZero = false;
    AuctionStatus status = AS_NONE;
    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"none") == 0) {
        status = AS_NONE;
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"start") == 0) {
        status = AS_DOING;
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"done") == 0) {
        status = AS_DONE;
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"done_now") == 0) {
        status = AS_DOING;
        setDurationToZero = true;
    } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"index") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//set_auction_status [auction_id] index [index_number]");
            return false;
        }

        const int itemIndex = WindowsWtol(tokens[2].data());
        const int ownerDatabaseId = auction->GetAuctionItem().m_nOwnerDBID;
        CAuctionNPC* const npc = CAuctionNPCDB::inst().GetAuctionNPC(ownerDatabaseId);
        if (npc == nullptr) {
            socket->SendSystemMessage(u"SYS", u"cannot find auction NPC");
            return false;
        }

        const NPCAuctionItem npcItem = npc->GetAuctionItem(itemIndex);
        if (npcItem.m_nItemType == 0 && npcItem.m_nItemAmount == 0 && npcItem.m_nItemPrice == 0) {
            socket->SendSystemMessage(u"SYS", u"cannot find auction item, index error");
            return false;
        }

        // The current callback leaves AuctionItem's explicit +0x0c lane
        // uninitialized before the complete 0x18-byte owner copy.
        AuctionItem item;
        item.m_nOwnerDBID = ownerDatabaseId;
        item.m_nItemIndex = itemIndex;
        item.m_nClassID = npcItem.m_nItemType;
        item.m_nAmount = npcItem.m_nItemAmount;
        auction->SetAuctionItemInfo(item, runtime::Int32FromBits(static_cast<std::uint32_t>(npcItem.m_nItemPrice)));
        socket->SendSystemMessage(u"SYS", u"accepted set_auction_status command...");
        return false;
    } else {
        socket->SendSystemMessage(u"SYS", u"//set_auction_status [auction_id] [none|start|done|done_now|index]");
        return false;
    }

    auction->SetAuctionStatus(status);
    if (setDurationToZero) {
        auction->SetAuctionDuration(0);
    }
    socket->SendSystemMessage(u"SYS", u"accepted set_auction_status command...");
    return false;
}

