bool pick_items(CUserSocket*, User* user, char16_t*) {
    // Current L2Server 0x0051a5c8. Local TLMFunc::CanDo 0x004db340.
    L2_GUARD_FUNCTION();

    CTLMFilterRect filter(user, 2048.0);

    class TLMFunc final : public CTLMFunc {
    public:
        explicit TLMFunc(User* const user) :
            m_user(user), m_position(user->GetPos()), m_inZoneId(static_cast<int>(user->GetInZoneID())) {}

        bool CanDo(CObject* object, double) override {
            CItem* const item = object->CastItem();
            CSharedItemData* const data = item->m_data;
            if (data->m_bIsActive) {
                const double deltaX = data->m_Pos.x - m_position.x;
                const double deltaY = data->m_Pos.y - m_position.y;
                const double deltaZ = data->m_Pos.z - m_position.z;
                const double distance = std::sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);
                const std::int32_t heightDifference = runtime::AbsoluteInt32Wrapping(
                    runtime::Win64CvttDoubleToInt32(item->m_data->m_Pos.z - m_position.z)
                );
                if (heightDifference < 0x1f5 && distance < 450.0) {
                    CWorld& sightWorld = CWorld::Inst();
                    CSharedItemData* const sightData = item->m_data;
                    if (sightWorld.GetGeo()->CanSee(m_position, sightData->m_Pos, m_inZoneId, true) &&
                        CWorld::Inst().PickItemCond(item, m_user)) {
                        CWorld::Inst().DoAsyncPickItem(item);
                        CWorld::Inst().DoAsyncAddItemToInventory(item, m_user);
                    }
                }
            }
            return true;
        }

    private:
        User* m_user;
        FVector m_position;
        int m_inZoneId;
    };

    TLMFunc function(user);
    FOR_ALL_NEIGHBOR_ITEM_RECT(&filter, &function);
    return false;
}

