bool _set_castle_owner(User* user, CUserSocket* socket, CResidence* residence, char16_t* pledgeName, const int castleType) {
    // Current L2Server 0x0052e2a4.
    L2_GUARD_FUNCTION();
    if (user == nullptr) {
        socket->SendSystemMessage(u"SYS", u"User is not valid");
        return false;
    }

    std::u16string pledgeName16 = std::u16string(pledgeName);
    CSPointer<CPledge> pledge =
        CPledge::FindPledge(user->m_data->m_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName16.data()));
    if (!pledge) {
        socket->SendSystemMessage(
            u"SYS",
            user->m_data->m_nWorldId == g_nWorldId ? u"you can use this command only after owner pledge is loaded"
                                                   : u"Raid User cannot do set_castle_owner command"
        );
        return false;
    }

    const auto auditAccepted = [socket, residence, pledgeName](const int) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return;
        }

        std::uint32_t builderDbId = 0;
        std::uint32_t builderAccountId = 0;
        std::array<char16_t, 32> builderName{};
        std::array<char16_t, 16> builderAccount{};
        FVector builderPosition{};
        {
            L2_GUARD(*builder->m_lock);
            builderDbId = builder->GetDBID();
            builderAccountId = builder->GetAccountID();
            CopyBuilderText(builderName.data(), 0x19, builder->GetName());
            const std::u16string account(builder->m_sAccountName.data());
            CopyBuilderText(builderAccount.data(), 0x0f, account.c_str());
            builderPosition = builder->GetPos();
        }

        const int residenceId = residence->m_data != nullptr ? residence->m_data->m_nResidenceID : 0;
        // Log.Add(
        //     LOG_BOTH,
        //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,%I64d,%s,"
        //     L",,,,,,,,,,,%s,%s,,,",
        //     static_cast<long long>(0x218),
        //     static_cast<long long>(builderDbId),
        //     static_cast<long long>(builderAccountId),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.x)),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.y)),
        //     static_cast<long long>(
        //         runtime::Win64CvttDoubleToInt32(
        //             builderPosition.z)),
        //     static_cast<long long>(residenceId),
        //     pledgeName,
        //     builderName.data(),
        //     builderAccount.data())
        Log.Add(
            LOG_BOTH,
            u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,%I64d,%s,"
            u",,,,,,,,,,,%s,%s,,,",
            static_cast<long long>(0x218), static_cast<long long>(builderDbId), static_cast<long long>(builderAccountId),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.x)),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.y)),
            static_cast<long long>(runtime::Win64CvttDoubleToInt32(builderPosition.z)), static_cast<long long>(residenceId),
            pledgeName, builderName.data(), builderAccount.data()
        );
        socket->SendSystemMessage(u"SYS", u"builder command[set_castle_owner] accepted");
    };

    if (residence->IsCastle()) {
        CCastle* const castle = static_cast<CCastle*>(residence);
        if (pledge->GetCastle() != nullptr) {
            socket->SendSystemMessage(u"SYS", u"you already have one castle. 'reset_castle_owner' first!!");
            return false;
        }

        const std::uint32_t oldOwnerId = castle->m_data->m_nResidenceOwnerID;
        if (oldOwnerId != 0) {
            CSPointer<CPledge> oldOwner = CPledge::FindPledge(g_nWorldId, oldOwnerId);
            if (oldOwner) {
                oldOwner->SetCastle(nullptr);
                oldOwner->Save(6);
                oldOwner->UpdatePledgeInfoPacket();
                oldOwner->UpdateInfoWindowPacket();
                oldOwner->UnequipMemberCastleItem();
            }
        }

        CFortress* const fortress = pledge->GetFortress();
        if (fortress != nullptr) {
            fortress->ResetOwnership();
        }
        castle->m_data->m_ResidenceType = castleType;
        pledge->SetCastle(castle);
        if (castle->m_pDominion != nullptr) {
            castle->m_pDominion->ChangeDominionStatus(1);
            castle->m_pDominion->m_data->m_nResidenceOwnerID = pledge->GetDbId();
        }
        pledge->Save(6);
        pledge->UpdatePledgeInfoPacket();
        pledge->UpdateInfoWindowPacket();
        castle->SetPledge(pledge.get());

        const int oldOwnerWorldId = castle->m_nPrevOwnerPledgeWorldId;
        const int ownerWorldId = pledge->GetWorldId();
        const int oldOwnerDbId = castle->m_PreviousOwnerPledgeDbId;
        const int ownerDbId = static_cast<int>(pledge->GetDbId());
        db.ReqOwnCastle(castle, ownerDbId, oldOwnerDbId, castleType, ownerWorldId, oldOwnerWorldId);
        db.RequestSetCastleCampaign(castle, -1);
        castle->BroadcastCastleState();
        auditAccepted(0x256f);
        return true;
    }

    if (residence->IsWorldAgit()) {
        CWorldAgit* const worldAgit = static_cast<CWorldAgit*>(residence);
        if (pledge->GetWorldAgit() != nullptr) {
            socket->SendSystemMessage(u"SYS", u"you already have one agit. 'reset_castle_owner' first!!");
            return false;
        }

        const std::uint32_t oldOwnerId = worldAgit->m_data->m_nResidenceOwnerID;
        if (oldOwnerId != 0) {
            CSPointer<CPledge> oldOwner = CPledge::FindPledge(g_nWorldId, oldOwnerId);
            if (oldOwner) {
                oldOwner->SetWorldAgit(nullptr);
                oldOwner->Save(7);
                oldOwner->UpdateInfoWindowPacket();
                oldOwner->UnequipMemberCastleItem();
            }
        }

        pledge->SetWorldAgit(worldAgit);
        pledge->Save(7);
        pledge->UpdateInfoWindowPacket();
        worldAgit->SetPledge(pledge.get());
        if (worldAgit->IsAuctionAgit() && worldAgit->CastAuctionAgit()->m_nAuctionId > 0) {
            worldAgit->CastAuctionAgit()->SetSaleState(SALE_OWNED);
            worldAgit->CastAuctionAgit()->m_nAuctionId = 0;
        }
        db.ReqOwnAgit(worldAgit, static_cast<int>(pledge->GetDbId()));
        auditAccepted(0x25a0);
        return true;
    }

    if (residence->IsFortress()) {
        const unsigned int fortressId =
            residence->m_data != nullptr ? static_cast<unsigned int>(residence->m_data->m_nResidenceID) : 0U;
        if (pledge->CanOwnFortress(fortressId)) {
            static_cast<CFortress*>(residence)->SetOwnership(pledge.get(), false);
            socket->SendSystemMessage(u"SYS", u"set_owner accepted");
        }
        return true;
    }

    if (residence->IsDominion()) {
        socket->SendSystemMessage(
            u"SYS", u"no effect for dominion. you must change castle's owner to change dominion's owner."
        );
    }
    return true;
}

bool set_castle_owner(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x00540254.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    {
        L2_GUARD(*builder->m_lock);
        std::array<char16_t, 32> unusedName{};
        std::array<char16_t, 16> unusedAccount{};
        static_cast<void>(builder->GetDBID());
        static_cast<void>(builder->GetAccountID());
        CopyBuilderText(unusedName.data(), 0x19, builder->GetName());
        const std::u16string account(builder->m_sAccountName.data());
        CopyBuilderText(unusedAccount.data(), 0x0f, account.c_str());
        const FVector unusedPosition = builder->GetPos();
        static_cast<void>(unusedPosition);
    }

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        // Original: u"//set_castle_owner castle type(1:선 2:악) pledge"
        socket->SendSystemMessage(u"SYS", u"//set_castle_owner castle type(1:good 2:evil) pledge");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr) {
        return false;
    }

    const int castleType = WindowsWtol(tokens[1].data());
    if (castleType != 1 && castleType != 2) {
        socket->SendSystemMessage(u"SYS", u"castle type can be only 1 or 2");
        return false;
    }

    static_cast<void>(_set_castle_owner(builder, socket, residence, tokens[2].data(), castleType));
    return false;
}

bool SetCastleType(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004f38e0.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        // Original: u"//set_castle_type castle type(1:선 2:악)"
        socket->SendSystemMessage(u"SYS", u"//set_castle_type castle type(1:good 2:evil)");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr) {
        return false;
    }
    if (!residence->IsCastle()) {
        socket->SendSystemMessage(u"SYS", u"castle only can change type");
        return false;
    }

    const int castleType = WindowsWtol(tokens[1].data());
    if (static_cast<unsigned int>(castleType - 1) >= 2U) {
        socket->SendSystemMessage(u"SYS", u"castle type can be only 1 or 2");
        return false;
    }

    CCastle* const castle = residence->CastCastle();
    castle->m_data->m_ResidenceType = castleType;
    db.RequestSetCastleType(*castle, residenceId, castleType);
    castle->BroadcastCastleState();
    socket->SendSystemMessage(u"SYS", u"set castle type cmd success");
    return false;
}

