bool BuilderCmd_gmchat(CUserSocket* socket, User* user, char16_t* command) {
    // Current L2Server 0x0054dbcc.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//gmchat charname message");
        return false;
    }

    const std::u16string targetName = std::u16string(tokens[0].data());
    const std::u16string lowerName = LowercaseGameName(targetName);
    const std::wstring hostLowerName = Utf16ToWide(lowerName);
    CSPointer<User> target = GetUserFromNameMap(g_nWorldId, lowerName);

    if (!target) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s] fail to try to gmchat [%s] with msg [%s].",
        //     builder->GetName(),
        //     hostLowerName.c_str(),
        //     tokens[1].data())
        // Previous: L2_LOG_ERROR(Log,
        //     L"[%s] fail to try to gmchat [%s] with msg [%s].",
        //     builder->GetName(), hostLowerName.c_str(), tokens[1].data())
        // L2_LOG_ERROR(Log,
        //     L"[builder GM chat] '%s' cannot message '%s': the target was not "
        //     L"found. Message: '%s'.",
        //     builder->GetName(),
        //     hostLowerName.c_str(),
        //     tokens[1].data())
        // L2_LOG_ERROR(Log,
        //     L"[builder GM chat] '%s' cannot message '%s': the target was not "
        //     L"found. Message: '%s'.",
        //     Utf16ToWide(builder->GetName()).c_str(),
        //     hostLowerName.c_str(),
        //     tokens[1].data())
        L2_LOG_ERROR(
            Log,
            u"[builder GM chat] '%s' cannot message '%s': the target was not "
            u"found. Message: '%s'.",
            builder->GetName(), hostLowerName.c_str(), tokens[1].data()
        );
        std::array<char16_t, 56> message{};
        FormatUtf16To(message.data(), message.size(), u"Cannot find GM.[%s]", hostLowerName.c_str());
        builder->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    if (!target->IsBuilder()) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s] fail to try to gmchat [%s] with msg [%s]. not gm.",
        //     builder->GetName(),
        //     hostLowerName.c_str(),
        //     tokens[1].data())
        // Previous: L2_LOG_ERROR(Log,
        //     L"[%s] fail to try to gmchat [%s] with msg [%s]. not gm.",
        //     builder->GetName(), hostLowerName.c_str(), tokens[1].data())
        // L2_LOG_ERROR(Log,
        //     L"[builder GM chat] '%s' cannot message '%s': the target is not a "
        //     L"builder. Message: '%s'.",
        //     builder->GetName(),
        //     hostLowerName.c_str(),
        //     tokens[1].data())
        // L2_LOG_ERROR(Log,
        //     L"[builder GM chat] '%s' cannot message '%s': the target is not a "
        //     L"builder. Message: '%s'.",
        //     Utf16ToWide(builder->GetName()).c_str(),
        //     hostLowerName.c_str(),
        //     tokens[1].data())
        L2_LOG_ERROR(
            Log,
            u"[builder GM chat] '%s' cannot message '%s': the target is not a "
            u"builder. Message: '%s'.",
            builder->GetName(), hostLowerName.c_str(), tokens[1].data()
        );
        std::array<char16_t, 128> message{};
        FormatUtf16To(message.data(), message.size(), u"Cannot say gmchat to normal user.[%s]", hostLowerName.c_str());
        builder->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    std::array<char16_t, 56> displayName{};
    FormatUtf16To(displayName.data(), displayName.size(), u"->(GM)%s", user->GetName());
    static_cast<void>(
        builder->Hear(builder, std::u16string(displayName.data()).c_str(), std::u16string(tokens[1].data()).c_str(), 2)
    );

    FormatUtf16To(displayName.data(), displayName.size(), u"(GM)%s", builder->GetName());
    static_cast<void>(
        target->Hear(builder, std::u16string(displayName.data()).c_str(), std::u16string(tokens[1].data()).c_str(), 2)
    );
    return false;
}

