bool BuilderCmd_show_door_hp(CUserSocket* socket, User*, char16_t* command) {
    // Current L2Server 0x004f49bc.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//show_door_hp door");
        return false;
    }

    const int doorId = WindowsWtol(tokens[0].data());
    CDoor* const door = doorId == 0 ? g_DoorDB.GetDoor(tokens[0].data(), 0) : g_DoorDB.GetDoor(doorId);
    if (door == nullptr) {
        return false;
    }

    const double baseHp = door->m_dBaseHp;
    const double maximumHp = door->m_data->m_dMaxHP;
    const double physicalDefence = door->GetPDefend();
    const double magicalDefence = door->GetMDefend();
    const double currentHp = door->GetHP();
    const std::wstring doorName = Utf16ToWide(std::u16string_view(door->m_sDoorName));
    std::array<char16_t, 8216> message{};
    FormatUtf16To(
        message.data(), message.size(),
        u"DOOR[%s]: HP[%d] MAXHP[%d] BASEHP[%d] "
        u"(mdefend:[%d] pdefend:[%d])",
        doorName.c_str(), runtime::Win64CvttDoubleToInt32(currentHp), runtime::Win64CvttDoubleToInt32(maximumHp),
        runtime::Win64CvttDoubleToInt32(baseHp), runtime::Win64CvttDoubleToInt32(magicalDefence),
        runtime::Win64CvttDoubleToInt32(physicalDefence)
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

