bool BuildeCmd_SetEconomicRestriction(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x005004e4.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//set_economic_restriction [on|off]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"켬") == 0) {
        {
            L2_GUARD(socket->mLock);
            socket->m_bEconomicRestriction = true;
            socket->SendSystemMessage(u"SYS", u"Currently, you're EconomicRestriction is true.");
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"끔") == 0) {
        {
            L2_GUARD(socket->mLock);
            socket->m_bEconomicRestriction = false;
            socket->SendSystemMessage(u"SYS", u"Currently, you're EconomicRestriction is false.");
        }
    }
    return false;
}

bool BuilderCmd_FieldCycle(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x005448f4.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//field_cycle command [options]...");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"info") == 0) {
        if (tokenCount < 2) {
            g_FieldCycleSystem.SendDebugInfoTo(socket);
        } else {
            g_FieldCycleSystem.SendDebugInfoTo(WindowsWtol(tokens[1].data()), socket);
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set_step") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel != 0 && builderLevel < 3) {
            if (tokenCount < 3) {
                socket->SendSystemMessage(u"SYS", u"//field_cycle set_step fieldID stepNumber");
            } else {
                g_FieldCycleSystem.ChangeStep(
                    WindowsWtol(tokens[1].data()), WindowsWtol(tokens[2].data()), FieldCycleReason::ByBuilder, nullptr,
                    socket
                );
            }
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"add_point") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel != 0 && builderLevel < 3) {
            if (tokenCount < 3) {
                socket->SendSystemMessage(u"SYS", u"//field_cycle add_point fieldID delta");
            } else {
                g_FieldCycleSystem.AddPoint(
                    WindowsWtol(tokens[1].data()), WindowsWtol(tokens[2].data()), FieldCycleReason::ByBuilder, nullptr,
                    socket
                );
            }
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"interval") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel != 0 && builderLevel < 3) {
            if (tokenCount < 2) {
                socket->SendSystemMessage(u"SYS", u"//field_cycle interval time");
            } else {
                FieldCycleConst::_CYCLE_HEARTBEAT =
                    std::max(1000, runtime::MultiplyInt32Wrapping(WindowsWtol(tokens[1].data()), 1000));
            }
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"expire_time") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel != 0 && builderLevel < 3) {
            if (tokenCount < 3) {
                socket->SendSystemMessage(u"SYS", u"//field_cycle expire_time fieldID second");
            } else if (CFieldCycle* const fieldCycle = g_FieldCycleSystem.GetFieldCycle(WindowsWtol(tokens[1].data()))) {
                fieldCycle->SetExpirationTime(WindowsWtol(tokens[2].data()));
            }
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"next_step") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel != 0 && builderLevel < 3) {
            if (tokenCount < 2) {
                socket->SendSystemMessage(u"SYS", u"//field_cycle next_step fieldID");
            } else if (CFieldCycle* const fieldCycle = g_FieldCycleSystem.GetFieldCycle(WindowsWtol(tokens[1].data()))) {
                socket->SendSystemMessage(
                    u"SYS",
                    fieldCycle->ChangeNextStep() ? u"[//field_cycle next_step] is accepted"
                                                 : u"[//field_cycle next_step] is failed"
                );
            }
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"limit_time") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel != 0 && builderLevel < 3) {
            if (tokenCount < 3) {
                socket->SendSystemMessage(u"SYS", u"//field_cycle limit_time fieldID second");
            } else if (CFieldCycle* const fieldCycle = g_FieldCycleSystem.GetFieldCycle(WindowsWtol(tokens[1].data()))) {
                fieldCycle->SetMissionLimitTime(WindowsWtol(tokens[2].data()));
                socket->SendSystemMessage(u"SYS", u"[//field_cycle next_step] is accepted");
            } else {
                socket->SendSystemMessage(u"SYS", u"[//field_cycle limit_time] is failed");
            }
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"reload_mission") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel != 0 && builderLevel < 2) {
            if (g_L2ServerType == L2ServerType::LIVE) {
                user->SendSystemMessage(u"SYS", u"[//field_cycle reload_mission] is failed: not in live server.");
            } else {
                FieldCycleMissionDB::inst().Reload();
                socket->SendSystemMessage(u"SYS", u"[//field_cycle reload_mission] is accepted");
            }
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"broadcast") == 0) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return true;
        }
        int builderLevel;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        if (builderLevel != 0 && builderLevel < 2) {
            if (tokenCount < 3) {
                socket->SendSystemMessage(u"SYS", u"//field_cycle broadcast fieldID msg");
            } else {
                const int fieldCycleId = WindowsWtol(tokens[1].data());
                const std::u16string targetMessage = std::u16string(tokens[2].data());
                DefaultIOBuffer* const buffer = MakeConstBuffer("cddSdS", 0x4a, 0, 5, u"SYS", -1, targetMessage.c_str());
                g_FieldCycleSystem.BroadcastTo(fieldCycleId, buffer);
                buffer->Release();
                socket->SendSystemMessage(u"SYS", u"[//field_cycle broadcast] is accepted");
            }
        }
        return false;
    }

    return false;
}

