bool user_pvpmatch(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0055f974.
    L2_GUARD_FUNCTION();
    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (command == nullptr || !ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//user_pvpmatch [ready/start/end]");
        return false;
    }

    CPVPMatch2* const match = CPVPMatchSystem::inst().GetMatchByUserLevel(user->Level());
    if (match == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid PVPMatch");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"ready") == 0) {
        static_cast<void>(CPVPMatchSystem::inst().CrataeMatchUsingBuilder(match->GetManagerNpcId(), 2));
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"start") == 0) {
        static_cast<void>(CPVPMatchSystem::inst().CrataeMatchUsingBuilder(match->GetManagerNpcId(), 0));
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"end") == 0) {
        static_cast<void>(CPVPMatchSystem::inst().CrataeMatchUsingBuilder(match->GetManagerNpcId(), 1));
    }
    return false;
}

bool cleft(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0051315c.
    L2_GUARD_FUNCTION();
    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (command == nullptr || !ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//cleft command [options]...");
        return false;
    }

    CCleft& match = Singleton<CCleft>::inst();
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"time_set") == 0) {
        if (tokenCount < 4) {
            socket->SendSystemMessage(u"SYS", u"//cleft time_set combat_time reward_time CAT_period");
        } else {
            match.SetTimeProperty(
                WindowsWtol(tokens[1].data()), WindowsWtol(tokens[2].data()), WindowsWtol(tokens[3].data())
            );
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"register_member_check") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//cleft register_member_check member_count");
        } else {
            match.SetMinRegisterCount(WindowsWtol(tokens[1].data()));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"team_balance") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//cleft team_balance (on|off)");
        } else {
            const bool enabled = std::u16string_view(tokens[1].data()).compare(u"on") == 0;
            socket->SendSystemMessage(u"SYS", enabled ? u"team_balance on" : u"team_balance off");
            match.SetTeamBalance(enabled);
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"show_info") == 0) {
        match.ShowCleftInfo(*user);
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"show_state") == 0) {
        match.ShowCleftState(*user);
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set_point") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//cleft set_point (blue|red) point");
        } else {
            static_cast<void>(
                match.AddPoint(CPVPMatch::GetTeamType(tokens[1].data(), nullptr), WindowsWtol(tokens[2].data()))
            );
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set_winner") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//cleft set_winner (blue|red)");
        } else {
            static_cast<void>(match.SetCleftWinner(CPVPMatch::GetTeamType(tokens[1].data(), nullptr)));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"enter") == 0) {
        static_cast<void>(match.EnterCleftPlayer(*user));
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"join") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//cleft join (blue|red)");
        } else {
            static_cast<void>(match.AddCleftPlayer(CPVPMatch::GetTeamType(tokens[1].data(), nullptr), *user));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"leave") == 0) {
        static_cast<void>(match.RemoveCleftPlayer(static_cast<int>(user->Id())));
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"destroy") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//cleft destroy (center|defence) nPoint");
        } else {
            bool defence = false;
            if (std::u16string_view(tokens[1].data()).compare(u"center") != 0) {
                defence = std::u16string_view(tokens[1].data()).compare(u"defence") == 0;
            }
            match.TowerDestroyed(*user, defence, WindowsWtol(tokens[2].data()));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"next_cat") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//cleft next_cat (blue|red)");
        } else {
            static_cast<void>(match.SelectRandomCat(CPVPMatch::GetTeamType(tokens[1].data(), nullptr)));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"ignore_15") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//cleft ignore_15 (on|off)");
        } else {
            match.m_bIgnore15Min = std::u16string_view(tokens[1].data()).compare(u"on") == 0;
        }
    }
    return false;
}

bool blockupset(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00513774.
    L2_GUARD_FUNCTION();
    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (command == nullptr || !ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//blockupset command [options]...");
        return false;
    }

    CBlockUpsetManager& manager = Singleton<CBlockUpsetManager>::inst();
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"min_member") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//blockupset min_member stage_index member_count");
        } else {
            manager.SetMinRegisterCount(WindowsWtol(tokens[1].data()), WindowsWtol(tokens[2].data()));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"game_period") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//blockupset game_peroid game_period_sec");
        } else {
            manager.m_GamePeriodSec = WindowsWtol(tokens[1].data());
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"vote_wait") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//blockupset vote_wait wait_sec");
        } else {
            manager.m_nVoteWaitSec = WindowsWtol(tokens[1].data());
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"show_info") == 0) {
        manager.ShowBlockUpsetInfo(*user);
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"show_state") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//blockupset show_state stage_index");
        } else {
            manager.ShowBlockUpsetState(WindowsWtol(tokens[1].data()), *user);
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"enter") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//blockupset enter stage_index");
        } else {
            static_cast<void>(manager.EnterBlockUpsetPlayer(WindowsWtol(tokens[1].data()), *user));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"join") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//blockupset join stage_index (blue|red)");
        } else {
            static_cast<void>(manager.AddBlockUpsetWaitingPlayer(
                WindowsWtol(tokens[1].data()), CPVPMatch::GetTeamType(tokens[2].data(), nullptr), *user
            ));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"leave") == 0) {
        static_cast<void>(manager.RemoveBlockUpsetWaitingPlayer(static_cast<int>(user->Id())));
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"add_point") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//blockupset add_point point");
        } else {
            static_cast<void>(manager.AddBlockUpsetPoint(*user, WindowsWtol(tokens[1].data())));
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set_winner") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//blockupset set_winner stage_index (blue|red)");
        } else {
            static_cast<void>(
                manager.SetBlockUpsetWinner(WindowsWtol(tokens[1].data()), CPVPMatch::GetTeamType(tokens[2].data(), nullptr))
            );
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"show_waiting_npc") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(
                u"SYS",
                u"//blockupset show_waiting_npc "
                u"(0-hide|1-show) (blue|red)"
            );
        }
        const int show = WindowsWtol(tokens[1].data());
        static_cast<void>(CPVPMatch::GetTeamType(tokens[2].data(), nullptr));
        manager.ShowWaitingNpcBlock(show != 0);
    }
    return false;
}

bool register_dominion_pledge(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00534210.
    L2_GUARD_FUNCTION();
    if (user == nullptr || user->m_data->m_nWorldId != g_nWorldId) {
        socket->SendSystemMessage(u"SYS", u"Raid User cannot do register_dominion_pledge command");
        return false;
    }

    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    std::optional<std::u16string> account;
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        account.emplace(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, account->c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPosition);

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (command == nullptr || !ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//register_dominion_pledge dominion pledge");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr) {
        socket->SendSystemMessage(u"SYS", u"residence id is invalid.");
        return false;
    }

    CDominion* const dominion = residence->CastDominion();
    if (dominion == nullptr) {
        socket->SendSystemMessage(u"SYS", u"this residence is not dominion.");
        return false;
    }
    if (dominion->GetResidenceState() != RS_REGISTRATION) {
        socket->SendSystemMessage(u"SYS", u"you can register when dominion is waiting registration.");
        return false;
    }

    std::u16string pledgeName = std::u16string(tokens[1].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        socket->SendSystemMessage(u"SYS", u"you can use this command only after owner pledge is loaded");
        return false;
    }

    const int pledgeId = runtime::Int32FromBits(pledge->GetDbId());
    if (pledge->GetCastle() != nullptr || CDominionManager::Inst()->GetPledgeDominionSiegeID(pledgeId) != 0) {
        socket->SendSystemMessage(
            u"SYS",
            u"this pledge owns castle or already registered to "
            u"dominion siege."
        );
        return false;
    }
    if (!dominion->RegisterPledge(pledgeId, true)) {
        socket->SendSystemMessage(u"SYS", u"i don't know reason. but you failed.");
        return false;
    }

    pledge->SetAllOnlineMemberRenamed(dominion->GetResidenceID());
    socket->SendSystemMessage(u"SYS", u"command accepted.");
    return false;
}

