bool show_dominion_registry(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x0055b004.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    std::optional<std::u16string> account;
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        account.emplace(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, account->c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPosition);

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (command == nullptr || !ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//show_dominion_registry dominion");
        return false;
    }

    const int residenceId = WindowsWtol(tokens[0].data());
    CResidence* residence = nullptr;
    if (residenceId == 0) {
        const std::u16string residenceName = std::u16string(tokens[0].data());
        residence = g_ResidenceDB.GetResidence(residenceName.c_str());
    } else {
        residence = g_ResidenceDB.GetResidence(residenceId);
    }
    if (residence == nullptr) {
        socket->SendSystemMessage(u"SYS", u"residence id is invalid.");
        return false;
    }

    CDominion* const dominion = residence->CastDominion();
    if (dominion == nullptr) {
        socket->SendSystemMessage(u"SYS", u"this residence is not dominion.");
        return false;
    }

    CDominionSiegeEntry* const entry = dominion->GetSiegeEntry();
    if (entry == nullptr || entry->IsEmpty()) {
        socket->SendSystemMessage(u"SYS", u"there's no entry for this dominion!");
        return false;
    }

    const auto pledgeList = entry->GetPledgeList();
    const auto userList = entry->GetUserList();
    std::array<char16_t, 512> message{};
    const std::wstring dominionName = dominion->m_data != nullptr
        ? Utf16ToWide(std::u16string_view(dominion->m_data->m_sResidenceName.data()))
        : std::wstring();
    FormatUtf16To(message.data(), message.size(), u"Registry For Dominion : %s", dominionName.c_str());
    socket->SendSystemMessage(u"SYS", message.data());

    FormatUtf16To(message.data(), message.size(), u"Pledge List:");
    socket->SendSystemMessage(u"SYS", message.data());
    int pledgeNumber = 0;
    for (const std::uint32_t pledgeId : pledgeList) {
        CSPointer<CPledge> pledge = CPledge::FindPledge(g_nWorldId, runtime::Int32FromBits(pledgeId));
        if (!pledge) {
            continue;
        }
        ++pledgeNumber;
        FormatUtf16To(message.data(), message.size(), u"%d. %s", pledgeNumber, pledge->GetPledgeName());
        socket->SendSystemMessage(u"SYS", message.data());
    }

    FormatUtf16To(message.data(), message.size(), u"User List:");
    socket->SendSystemMessage(u"SYS", message.data());
    int userNumber = 0;
    for (const std::uint32_t userId : userList) {
        CSPointer<User> member =
            g_UserDBIDMap.FindObject(std::CDualKey<int, int>(g_nWorldId, runtime::Int32FromBits(userId)));
        if (!member) {
            continue;
        }
        ++userNumber;
        FormatUtf16To(message.data(), message.size(), u"%d. %s", userNumber, member->GetName());
        socket->SendSystemMessage(u"SYS", message.data());
    }

    FormatUtf16To(message.data(), message.size(), u"Dominion Registry End!");
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

