bool ncguard(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x005098b8.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return true;
    }

    std::uint32_t builderDbId = 0;
    std::uint32_t builderAccountId = 0;
    std::array<char16_t, 28> builderName{};
    std::array<char16_t, 16> builderAccount{};
    FVector builderPosition{};
    std::optional<std::u16string> account;
    {
        L2_GUARD(*builder->m_lock);
        builderDbId = builder->GetDBID();
        builderAccountId = builder->GetAccountID();
        CopyBuilderText(builderName.data(), 0x19, builder->GetName());
        account.emplace(builder->m_sAccountName.data());
        CopyBuilderText(builderAccount.data(), 0x0f, account->c_str());
        builderPosition = builder->GetPos();
    }
    static_cast<void>(builderDbId);
    static_cast<void>(builderAccountId);
    static_cast<void>(builderName);
    static_cast<void>(builderAccount);
    static_cast<void>(builderPosition);

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//ncguard [on/off/bot_event]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0) {
        g_bInitedNCGuard = true;
        if (!g_NCGuardServerStarted) {
            const NCGuardServerResult initializeResult =
                InitializeNCGuardServerW(L".\\NCGuard\\x64\\", L".\\NCGuard\\", NCGuardSendHandler, NCGuardEventHandler);
            if (initializeResult != 0U) {
                if (initializeResult == 0x4666U) {
                    std::array<wchar_t, 260> version{};
                    NCGuardServerResult packedVersion = 0;
                    if (GetDllVersionW(L".\\NCGuard\\x64\\ncguardserver64.dll", version.data(), &packedVersion) == 0U) {
                        // Log.Add(
                        //     LOG_ERROR,
                        //     L"Unpair DLL Version, [%s]",
                        //     version.data())
                        // Previous: L2_LOG_ERROR(Log,
                        //     L"Unpair DLL Version, [%s]", version.data())
                        L2_LOG_ERROR(
                            Log,
                            u"[NCGuard] Server DLL version '%s' does not match "
                            u"the expected version.",
                            version.data()
                        );
                    }
                } else {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"Init NCGuard Module fail[%d]",
                    //     static_cast<int>(initializeResult))
                    // Previous: L2_LOG_ERROR(Log,
                    //     L"Init NCGuard Module fail[%d]",
                    //     static_cast<int>(initializeResult))
                    L2_LOG_ERROR(
                        Log,
                        u"[NCGuard] Module initialization failed with result "
                        u"%d; the module remains stopped.",
                        static_cast<int>(initializeResult)
                    );
                    socket->SendSystemMessage(u"SYS", u"ncguard init fail");
                }
                return false;
            }
            // Log.Add(
            //     LOG_ERROR,
            //     L"[NO_ERROR]Init NCGuard Module Success")
            // L2_LOG_ERROR(Log,
            //     L"[NO_ERROR]Init NCGuard Module Success")
            L2_LOG_INFO(Log, "[NCGuard] Module initialized.");
            g_NCGuardServerStarted = true;
        }

        const NCGuardServerResult startResult = StartNCGuardServer();
        if (startResult == 0U) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[NO_ERROR]Start NCGuard Module Success")
            // L2_LOG_ERROR(Log,
            //     L"[NO_ERROR]Start NCGuard Module Success")
            L2_LOG_INFO(Log, "[NCGuard] Module started.");
            socket->SendSystemMessage(u"SYS", u"ncguard on.");
        } else {
            // Log.Add(
            //     LOG_ERROR,
            //     L"Start NCGuard Module fail[%d]",
            //     static_cast<int>(startResult))
            // Previous: L2_LOG_ERROR(Log,
            //     L"Start NCGuard Module fail[%d]",
            //     static_cast<int>(startResult))
            L2_LOG_ERROR(
                Log,
                u"[NCGuard] Module start failed with result %d; the module "
                u"remains stopped.",
                static_cast<int>(startResult)
            );
            socket->SendSystemMessage(u"SYS", u"ncguard start fail");
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0) {
        g_bInitedNCGuard = false;
        if (StopNCGuardServer(0) == 0U) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[NO_ERROR]Stop NCGuard Module Success")
            // L2_LOG_ERROR(Log,
            //     L"[NO_ERROR]Stop NCGuard Module Success")
            L2_LOG_INFO(Log, "[NCGuard] Module stopped.");
        }
        socket->SendSystemMessage(u"SYS", u"ncguard off");
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"log_test") == 0) {
        socket->SendSystemMessage(u"SYS", u"ncguard log test done");
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"bot_event") == 0) {
        const NCGuardServerResult result = MakeReceivePseudoPacket(builder->GetDBID(), NormalDetectedPacket);
        std::array<char16_t, 128> message{};
        FormatUtf16To(
            message.data(), message.size(),
            u"MakeReceivePseudoPacket Result : %lu \n"
            u"(0 : Success, else : Fail)",
            static_cast<unsigned long>(result)
        );
        socket->SendSystemMessage(u"SYS", message.data());
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"patch_defender") == 0) {
        const NCGuardServerResult result = MakeReceivePseudoPacket(builder->GetDBID(), NormalPDPacket);
        std::array<char16_t, 128> message{};
        FormatUtf16To(
            message.data(), message.size(),
            u"MakeReceivePseudoPacket Result : %lu \n"
            u"(0 : Success, else : Fail)",
            static_cast<unsigned long>(result)
        );
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

