bool BuilderCmd_Premium_item(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0055a8b4.
    L2_GUARD_FUNCTION();
    if (user == nullptr || socket == nullptr || command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//premium_item [new | del | list | withdraw | get] "
            u"warehouse_id class_id amount"
        );
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"new") != 0 &&
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"del") != 0 &&
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"list") != 0 &&
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"withdraw") != 0 &&
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"get") != 0) {
        socket->SendSystemMessage(
            u"SYS",
            u"//premium_item [new | del | list | withdraw | get] "
            u"warehouse_id class_id amount"
        );
        return false;
    }

    User* target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        target = user;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"new") == 0) {
        if (tokenCount < 4) {
            socket->SendSystemMessage(u"SYS", u"//premium_item new warehouse_id class_id amount");
            return false;
        }

        std::int64_t warehouseNo = BuilderWindowsWtoi64(tokens[1].data());
        if (warehouseNo > 0) {
            warehouseNo = -warehouseNo;
        }
        const int itemClassId = WindowsWtol(tokens[2].data());
        const std::int64_t amount = BuilderWindowsWtoi64(tokens[3].data());
        CObject* const object = g_ObjectDB.GetObjectW(itemClassId, false);
        if (object == nullptr) {
            socket->SendSystemMessage(u"SYS", u"item class id is invalid");
            return false;
        }

        CItem* const item = static_cast<CItem*>(object);
        if (!CSharedItemData::IsStackable(item->m_data->m_ItemConsumeType) && amount > 1) {
            socket->SendSystemMessage(u"SYS", u"amount must be 1 with this item");
            return false;
        }
        if (item->m_const->m_period > 0) {
            socket->SendSystemMessage(u"SYS", u"item is periodic");
            return false;
        }
        if (amount < 1) {
            socket->SendSystemMessage(u"SYS", u"//premium_item new warehouse_id class_id amount");
            return false;
        }

        CPacketHelperEx<20480> packet;
        static_cast<void>(packet.Assemble("QdQ", warehouseNo, itemClassId, amount));
        const int invokingAccountId = static_cast<int>(user->GetAccountID());
        const int targetAccountId = static_cast<int>(target->GetAccountID());
        db.RequestSavePremiumItemForChar(
            targetAccountId, 0, u"", invokingAccountId, 0, u"", 1,
            packet.GetLength(), packet.GetPacket()
        );
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"del") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//premium_item del warehouse_id");
            return false;
        }

        const std::int64_t warehouseNo = BuilderWindowsWtoi64(tokens[1].data());
        L2_GUARD(target->m_PremiumItemLock);
        const auto item = target->m_mapPremiumItem.find(warehouseNo);
        if (item == target->m_mapPremiumItem.end()) {
            socket->SendSystemMessage(u"SYS", u"target user do not have the item");
            return false;
        }
        target->m_mapPremiumItem.erase(item);
        db.RequestDeletePremiumItem(warehouseNo);
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"list") == 0) {
        L2_GUARD(target->m_PremiumItemLock);
        for (const auto& entry : target->m_mapPremiumItem) {
            const CPremiumItem* const item = entry.second;
            const std::u16string buyer(item->m_sBuyerCharName.data());
            std::array<char16_t, 256> message{};
            FormatUtf16To(
                message.data(), message.size(), u"warehouseNo[%I64d] item[%d:%I64d] buyer[%s]",
                static_cast<long long>(entry.first), item->m_nItemClassId, static_cast<long long>(item->m_nItemAmount),
                buyer.c_str()
            );
            socket->SendSystemMessage(u"SYS", message.data());
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"withdraw") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//premium_item withdraw warehouse_id amount");
            return false;
        }
        target->WithdrawPremiumItem(BuilderWindowsWtoi64(tokens[1].data()), BuilderWindowsWtoi64(tokens[2].data()));
    } else {
        if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"get") == 0) {
            g_PremiumSvc.RequestGetPremiumItems();
        }
    }

    socket->SendSystemMessage(u"SYS", u"completed premium_item");
    return false;
}

bool BuilderCmd_set_birthday(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x004fc764.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//set_birthday year month day");
        return false;
    }

    CCreature* const target = user->m_spTarget.GetCreature();
    if (target == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid target.");
        return false;
    }
    if (!target->IsPC()) {
        return false;
    }

    _SYSTEMTIME birthday{};
    birthday.wYear = static_cast<std::uint16_t>(WindowsWtol(tokens[0].data()));
    birthday.wMonth = static_cast<std::uint16_t>(WindowsWtol(tokens[1].data()));
    birthday.wDay = static_cast<std::uint16_t>(WindowsWtol(tokens[2].data()));
    {
        L2_GUARD(*target->m_lock);
        std::memcpy(&target->CastUser()->m_data->m_tCreateDate, &birthday, sizeof(birthday));
    }

    // Preserve the current right-to-left conversion order at the DB call.
    const int day = WindowsWtol(tokens[2].data());
    const int month = WindowsWtol(tokens[1].data());
    const int year = WindowsWtol(tokens[0].data());
    db.SetBirthday(*target->CastUser(), year, month, day);
    return false;
}

