bool ShowTeleporterInfo(CUserSocket* const socket, User*, char16_t*) {
    // Current L2Server.exe 0x00542b8c.
    L2_GUARD_FUNCTION();
    User* const builder = socket->GetUser();
    if (builder == nullptr) {
        return false;
    }

    CCreature* const target = builder->m_spTarget.GetCreature();
    if (target == nullptr || !target->IsNPC()) {
        socket->SendSystemMessage(u"SYS", u"target is NULL or not NPC");
        return false;
    }
    CTeleporter* const teleporter = target->CastTeleporter();
    if (teleporter == nullptr || !teleporter->IsTeleporter()) {
        socket->SendSystemMessage(u"SYS", u"target is not teleporter");
        return false;
    }
    CNPC* const npc = target->CastNPC();
    if (npc == nullptr) {
        socket->SendSystemMessage(u"SYS", u"Casting Error~!");
        return false;
    }

    std::array<char16_t, 2048> message{};
    FormatUtf16To(
        message.data(), message.size(),
        u"TeleporterName[%s], param[%d, %d, %d, %d], "
        u"pTeleporter->m_teleporterFlag[%d]",
        teleporter->GetName(), teleporter->GetParam(3), teleporter->GetParam(2), teleporter->GetParam(1),
        teleporter->GetParam(0), static_cast<int>(teleporter->GetTeleporterFlag())
    );
    socket->SendSystemMessage(u"SYS", message.data());

    for (const auto& parameter : npc->m_pClassConst->m_mapParameter) {
        const std::u16string name(parameter.first.c_str());
        const std::u16string value(parameter.second.c_str());
        FormatUtf16To(message.data(), message.size(), u"ParamName[%s] ParamValue[%s]", name.c_str(), value.c_str());
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

