bool skill_enchant(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x0053786c.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 3, tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//skill_enchant [info/detail_train/detail_safe/"
            u"detail_untrain/detail_routechange/train/safe/untrain/route] "
            u"[skill_id] [skill_level] [skill_sub_lev]"
        );
        return false;
    }

    const int skillId = WindowsWtol(tokens[1].data());
    const int skillLevel = WindowsWtol(tokens[2].data());
    const int skillSubLevel = tokenCount > 3 ? WindowsWtol(tokens[3].data()) : 0;
    const std::int32_t packedLevel = runtime::Int32FromBits(
        (static_cast<std::uint32_t>(skillSubLevel) << 16U) | (static_cast<std::uint32_t>(skillLevel) & 0xffffU)
    );

    CPacketHelperEx<20480> packet{};
    int packetId = 0;
    const char16_t* packetName = nullptr;
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"info") == 0) {
        static_cast<void>(packet.Assemble("dd", skillId, packedLevel));
        packetId = 0x00e;
        packetName = u"C_EX_ENCHANT_SKILL_INFO";
    } else {
        int action = -1;
        if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"detail_train") == 0) {
            action = 0;
        } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"detail_safe") == 0) {
            action = 1;
        } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"detail_untrain") == 0) {
            action = 2;
        } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"detail_route") == 0) {
            action = 3;
        }

        if (action >= 0) {
            static_cast<void>(packet.Assemble("ddd", action, skillId, packedLevel));
            packetId = 0x043;
            packetName = u"C_EX_ENCHANT_SKILL_INFO_DETAIL";
        } else {
            if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"train") == 0) {
                action = 0;
                packetName = u"C_EX_REQ_ENCHANT_SKILL";
            } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"safe") == 0) {
                action = 1;
                packetName = u"C_EX_REQ_ENCHANT_SKILL_SAFE";
            } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"untrain") == 0) {
                action = 2;
                packetName = u"C_EX_REQ_ENCHANT_SKILL_UNTRAIN";
            } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"route") == 0) {
                action = 3;
                packetName = u"C_EX_REQ_ENCHANT_SKILL_ROUTE_CHANGE";
            } else {
                socket->SendSystemMessage(
                    u"SYS",
                    u"//skill_enchant [info/detail_train/detail_safe/"
                    u"detail_untrain/detail_routechange/train/safe/untrain/route] "
                    u"[skill_id] [skill_level]"
                );
                return false;
            }
            static_cast<void>(packet.Assemble("ddd", action, skillId, packedLevel));
            packetId = 0x00f;
        }
    }

    socket->SendSystemMessage(u"SYS", packetName);
    return g_UserPacketEx.GetCallback(packetId)(
        static_cast<CSocket*>(socket), reinterpret_cast<const std::uint8_t*>(packet.GetPacket())
    );
}

