bool use_skill_infecting(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00514ecc.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//use_skill_infecting skill_id skill_level "
            u"skill_sub_level duration"
        );
        return false;
    }

    const int skillId = WindowsWtol(tokens[0].data());
    const int skillLevel = WindowsWtol(tokens[1].data());
    const int skillSubLevel = WindowsWtol(tokens[2].data());
    const int duration = WindowsWtol(tokens[3].data());
    const CSkillInfo* const skill = g_SkillDB.GetSkillInfo(CSkillKey(skillId, skillLevel, skillSubLevel), user);
    std::array<char16_t, 1024> message{};
    if (skill == nullptr) {
        FormatUtf16To(
            message.data(), message.size(), u"Invalid Skill ID (id:%d-level:%d-sub_level:%d)", skillId, skillLevel,
            skillSubLevel
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    if (skill->m_OperateType != SKILL_DURATION && skill->m_OperateType != SKILL_CHARGE_DURATION &&
        skill->m_OperateType != SKILL_SELFDURATION) {
        FormatUtf16To(
            message.data(), message.size(), u"It's not a infecting skill (id:%d-level:%d-sub_level:%d)", skillId, skillLevel,
            skillSubLevel
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    const int abnormalTime = user->GetAbnormalTime(skill, false);
    if (abnormalTime < duration) {
        FormatUtf16To(
            message.data(), message.size(), u"duration exceedes abnormal time (input:%d max:%d)", duration,
            skill->m_nAbnormalTime
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    const int now = runtime::crt::Time32Now();
    const int secondAbnormalTime = user->GetAbnormalTime(skill, false);
    CCreature* const target = user->m_spTarget.GetCreature();
    if (target != nullptr) {
        static_cast<void>(target->InfectedSkillBy(
            nullptr, skill, nullptr,
            runtime::SubtractInt32Wrapping(runtime::AddInt32Wrapping(now, duration), secondAbnormalTime)
        ));
    }

    const std::int32_t packedLevel = runtime::Int32FromBits(
        (static_cast<std::uint32_t>(skillSubLevel) << 16U) | (static_cast<std::uint32_t>(skillLevel) & 0xffffU)
    );
    CLogFormatter formatter;
    formatter.WriteLog2(0x220, user, target, skillId, packedLevel, 0, 0, 0, 0, 0);
    return false;
}

