CParty* _make_party(User* const user, const int requestedCount) {
    // Current L2Server.exe helper reached from 0x005148e0.
    L2_GUARD_FUNCTION();
    user->m_bPartyBuilder = true;
    user->ProcessMyParty(false);
    CParty* const party = CParty::TestCreateParty(user, user, IRT_PICKER_FIRST);
    if (party == nullptr) {
        return nullptr;
    }

    const int count = requestedCount > 7 ? 7 : requestedCount;
    const std::uint32_t additionalBits = static_cast<std::uint32_t>(count) - 2U;
    if (runtime::Int32FromBits(additionalBits) > 0) {
        std::uint64_t remaining = additionalBits;
        do {
            static_cast<void>(party->AddMember(user));
            user->SetParty(party, nullptr);
            party->OpenAllWindowPacket(user);
            party->SendAllSpelledInfoChanged();
            --remaining;
        } while (remaining != 0);
    }
    return party;
}

