bool _force_invite_party(CUserSocket* const socket, User* const builder, User* const target) {
    // Current L2Server.exe helper reached from 0x00562cb0.
    L2_GUARD_FUNCTION();
    if (!builder->m_data->m_bCanJoinParty || !target->m_data->m_bCanJoinParty) {
        socket->Send("cdd", 0x3a, 0, 0);
        return false;
    }
    if (!builder->IsPartyJoinable() || !target->IsPartyJoinable()) {
        return false;
    }
    if (builder->m_nId == target->m_nId) {
        socket->Send("cdd", 0x3a, 0, 0);
        socket->SendSystemMessage(SystemMessageId::INVALID_PARTY_INVITATION_TARGET);
        return false;
    }
    if (target->GetParty() != nullptr) {
        socket->Send("cdd", 0x3a, 0, 0);
        socket->SendSystemMessage_Char(SystemMessageId::CANNOT_INVITE_CHARACTER_ALREADY_IN_PARTY, target->GetName());
        return false;
    }

    CParty* party = builder->GetParty();
    if (party == nullptr) {
        CSPointer<User> targetReference(target, ObjectRefType::FunctionChain);
        static_cast<void>(CPartyMatchingRequest::inst().DismissRoomOnly(targetReference));
        party = new CParty(builder->m_ItemRoutingType);
        builder->SetParty(party, nullptr);
        party->SetMaster(builder);
        static_cast<void>(party->AddMember(builder));
        static_cast<void>(party->AddMember(target));
        target->SetParty(party, nullptr);
        g_PartyMap.Insert(runtime::Int32FromBits(party->m_nId), party, "BuilderCmdHandler.cpp", 0x6fff);
        party->OpenAllWindowPacket(builder);
        builder->m_bSpelledInfoChanged = true;
        builder->m_NeedUpdatePacketBits |= 4U;
        // Current keeps the creation reference here.
    } else {
        if (party->IsLootingTypeModifyInProgress()) {
            socket->SendSystemMessage(SystemMessageId::CANNOT_MAKE_ONE_TO_ONE_REQUEST_DURING_PARTY_LOOT_CHANGE);
            socket->Send("cdd", 0x3a, 0, 0);
            return false;
        }
        if (party->m_data->m_OnlineMaster.id != builder->m_nId) {
            socket->Send("cdd", 0x3a, 0, 0);
            socket->SendSystemMessage(SystemMessageId::ONLY_PARTY_LEADER_CAN_INVITE);
            return false;
        }
        if (party->GetMemberCount() > 6) {
            socket->Send("cdd", 0x3a, 0, 0);
            socket->SendSystemMessage(SystemMessageId::PARTY_FULL);
            return false;
        }

        CMultiPartyCommandChannel* const channel = party->GetMPCC();
        if (channel != nullptr && channel->m_isTeleporting) {
            socket->SendSystemMessage(SystemMessageId::CANNOT_JOIN_PARTY_WHILE_COMMAND_CHANNEL_TELEPORTING);
            return false;
        }

        CSPointer<User> targetReference(target, ObjectRefType::FunctionChain);
        static_cast<void>(CPartyMatchingRequest::inst().DismissRoomOnly(targetReference));
        static_cast<void>(party->AddMember(target));
        target->SetParty(party, nullptr);
        party->AddWindowPacket(target);
        if (channel != nullptr) {
            target->m_data->m_nMPCCId = channel->m_nId;
            CSPointer<User> dismissReference(target, ObjectRefType::FunctionChain);
            static_cast<void>(CPartyMatchingRequest::inst().DismissMPCCRoomOnly(dismissReference));
            CSPointer<User> withdrawReference(target, ObjectRefType::FunctionChain);
            static_cast<void>(CPartyMatchingRequest::inst().WithdrawMPCCRoom(withdrawReference));
        }
    }

    party->OpenAllWindowPacket(target);
    target->m_bSpelledInfoChanged = true;
    target->m_NeedUpdatePacketBits |= 4U;
    target->GatherSpelledInfoChanged();
    CMultiPartyCommandChannelManager manager;
    CSPointer<User> targetReference(target, ObjectRefType::FunctionChain);
    manager.OnJoinParty(targetReference);

    const std::u16string memberNames = party->GetAllMemberName();
    const std::u16string hostMemberNames = Utf16Text(memberNames.c_str()).String();
    CLogFormatter formatter;
    formatter.WriteLog1_1(
        0x331, builder, target, hostMemberNames.data(), nullptr, nullptr, builder->m_data->m_Race, builder->m_data->m_Sex,
        builder->m_data->m_nClass, builder->m_data->m_nLevel, 0, party->GetRoutingType(), 0
    );
    socket->Send("cdd", 0x3a, 1, builder->m_ItemRoutingType);
    target->GetSocket()->Send("cdd", 0x3a, 2, builder->m_ItemRoutingType);
    return false;
}

bool force_invite_party(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00562cb0.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    static_cast<void>(ParseBuilderTextTokenList(command, 0, tokens, tokenCount));

    CSPointer<User> targetReference;
    if (tokenCount == 0) {
        User* const socketUser = socket->GetUser();
        if (socketUser == nullptr) {
            return false;
        }
        User* const target = socketUser->m_spTarget.GetUser();
        if (target == nullptr) {
            socket->SendSystemMessage(u"SYS", u"Select a target first.");
            return false;
        }
        targetReference.SetObject(target, ObjectRefType::FunctionChain);
    } else {
        targetReference = GetUserFromNameMap(g_nWorldId, std::u16string(tokens[0].data()));
        if (!targetReference) {
            socket->SendSystemMessage(u"SYS", u"the user is not in l2 world");
            return false;
        }
    }

    static_cast<void>(_force_invite_party(socket, user, targetReference.get()));
    return false;
}

bool _force_invite_room(CUserSocket*, User* const builder, User* const target) {
    // Current L2Server.exe helper reached from 0x0056fe30.
    L2_GUARD_FUNCTION();
    if (builder == nullptr) {
        target->SendSystemMessage(SystemMessageId::COMMAND_CHANNEL_INVITATION_USER_NOT_FOUND);
        CReplyChecker::FinishWaitingReplyByReplier(target);
        return false;
    }

    static_cast<void>(CCursedWeaponMgr::inst());
    if (target != nullptr && target->m_nCursedWeaponClassId > 0) {
        return false;
    }
    static_cast<void>(CCursedWeaponMgr::inst());
    if (builder->m_nCursedWeaponClassId > 0) {
        return false;
    }

    CMultiPartyCommandChannelManager manager;
    CParty* const party = builder->GetParty();
    if (!CMultiPartyCommandChannelRegistry::IsChannelOwner(party)) {
        CSPointer<User> openReference(builder, ObjectRefType::FunctionChain);
        manager.Open(openReference, MCT_ITEM);
    }
    CSPointer<User> builderReference(builder, ObjectRefType::FunctionChain);
    CSPointer<User> targetReference(target, ObjectRefType::FunctionChain);
    manager.Join(builderReference, targetReference);
    CSPointer<User> matchingReference(target, ObjectRefType::FunctionChain);
    static_cast<void>(CPartyMatchingRequest::inst().OnJoinMPCC(matchingReference));
    CReplyChecker::FinishWaitingReplyByReplier(target);
    return false;
}

