bool _user_in(User* const user, const int type, char16_t* const name) {
    // Current L2Server.exe helper reached from 0x005405ec.
    L2_GUARD_FUNCTION();
    static_cast<void>(type);
    std::u16string targetName = std::u16string(name);
    CTerritory* const territory = g_NpcPosDB.GetNpcPos(targetName.data());
    if (territory == nullptr) {
        user->GetSocket()->SendSystemMessage(u"SYS", u"invalid territory name");
        return false;
    }

    class TLMFunc final : public CTLMFunc {
    public:
        TLMFunc(User* const user, char16_t* const name) : m_user(user), m_name(name) {}

        bool CanDo(CObject* const object, double) override {
            if (!object->IsPC() || (!object->IsDeleting() && object->m_Deleted == 0)) {
                User* const found = object->CastUser();
                if (found->IsBuilder()) {
                    ++m_gmCount;
                } else {
                    ++m_userCount;
                }
            }
            return true;
        }

        void Finish() override {
            std::array<char16_t, 1024> message{};
            FormatUtf16To(message.data(), message.size(), u"user [%d], gm [%d] in %s", m_userCount, m_gmCount, m_name);
            m_user->GetSocket()->SendSystemMessage(u"SYS", message.data());
        }

    private:
        int m_userCount = 0;
        int m_gmCount = 0;
        User* m_user;
        char16_t* m_name;
    };

    CTLMFilterTerritory filter(static_cast<int>(user->GetInZoneID()), territory);
    TLMFunc function(user, name);
    FOR_ALL_NEIGHBOR_USER_IN_TERRITORY(&filter, &function);
    return false;
}

