bool _obj_in_area(User* const user, const int type, char16_t* const name) {
    // Current L2Server.exe helper reached from 0x00566884/0x00566a4c.
    L2_GUARD_FUNCTION();
    CTerritory* const territory = GetTerritory(user, type, name);
    if (territory == nullptr) {
        return false;
    }

    class CCreatureInTerritory final : public CTLMFunc {
    public:
        explicit CCreatureInTerritory(std::map<int, int>& counts) : m_counts(counts) {}

        bool CanDo(CObject* const object, double) override {
            const int key = object->IsNPC() ? object->CastNPC()->m_nClassId : -1;
            ++m_counts[key];
            return true;
        }

    private:
        std::map<int, int>& m_counts;
    };

    std::map<int, int> counts;
    CTLMFuncInTerritory filter(static_cast<int>(user->GetInZoneID()), territory);
    CCreatureInTerritory function(counts);
    FOR_ALL_NEIGHBOR_CREATURE_DIST(&filter, &function);

    std::wostringstream stream;
    int totalNpc = 0;
    for (const auto& entry : counts) {
        if (entry.first == -1) {
            stream << L"Not npc : " << entry.second << std::endl;
        } else {
            stream << L"Npc : " << Utf16ToWide(g_ObjectDB.GetName(entry.first)) << L" : " << entry.second << std::endl;
            totalNpc += entry.second;
        }
    }
    stream << "TotalNpc : " << totalNpc << std::endl;
    // The list is built with a native wide stream.
    user->GetSocket()->SendSystemMessage(u"SYS", WideToUtf16(stream.str()));
    return false;
}

