bool npc_menu(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x005158cc.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 4> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//npc_menu ask replay state count");
        return false;
    }

    const int ask = WindowsWtol(tokens[0].data());
    const std::int64_t replay = BuilderWindowsWtoi64(tokens[1].data());
    const int state = WindowsWtol(tokens[2].data());
    const int count = WindowsWtol(tokens[3].data());
    if (count >= 101) {
        user->SendSystemMessage(u"SYS", u"count must be lower than 100");
        return false;
    }

    CNPC* const npc = user->m_spTarget.GetNPC();
    if (npc == nullptr || count <= 0) {
        return false;
    }

    int remaining = count;
    do {
        QuestNpcEventController* const controller = npc->GetEventController(QUEST_NPC_EVENT_MENU_SELECTED, false);
        if (controller != nullptr) {
            static_cast<void>(controller->Do(*user, npc, static_cast<std::int64_t>(ask), replay));
        }
        g_npcserver.Send(
            "cddddQd", 0x0c, user->m_data->index, static_cast<int>(user->m_nId), npc->m_data->index, ask, replay, state
        );
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
        --remaining;
    } while (remaining != 0);
    return false;
}

bool sector_show(CUserSocket* const socket, User* const user, char16_t*) {
    // Current L2Server.exe 0x00515bb8.
    L2_GUARD_FUNCTION();
    const FVector position = user->GetPos();
    const std::int32_t x = runtime::Win64CvttDoubleToInt32(position.x);
    const std::int32_t y = runtime::Win64CvttDoubleToInt32(position.y);
    const std::int32_t zoneX = (runtime::AddInt32Wrapping(x, 0x50000) >> 15) + 10;
    const std::int32_t zoneY = (runtime::AddInt32Wrapping(y, 0x40000) >> 15) + 10;
    CGeoZone* const zone = CWorld::Inst().GetGeo()->GetZone(zoneX, zoneY);
    CGeoSector* const sector = zone != nullptr ? zone->GetSector((x >> 7) & 0xff, (y >> 7) & 0xff) : nullptr;

    std::array<char16_t, 1024> message;
    if (sector == nullptr) {
        socket->SendSystemMessage(u"SYS", u"no sector");
    } else {
        const std::uint16_t field = static_cast<std::uint16_t>(sector->m_Field);
        FormatUtf16To(
            message.data(), 0x3ff,
            u"(BR %d, BP %d, F %d), (P %d, W %d, SC %d), "
            u"(I %d, S %d, NR %d), (SH %d)",
            (field & GeoFieldMask[GEO_FIELD_BATTLE_RESIDENCE]) == GeoFieldMask[GEO_FIELD_BATTLE_RESIDENCE],
            (field & GeoFieldMask[GEO_FIELD_BATTLE_PVP]) == GeoFieldMask[GEO_FIELD_BATTLE_PVP],
            (field & GeoFieldMask[GEO_FIELD_FREEZE]) == GeoFieldMask[GEO_FIELD_FREEZE],
            (field & GeoFieldMask[GEO_FIELD_PEACE]) == GeoFieldMask[GEO_FIELD_PEACE],
            (field & GeoFieldMask[GEO_FIELD_WATER]) == GeoFieldMask[GEO_FIELD_WATER],
            (field & GeoFieldMask[GEO_FIELD_STATUS_CHANGE]) == GeoFieldMask[GEO_FIELD_STATUS_CHANGE],
            (field & GeoFieldMask[GEO_FIELD_INSTANT]) == GeoFieldMask[GEO_FIELD_INSTANT],
            (field & GeoFieldMask[GEO_FIELD_SSQ]) == GeoFieldMask[GEO_FIELD_SSQ],
            (field & GeoFieldMask[GEO_FIELD_NO_RESTART]) == GeoFieldMask[GEO_FIELD_NO_RESTART],
            (field & GeoFieldMask[GEO_FIELD_SHUTTLE]) == GeoFieldMask[GEO_FIELD_SHUTTLE]
        );
    }
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

bool write_post(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00515e60.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 8> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//write_post receiver trade title content itemid1 "
            u"itemid2 itemid3 trade_money"
        );
        return false;
    }

    const int trade = WindowsWtol(tokens[1].data());
    std::array<int, 3> itemClassIds{
        WindowsWtol(tokens[4].data()),
        WindowsWtol(tokens[5].data()),
        WindowsWtol(tokens[6].data()),
    };
    const std::int64_t tradeMoney = BuilderWindowsWtoi64(tokens[7].data());
    std::array<CPost::ItemPair, 8> items;
    std::array<ItemConsumeType, 8> consumeTypes;
    std::array<char, 1024> itemPacket;
    int itemPacketSize = 0;
    int foundCount = 0;
    std::int64_t fee = 100;

    if (trade != 0) {
        for (std::size_t index = 0; index < itemClassIds.size(); ++index) {
            CItem* const item = user->m_inv.GetFirstItemByClassID(itemClassIds[index], false, false);
            if (item == nullptr) {
                continue;
            }

            items[index].db_id = item->GetDBID();
            items[index].amount = item->m_data->m_nCount;
            consumeTypes[index] = item->m_data->m_ItemConsumeType;
            itemPacketSize += ::Assemble(
                itemPacket.data() + itemPacketSize, static_cast<int>(itemPacket.size()) - itemPacketSize, "dQd",
                item->GetDBID(), item->m_data->m_nCount, static_cast<int>(item->m_data->m_ItemConsumeType)
            );
            fee += 1000;
            ++foundCount;
        }
    }

    if (PostUtil::CheckWritePost(socket, user, foundCount, items.data(), tradeMoney, fee, consumeTypes.data()) &&
        user->m_pPostInfo->TryWrite()) {
        db.RequestWritePost(
            *user, tokens[0].data(), trade, tokens[2].data(), tokens[3].data(), foundCount, itemPacketSize,
            itemPacket.data(), tradeMoney, trade != 0, fee
        );
    }
    return false;
}

