bool show_skill_info(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x005183ec.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//show_skill_info on/off");
        return false;
    }

    const char16_t* message = nullptr;
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"켬") == 0) {
        if (!user->m_ShowSkillInfo) {
            user->m_ShowSkillInfo = true;
            message = u"Now, you can see Skill Info";
        } else {
            message = u"Currently, you can see Skill Info";
        }
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"끔") == 0) {
        if (!user->m_ShowSkillInfo) {
            message = u"Currently, you can't see Skill Info";
        } else {
            user->m_ShowSkillInfo = false;
            message = u"Now, you can't see Skill Info";
        }
    } else {
        message = u"show_skill_info on/off";
    }

    socket->SendSystemMessage(u"SYS", message);
    return false;
}

