bool show_pet_item(CUserSocket* const socket, User* const user, char16_t*) {
    // Current L2Server.exe 0x00542e6c.
    L2_GUARD_FUNCTION();
    std::array<char16_t, 1024> message{};
    {
        L2_WRITE_GUARD(user->m_inv);
        CSharedItemData* itemData = user->m_inv.GetFirst();
        while (itemData != nullptr) {
            CSharedItemData* const next = itemData->Next();
            CSPointer<CItem> item = CItemFactory::Inst().FindObjectSP(itemData->index);
            if (item && item->IsPetCollarItem()) {
                FormatUtf16To(
                    message.data(), message.size(), u"Pet Item [%d][%d]", item->m_data->m_nClassID, item->m_data->m_nDBID
                );
                socket->SendSystemMessage(u"SYS", message.data());
            }
            itemData = next;
        }
    }
    return false;
}

