bool UndergroundColosseum(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00516fb8.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//uc match_type command ...");
        return false;
    }

    const int matchType = WindowsWtol(tokens[0].data());
    User* const target = user->m_spTarget.GetUser();
    const char16_t* const action = tokens[1].data();
    if (CompareBuilderTextIgnoreCase(action, u"reg") == 0) {
        if (target == nullptr) {
            socket->SendSystemMessage(u"SYS", u"Choose target first.");
        } else {
            CEventMatchHelper::RegisterParty(matchType, *target, *user);
        }
    } else if (CompareBuilderTextIgnoreCase(action, u"unreg") == 0) {
        if (target == nullptr) {
            socket->SendSystemMessage(u"SYS", u"Choose target first.");
        } else {
            CEventMatchHelper::UnregisterParty(matchType, *target, *user);
        }
    } else if (CompareBuilderTextIgnoreCase(action, u"start") == 0) {
        CEventMatchHelper::StartMatch(matchType, *user);
    } else if (CompareBuilderTextIgnoreCase(action, u"observe_start") == 0) {
        CEventMatchHelper::StartObserve(matchType, *user);
    } else if (CompareBuilderTextIgnoreCase(action, u"observe_end") == 0) {
        CEventMatchHelper::EndObserve(matchType, *user);
    } else if (CompareBuilderTextIgnoreCase(action, u"reset") == 0) {
        CEventMatchHelper::UnregisterAll(matchType, *user);
    } else {
        socket->SendSystemMessage(u"SYS", u"//uc match_type command ...");
    }
    return false;
}

