bool set_item_period(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x00518b1c.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    {
        L2_GUARD(*user->m_lock);
        std::array<char16_t, 25> characterName{};
        std::array<char16_t, 15> accountName{};
        static_cast<void>(user->GetDBID());
        static_cast<void>(user->GetAccountID());
        CopyBuilderText(characterName.data(), characterName.size(), user->GetName());
        const std::u16string accountNameText(user->m_sAccountName.data());
        CopyBuilderText(accountName.data(), accountName.size(), accountNameText.c_str());
        const FVector position = user->GetPos();
        static_cast<void>(position);
    }

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//set_item_period (item_class_id or item_name) period");
        return false;
    }

    int itemClassId = WindowsWtol(tokens[0].data());
    if (itemClassId == 0) {
        const std::u16string itemName = std::u16string(tokens[0].data());
        itemClassId = g_ObjectDB.GetClassIdFromName(itemName.c_str(), false);
    }
    if (itemClassId < 1) {
        socket->SendSystemMessage(u"SYS", u"error : invalid item name");
        return false;
    }

    const int period = WindowsWtol(tokens[1].data());
    CItem* const item = user->m_inv.GetFirstItemByClassID(itemClassId, false, false);
    if (item == nullptr) {
        socket->SendSystemMessage(u"SYS", u"error : not existed item.");
        return false;
    }
    if (item->m_const->m_period < 1 || user->GetPeriodLeft(*item) < 0) {
        socket->SendSystemMessage(u"SYS", u"error : not periodic item or expired item.");
        return false;
    }

    if (!user->SetItemPeriod(*item, period)) {
        socket->SendSystemMessage(u"SYS", u"setting item period is failed.");
        return false;
    }
    user->SendPeriodicItemList();
    socket->SendSystemMessage(u"SYS", u"setting item period is accepted.");
    return false;
}

bool follow(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x00539de4.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    {
        L2_GUARD(*user->m_lock);
        std::array<char16_t, 25> characterName{};
        std::array<char16_t, 15> accountName{};
        static_cast<void>(user->GetDBID());
        static_cast<void>(user->GetAccountID());
        CopyBuilderText(characterName.data(), characterName.size(), user->GetName());
        const std::u16string accountNameText(user->m_sAccountName.data());
        CopyBuilderText(accountName.data(), accountName.size(), accountNameText.c_str());
        const FVector position = user->GetPos();
        static_cast<void>(position);
    }

    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//follow type data1 data2");
        return false;
    }

    const int type = WindowsWtol(tokens[0].data());
    const int first = WindowsWtol(tokens[1].data());
    const int second = WindowsWtol(tokens[2].data());
    CNPC* const target = user->m_spTarget.GetNPC();
    if (target == nullptr) {
        socket->SendSystemMessage(u"SYS", u"target should be NPC");
        return false;
    }

    if (type < 1) {
        target->m_FollowData.Init();
        target->DoNothing();
    } else if (type < 4) {
        target->OnNpcFollow(runtime::Int32FromBits(user->m_nId), static_cast<char>(type), first, second);
    } else if (type < 5) {
        CCreature* const previousTarget =
            g_CreatureSmartIdManager.GetObjectW(static_cast<std::uint32_t>(user->m_nOldTargetId));
        if (previousTarget != nullptr && previousTarget != target) {
            target->OnNpcFollow(runtime::Int32FromBits(user->m_nId), static_cast<char>(type - 2), first, second);
        } else {
            socket->SendSystemMessage(u"SYS", u"old target should be other NPC");
        }
    }
    return false;
}

