bool drop_item_ic(CUserSocket* const socket, User* const user, char16_t*) {
    // Current L2Server.exe 0x005197d8.
    L2_GUARD_FUNCTION();
    CNPC* const target = user->m_spTarget.GetNPC();
    if (target == nullptr || !target->IsNPC()) {
        socket->SendSystemMessage(u"SYS", u"target char first");
        return false;
    }

    target->AccumulateContribute(user, 1.0);
    std::array<char16_t, 256> itemChanceText{};
    std::array<char16_t, 256> itemText{};
    std::array<char16_t, 5000> list{};
    std::array<char16_t, 5000> message{};

    const auto effectiveChance = [](const double base, const double probability) noexcept {
        double result = base * probability;
        if (result > 100.0) {
            result = 100.0;
        } else if (!(result >= 0.0)) {
            result = 0.0;
        }
        return result;
    };
    const auto appendItem = [&](const ItemDropStruct& item, const double probability) {
        FormatUtf16To(
            itemText.data(), itemText.size(), u"{[%d];%d;%d;%f}", item.ItemClassId,
            runtime::Int32FromBits(static_cast<std::uint32_t>(item.DropMin)),
            runtime::Int32FromBits(static_cast<std::uint32_t>(item.DropMax)), probability
        );
        AppendBuilderText(list.data(), list.size(), std::u16string(itemText.data()).c_str());
        AppendBuilderText(list.data(), list.size(), u", ");
    };

    socket->SendSystemMessage(u"SYS", u"Multi DropList By ItemChance: ");
    const double multiChance = target->GetDropItemChanceProb(DROPITEM_MULTI);
    FormatUtf16To(itemChanceText.data(), itemChanceText.size(), u"ItemChance : %f", multiChance);
    socket->SendSystemMessage(u"SYS", itemChanceText.data());
    for (const ItemDropMultiStruct& group : target->m_pClassConst->m_ItemAdditionalMakeListMulti) {
        message.fill(L'\0');
        list.fill(L'\0');
        CopyBuilderText(list.data(), list.size(), u"{ ");
        for (const ItemDropStruct* const item : *group.pItemDropList) {
            appendItem(*item, item->DropProb);
        }
        AppendBuilderText(list.data(), list.size(), u" }");
        FormatUtf16To(
            message.data(), message.size(), u"prob : %f ( %s )", effectiveChance(multiChance, group.DropProb), list.data()
        );
        socket->SendSystemMessage(u"SYS", message.data());
    }

    message.fill(L'\0');
    list.fill(L'\0');
    socket->SendSystemMessage(u"SYS", u"Ex DropList By ItemChance");
    const double exChance = target->GetDropItemChanceProb(DROPITEM_EX);
    itemChanceText.fill(L'\0');
    FormatUtf16To(itemChanceText.data(), itemChanceText.size(), u"ItemChance : %f", exChance);
    socket->SendSystemMessage(u"SYS", itemChanceText.data());
    for (const ItemDropMultiStruct& group : target->m_pClassConst->m_ExItemDropListMulti) {
        message.fill(L'\0');
        list.fill(L'\0');
        CopyBuilderText(list.data(), list.size(), u"{ ");
        for (const ItemDropStruct* const item : *group.pItemDropList) {
            appendItem(*item, item->DropProb);
        }
        AppendBuilderText(list.data(), list.size(), u" }");
        FormatUtf16To(
            message.data(), message.size(), u"prob : %f ( %s )", effectiveChance(exChance, group.DropProb), list.data()
        );
        socket->SendSystemMessage(u"SYS", message.data());
    }

    message.fill(L'\0');
    list.fill(L'\0');
    socket->SendSystemMessage(u"SYS", u"SpoilList By ItemChance : ");
    const double spoilChance = target->GetPrivateDropCorpseItemChanceProb(user);
    itemChanceText.fill(L'\0');
    FormatUtf16To(itemChanceText.data(), itemChanceText.size(), u"ItemChance : %f", spoilChance);
    socket->SendSystemMessage(u"SYS", itemChanceText.data());
    CopyBuilderText(list.data(), list.size(), u"{ ");
    for (const ItemDropStruct& item : target->m_pClassConst->m_CorpseMakeList) {
        appendItem(item, effectiveChance(spoilChance, item.DropProb));
    }
    AppendBuilderText(list.data(), list.size(), u" }");
    FormatUtf16To(message.data(), message.size(), u"( %s )", list.data());
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

bool StepExpire(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x0051a0c0.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 5> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//step_expire fieldcycleID step day hour min");
        return false;
    }

    int day = 1;
    if (CompareBuilderTextIgnoreCase(tokens[2].data(), u"mon") != 0) {
        if (CompareBuilderTextIgnoreCase(tokens[2].data(), u"tue") == 0) {
            day = 2;
        } else if (CompareBuilderTextIgnoreCase(tokens[2].data(), u"wed") == 0) {
            day = 3;
        } else if (CompareBuilderTextIgnoreCase(tokens[2].data(), u"thu") == 0) {
            day = 4;
        } else if (CompareBuilderTextIgnoreCase(tokens[2].data(), u"fri") == 0) {
            day = 5;
        } else if (CompareBuilderTextIgnoreCase(tokens[2].data(), u"sat") == 0) {
            day = 6;
        } else if (CompareBuilderTextIgnoreCase(tokens[2].data(), u"sun") == 0) {
            day = 0;
        } else {
            day = -1;
        }
    }
    g_FieldCycleSystem.TryStepExpire(
        WindowsWtol(tokens[0].data()), WindowsWtol(tokens[1].data()), day, WindowsWtol(tokens[3].data()),
        WindowsWtol(tokens[4].data())
    );
    return false;
}

