bool skill_info(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0051b048.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"skill_info skill_id skill_level skill_sub_level");
        return false;
    }

    const int skillId = WindowsWtol(tokens[0].data());
    const int skillLevel = WindowsWtol(tokens[1].data());
    const int skillSubLevel = tokenCount > 2 ? WindowsWtol(tokens[2].data()) : 0;
    const CSkillInfo* const skill = g_SkillDB.GetSkillInfo(CSkillKey(skillId, skillLevel, skillSubLevel), user);
    if (skill == nullptr) {
        socket->SendSystemMessage(u"SYS", u"No skill");
        return false;
    }

    std::uint64_t packedKey = static_cast<std::uint64_t>(static_cast<std::int64_t>(skillId));
    packedKey <<= 16;
    packedKey |= static_cast<std::uint64_t>(static_cast<std::int64_t>(skillLevel));
    packedKey <<= 16;
    packedKey |= static_cast<std::uint64_t>(static_cast<std::int64_t>(skillSubLevel));

    std::array<char16_t, 1020> message{};
    FormatUtf16To(
        message.data(), message.size(), u"skill [%s] exist. [%I64d]", skill->m_pszName,
        static_cast<long long>(runtime::Int64FromBits(packedKey))
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

