bool ResetProfile(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x004fce10.
    L2_GUARD_FUNCTION();
    ProfileHelp help{socket};
    ResetProfiler profiler{&help};

    char16_t* token = nullptr;
    if (command != nullptr) {
        token = TakeBuilderTextToken(command);
    }
    if (token == nullptr) {
        if (socket != nullptr) {
            socket->SendSystemMessage(u"SYS", u"//resetprofile (cached | l2server | l2npc)");
        }
        return false;
    }

    profiler.Reset(token);
    if (socket != nullptr) {
        socket->SendSystemMessage(u"SYS", u"[Profile] This binary is not profile version.");
    }
    return false;
}

