bool SetProductDayOfWeek(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00535cac.
    L2_GUARD_FUNCTION();
    constexpr const char16_t* usage = u"//set_product_dayofweek [productid] [sun/mon/tue/wed/thu/fri/sat/all] [on/off]";
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", usage);
        return false;
    }

    const int productId = WindowsWtol(tokens[0].data());
    std::array<char16_t, 8> day{};
    CopyBuilderText(day.data(), day.size(), tokens[1].data());
    const int value = WindowsWtol(tokens[2].data());
    CProductSP product = g_ShopServer.GetProduct(productId);
    if (!product) {
        user->SendSystemMessage(u"SYS", usage);
        return false;
    }

    const std::uint8_t dayBits = static_cast<std::uint8_t>(product->m_dayOfWeek);
    std::array<int, 7> days{static_cast<int>((dayBits >> 0) & 1U), static_cast<int>((dayBits >> 1) & 1U),
        static_cast<int>((dayBits >> 2) & 1U), static_cast<int>((dayBits >> 3) & 1U), static_cast<int>((dayBits >> 4) & 1U),
        static_cast<int>((dayBits >> 5) & 1U), static_cast<int>((dayBits >> 6) & 1U)};

    int dayIndex = -1;
    constexpr std::array<const char16_t*, 7> names{u"sun", u"mon", u"tue", u"wed", u"thu", u"fri", u"sat"};
    for (std::size_t index = 0; index < names.size(); ++index) {
        if (CompareBuilderTextIgnoreCase(day.data(), names[index]) == 0) {
            dayIndex = static_cast<int>(index);
            break;
        }
    }
    if (dayIndex >= 0) {
        days[static_cast<std::size_t>(dayIndex)] = value;
    } else if (CompareBuilderTextIgnoreCase(day.data(), u"all") == 0) {
        days.fill(value);
    } else {
        user->SendSystemMessage(u"SYS", usage);
        return false;
    }

    product->SetDayOfWeek(days[0], days[1], days[2], days[3], days[4], days[5], days[6]);
    const std::uint8_t finalBits = static_cast<std::uint8_t>(product->m_dayOfWeek);
    std::array<char16_t, 128> message{};
    FormatUtf16To(
        message.data(), message.size(),
        u"SetProductDayOfWeek ok, product=%d, sun=%d, mon=%d, tue=%d, wed=%d, thu=%d, fri=%d, sat=%d", productId,
        static_cast<int>((finalBits >> 0) & 1U), static_cast<int>((finalBits >> 1) & 1U),
        static_cast<int>((finalBits >> 2) & 1U), static_cast<int>((finalBits >> 3) & 1U),
        static_cast<int>((finalBits >> 4) & 1U), static_cast<int>((finalBits >> 5) & 1U),
        static_cast<int>((finalBits >> 6) & 1U)
    );
    user->SendSystemMessage(u"SYS", message.data());
    return false;
}

