bool packet_log(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0050c468.
    L2_GUARD_FUNCTION();
    constexpr const char16_t* usage = u"//packet_log command [arg1 ... argN]";
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", usage);
        return false;
    }

    const char16_t* response = nullptr;
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"test") == 0) {
        User* target = user->m_spTarget.GetUser();
        if (target == nullptr) {
            target = user;
        }
        // Log.Add(
        //     LOG_ERROR,
        //     L"[PLog] By Builder[%d:%s]",
        //     user->GetDBID(),
        //     user->GetName())
        // Log.Add(
        //     LOG_ERROR,
        //     L"[packet history] Builder character DB ID %u (%s) requested a forced report. The enable setting and interval
        //     gate are bypassed.", user->GetDBID(), user->GetName())
        // L2_LOG_ERROR(Log,
        //     L"[packet history] Builder character DB ID %u (%s) requested a forced report. The enable setting and interval
        //     gate are bypassed.", user->GetDBID(), user->GetName())
        L2_LOG_ERROR(
            Log,
            u"[packet history] Builder character DB ID %u (%s) requested a forced report; the enable setting and interval "
            u"gate are bypassed.",
            user->GetDBID(), user->GetName()
        );
        target->GetSocket()->ReportPacketLog(true);
        response = u"Complete to write error log for packet log";
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"on") == 0) {
        g_bWritePacketLog = true;
        response = u"packet log on.";
    } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"off") == 0) {
        g_bWritePacketLog = false;
        response = u"packet log off";
    } else {
        response = usage;
    }
    socket->SendSystemMessage(u"SYS", response);
    return false;
}

bool set_country(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0050d74c.
    L2_GUARD_FUNCTION();
    if (g_L2ServerType == L2ServerType::LIVE) {
        user->SendSystemMessage(u"SYS", u"set_country doesn't work in Live Server");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"use //set_country country_code");
        return false;
    }

    const unsigned int country = static_cast<unsigned int>(WindowsWtol(tokens[0].data()));
    std::array<char16_t, 512> message{};
    if (country < 14U) {
        g_nCountryCode = static_cast<int>(country);
        FormatUtf16To(message.data(), message.size(), u"set_country ok, countr = %d", country);
        user->SendSystemMessage(u"SYS", message.data());

        if (!g_PremiumSetting.cashshopPause) {
            // Log.Add(LOG_NORMAL, L"Loading Product")
            // Previous: L2_LOG_INFO(Log, L"Loading Product")
            L2_LOG_INFO(Log, u"[premium shop] Reloading product data after country change.");
            if (!g_ShopServer.Load()) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"Loading Fail in productdata.txt, set_country")
                // Previous: L2_LOG_ERROR(Log,
                //     L"Loading Fail in productdata.txt, set_country")
                L2_LOG_ERROR(
                    Log,
                    u"[premium shop] Product data reload failed after country "
                    u"change; the cash shop was paused."
                );
                g_PremiumSetting.cashshopPause = true;
                user->SendSystemMessage(u"SYS", u"Load Productdata Fail");
            } else {
                // Log.Add(
                //     LOG_NORMAL,
                //     L"Loading Ok in productdata.txt, set_country")
                // Previous: L2_LOG_INFO(Log,
                //     L"Loading Ok in productdata.txt, set_country")
                L2_LOG_INFO(
                    Log,
                    u"[premium shop] Product data reload completed after "
                    u"country change."
                );
                user->SendSystemMessage(u"SYS", u"Load Productdata Ok");
            }
        }
    } else {
        FormatUtf16To(message.data(), message.size(), u"use //set_country country_code(%d ~ %d)", 0, 13);
        user->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

bool GM_say(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0050edc8.
    L2_GUARD_FUNCTION();
    constexpr const char16_t* usage = u"//GM_say [dist] [message], (dist <= 16384)";
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", usage);
        return false;
    }

    const int requestedDistance = WindowsWtol(tokens[0].data());
    if (requestedDistance < 1) {
        socket->SendSystemMessage(u"SYS", usage);
        return false;
    }
    const int distance = requestedDistance > 0x4000 ? 0x4000 : requestedDistance;

    class TLMFunc final : public CTLMFunc {
    public:
        TLMFunc(User* const user, const char16_t* const message) : m_user(user), m_message{} {
            CopyBuilderText(m_message.data(), m_message.size(), message);
        }

        bool CanDo(CObject* const object, double) override {
            if (!object->IsPC() || (!object->IsDeleting() && object->m_Deleted == 0)) {
                object->CastUser()->GetSocket()->SendSystemMessage_S(
                    SystemMessageId::GM_SYSTEM_MESSAGE_TEXT, m_message.data()
                );
            }
            return true;
        }

    private:
        [[maybe_unused]] User* m_user;
        std::array<char16_t, 1024> m_message;
    };


    const FVector position = user->GetPos();
    const unsigned int inZoneId = user->GetInZoneID();
    CTLMFilterDist filter(static_cast<int>(inZoneId), position, static_cast<double>(distance));
    TLMFunc function(user, tokens[1].data());
    FOR_ALL_NEIGHBOR_USER_DIST(&filter, &function);
    return false;
}

