bool show_area_type(CUserSocket* const socket, User* const user, char16_t*) {
    // Current L2Server.exe 0x0051e160.
    L2_GUARD_FUNCTION();
    const FVector position = user->GetPos();
    const std::int32_t x = runtime::Win64CvttDoubleToInt32(position.x);
    const std::int32_t y = runtime::Win64CvttDoubleToInt32(position.y);
    const std::int32_t zoneX = (runtime::AddInt32Wrapping(x, 0x50000) >> 15) + 10;
    const std::int32_t zoneY = (runtime::AddInt32Wrapping(y, 0x40000) >> 15) + 10;
    CGeoZone* const zone = CWorld::Inst().GetGeo()->GetZone(zoneX, zoneY);
    CGeoSector* const sector = zone != nullptr ? zone->GetSector((x >> 7) & 0xff, (y >> 7) & 0xff) : nullptr;
    if (sector == nullptr) {
        socket->SendSystemMessage(u"SYS", u"no sector");
        return false;
    }

    const std::uint16_t field = static_cast<std::uint16_t>(sector->m_Field);
    std::array<char16_t, 1024> message{};
    FormatUtf16To(
        message.data(), 0x3ff,
        u"(BR %d, BP %d, F %d), (P %d, W %d, SC %d), "
        u"(I %d, S %d, NR %d), (SH %d)",
        (field & GeoFieldMask[GEO_FIELD_BATTLE_RESIDENCE]) == GeoFieldMask[GEO_FIELD_BATTLE_RESIDENCE],
        (field & GeoFieldMask[GEO_FIELD_BATTLE_PVP]) == GeoFieldMask[GEO_FIELD_BATTLE_PVP],
        (field & GeoFieldMask[GEO_FIELD_FREEZE]) == GeoFieldMask[GEO_FIELD_FREEZE],
        (field & GeoFieldMask[GEO_FIELD_PEACE]) == GeoFieldMask[GEO_FIELD_PEACE],
        (field & GeoFieldMask[GEO_FIELD_WATER]) == GeoFieldMask[GEO_FIELD_WATER],
        (field & GeoFieldMask[GEO_FIELD_STATUS_CHANGE]) == GeoFieldMask[GEO_FIELD_STATUS_CHANGE],
        (field & GeoFieldMask[GEO_FIELD_INSTANT]) == GeoFieldMask[GEO_FIELD_INSTANT],
        (field & GeoFieldMask[GEO_FIELD_SSQ]) == GeoFieldMask[GEO_FIELD_SSQ],
        (field & GeoFieldMask[GEO_FIELD_NO_RESTART]) == GeoFieldMask[GEO_FIELD_NO_RESTART],
        (field & GeoFieldMask[GEO_FIELD_SHUTTLE]) == GeoFieldMask[GEO_FIELD_SHUTTLE]
    );
    socket->SendSystemMessage(u"SYS", message.data());

    if ((field & GeoFieldMask[GEO_FIELD_INSTANT]) != GeoFieldMask[GEO_FIELD_INSTANT]) {
        return false;
    }

    CArea* const damage = CAreaDB::inst().FindAllArea(position, AREAT_DAMAGE);
    CArea* const poison = CAreaDB::inst().FindAllArea(position, AREAT_POISON);
    CArea* const instantSkill = CAreaDB::inst().FindAllArea(position, AREAT_INSTANT_SKILL);
    FormatUtf16To(
        message.data(), 0x3ff, u"(Damage %d, Poison %d, InstantSkill %d)", damage != nullptr, poison != nullptr,
        instantSkill != nullptr
    );
    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

bool get_rid_of(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0051e730.
    L2_GUARD_FUNCTION();
    if (user == nullptr) {
        return false;
    }
    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr || command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//get_rid_of Quest_id Npc_id Npc_Num");
        return false;
    }

    const int questId = WindowsWtol(tokens[0].data());
    const int npcId = WindowsWtol(tokens[1].data());
    const int npcCount = WindowsWtol(tokens[2].data());
    std::array<char, 0x5000> packet;
    int packetSize = 0;
    std::uint8_t logCount = 0;
    bool inserted = false;
    for (MemoStruct& memo : target->m_data->m_Memo) {
        if (memo.nQuestID != questId) {
            continue;
        }
        for (UserNPCLog& log : memo.NPCLog) {
            if (log.nNPCID == 0) {
                if (inserted) {
                    continue;
                }
                log.userLogType = USER_NPC_LOG_QUEST_HUNT;
                log.nNPCID = npcId;
                runtime::raw_atomic::ExchangeI32(&log.nCount, npcCount);
                inserted = true;
            } else if (log.nNPCID == npcId) {
                log.nCount = npcCount;
            }

            const int assembled = ::Assemble(
                packet.data() + packetSize, static_cast<int>(packet.size()) - packetSize, "dcd", log.nNPCID,
                static_cast<int>(log.userLogType), log.nCount
            );
            if (assembled > 0) {
                packetSize = runtime::AddInt32Wrapping(packetSize, assembled);
            }
            ++logCount;
        }
    }

    CUserSocket* outputSocket = socket;
    if (outputSocket == nullptr) {
        outputSocket = user->GetSocket();
    }
    outputSocket->Send("chdcb", 0xfe, 0xc6, questId, static_cast<int>(logCount), packetSize, packet.data());
    target->SaveQuestNPCLog(questId);
    return false;
}

bool quest_reset(CUserSocket* socket, User* const user, char16_t*) {
    // Current L2Server.exe 0x004dbf54.
    L2_GUARD_FUNCTION();
    if (user == nullptr) {
        return false;
    }

    std::array<char, 0x5000> packet;
    std::int32_t packetSize = 0;
    std::uint8_t count = 0;
    std::int32_t questId = 0;
    for (MemoStruct& memo : user->m_data->m_Memo) {
        for (UserNPCLog& log : memo.NPCLog) {
            if (log.nNPCID == 0) {
                continue;
            }
            runtime::raw_atomic::ExchangeI32(&log.nCount, 0);
            questId = memo.nQuestID;
            const int assembled = ::Assemble(
                packet.data() + packetSize, static_cast<int>(packet.size()) - packetSize, "dcd", log.nNPCID,
                static_cast<int>(log.userLogType), log.nCount
            );
            if (assembled > 0) {
                packetSize = runtime::AddInt32Wrapping(packetSize, assembled);
            }
            ++count;
        }
    }

    if (socket == nullptr) {
        socket = user->GetSocket();
    }
    socket->Send("chdcb", 0xfe, 0xc6, questId, static_cast<int>(count), packetSize, packet.data());
    return false;
}

bool ResetBora(CUserSocket*, User* const user, char16_t*) {
    // Current L2Server.exe 0x0056c388.
    L2_GUARD_FUNCTION();
    if (user == nullptr) {
        return false;
    }

    const auto reset = [](User* const target) {
        target->m_data->m_nPKTimeStamp = 0;
        target->SetKarma(0);
        target->SetRelationChanged(false);
        target->m_bIsInitiativeViolet = false;
    };
    reset(user);

    CCreature::SkillTargetData targets;
    user->GatherNeighborCreature(user->GetPos(), 0, 0, false, targets, 300, 0, 0, SAFOT_ALL, user, nullptr, true, false);
    for (CSafePointer2<CCreature>& reference : targets.c) {
        CSPointer<CCreature> creature = reference.FindObjectSP();
        User* const target = creature ? creature->CastUser() : nullptr;
        if (target != nullptr) {
            reset(target);
        }
    }
    return false;
}

