bool abnormalVisualEffect(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x005558cc.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//ave [add/del/clear] [number]");
        return false;
    }

    if (std::u16string_view(tokens[0].data()).compare(u"clear") == 0) {
        user->m_AbnormalVisualEffectForTest.clear();
    } else if (std::u16string_view(tokens[0].data()).compare(u"add") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//ave [add] [number]");
            return false;
        }
        const int effect = WindowsWtol(tokens[1].data());
        if (effect > 0) {
            user->m_AbnormalVisualEffectForTest.insert(effect);
        }
    } else if (std::u16string_view(tokens[0].data()).compare(u"del") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//ave [del] [number]");
            return false;
        }
        const int effect = WindowsWtol(tokens[1].data());
        if (effect > 0) {
            user->m_AbnormalVisualEffectForTest.erase(effect);
        }
    } else {
        socket->SendSystemMessage(u"SYS", u"//ave [add/del/clear] [number]");
        return false;
    }

    user->CheckAbnormalVisualEffect();
    return false;
}

