bool PledgeGame(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0051eda8.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//pg command blablabla...");
        return false;
    }

    const auto checkAccess = [socket](const int maximum, const int) {
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return -1;
        }
        int builderLevel = 0;
        {
            L2_GUARD(*builder->m_lock);
            builderLevel = builder->m_data->m_nBuilder;
        }
        return builderLevel != 0 && builderLevel <= maximum ? 1 : 0;
    };
    const auto send = [socket](const char16_t* const message) { socket->SendSystemMessage(u"SYS", message); };
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"load") == 0) {
        const int access = checkAccess(1, 0x8462);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (SharedPledgeGameInfo::GetInfo()->m_nStep == 0) {
            g_PledgeGameSystem.Init();
            send(u"[pledgegame start] command accepted");
        } else {
            send(u"season already started");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"fastmode") == 0) {
        const int access = checkAccess(1, 0x8470);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (tokenCount < 2) {
            send(u"//pg fastmode [on|off]");
        } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"on") == 0) {
            g_PledgeGameSystem.SetFastTesting(true);
            send(u"[on] fast mode on for this time only");
        } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"off") == 0) {
            g_PledgeGameSystem.SetFastTesting(true);
            send(u"[on] fast mode off");
        } else {
            send(u"//pg fastmode [on/off]");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"routine") == 0) {
        const int access = checkAccess(1, 0x8489);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (tokenCount < 2) {
            send(u"//pg routine [on/off]");
        } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"on") == 0) {
            g_PledgeGameSystem.m_bStartGameAutomatically = true;
            send(u"[on] game will start on time");
        } else if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"off") == 0) {
            g_PledgeGameSystem.m_bStartGameAutomatically = false;
            send(u"[off] game won't start on time");
        } else {
            send(u"//pg routine [on/off]");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"open") == 0) {
        const int access = checkAccess(1, 0x84a2);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (SharedPledgeGameInfo::GetInfo()->m_nStep == 1 || SharedPledgeGameInfo::GetInfo()->m_nStep == 7) {
            static_cast<void>(g_PledgeGameSystem.OpenGame());
            send(u"[pledgegame open_game] command accepted");
        } else {
            send(u"pledgegame couldn't be opened");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"join") == 0) {
        const int access = checkAccess(1, 0x84b2);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (SharedPledgeGameInfo::GetInfo()->m_nStep == 2) {
            static_cast<void>(g_PledgeGameSystem.RegisterEntry(user));
            send(u"[pledgegame participate_game] command accepted");
        } else {
            send(u"game is not opened");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"prepare") == 0) {
        const int access = checkAccess(1, 0x84c1);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (SharedPledgeGameInfo::GetInfo()->m_nStep == 2) {
            static_cast<void>(g_PledgeGameSystem.PrepareGame());
            send(u"[pledgegame prepare_game] command accepted");
        } else {
            send(u"command not accepted!!");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"leave") == 0) {
        const int access = checkAccess(1, 0x84d0);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (SharedPledgeGameInfo::GetInfo()->m_nStep >= 2 && SharedPledgeGameInfo::GetInfo()->m_nStep <= 7) {
            static_cast<void>(g_PledgeGameSystem.LeaveGame(user, false));
            send(u"[pledgegame leave_game] command accepted");
        } else {
            send(u"command not accepted!!");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"matchpoint") == 0) {
        const int access = checkAccess(2, 0x84df);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        g_PledgeGameSystem.m_nDebugUserSID = user->GetServerId();
        send(u"[pledgegame matchgame] command accepted");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"observe") == 0) {
        const int access = checkAccess(1, 0x8504);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (SharedPledgeGameInfo::GetInfo()->m_nStep != 4 && SharedPledgeGameInfo::GetInfo()->m_nStep != 5) {
            return false;
        }
        if (tokenCount < 2) {
            send(u"//pg observe field_id");
            return false;
        }
        const int fieldId = WindowsWtol(tokens[1].data());
        if (static_cast<std::uint32_t>(fieldId) - 1U < 5U || fieldId == 6) {
            static_cast<void>(g_PledgeGameSystem.RegisterObserverEntry(user, fieldId - 1));
            return false;
        }
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] invalid field id(%d)",
        //     L"BuilderCmdHandler.cpp",
        //     0x8513,
        //     fieldId)
        // Previous: L2_LOG_ERROR(Log,
        //     L"[%s][%d] invalid field id(%d)",
        //     L"BuilderCmdHandler.cpp", 0x8513, fieldId)
        L2_LOG_ERROR(
            Log,
            u"[builder pledge game] Field ID %d is invalid; observer "
            u"registration was not changed.",
            fieldId
        );
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"reward") == 0) {
        const int access = checkAccess(4, 0x853a);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return false;
        }
        User* const target = builder->m_spTarget.GetUser();
        if (target == nullptr) {
            send(u"Select a target first.");
            return false;
        }

        int normalCount = 0;
        if (tokenCount == 2 && tokens[1][0] != L'\0') {
            normalCount = WindowsWtol(tokens[1].data());
        } else {
            const int minimum =
                std::min(g_PledgeGameSystem.m_nWinPrizeNormalMinCnt, g_PledgeGameSystem.m_nWinPrizeNormalMaxCnt);
            const int maximum =
                std::max(g_PledgeGameSystem.m_nWinPrizeNormalMinCnt, g_PledgeGameSystem.m_nWinPrizeNormalMaxCnt);
            normalCount = static_cast<int>(
                ::genrand64_real2() * static_cast<double>(maximum - minimum + 1) + static_cast<double>(minimum)
            );
        }
        if (g_PledgeGameSystem.m_nWinPrizeNormalItemType < 1) {
            send(u"No common_win_reward item");
            return false;
        }
        if (g_PledgeGameSystem.m_nWinPrizeRandItemType < 1) {
            send(u"No rand_win_min_max_reward item");
            return false;
        }

        const int actualNormalCount = g_PledgeGameSystem.GiveItemToWinner(
            static_cast<int>(target->m_nId), g_PledgeGameSystem.m_nWinPrizeNormalItemType, normalCount, true
        );
        const int randomMinimum =
            std::min(g_PledgeGameSystem.m_nWinPrizeRandItemMinCnt, g_PledgeGameSystem.m_nWinPrizeRandItemMaxCnt);
        const int randomMaximum =
            std::max(g_PledgeGameSystem.m_nWinPrizeRandItemMinCnt, g_PledgeGameSystem.m_nWinPrizeRandItemMaxCnt);
        const int randomCount = static_cast<int>(
            ::genrand64_real2() * static_cast<double>(randomMaximum - randomMinimum + 1) + static_cast<double>(randomMinimum)
        );
        static_cast<void>(
            g_PledgeGameSystem.GiveItem(target, g_PledgeGameSystem.m_nWinPrizeRandItemType, randomCount, false)
        );

        std::array<char16_t, 128> message{};
        FormatUtf16To(
            message.data(), message.size(), u"Target user got %d:%d, %d:%d item(s)",
            g_PledgeGameSystem.m_nWinPrizeNormalItemType, actualNormalCount, g_PledgeGameSystem.m_nWinPrizeRandItemType,
            randomCount
        );
        send(message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"close") == 0) {
        const int access = checkAccess(1, 0x856e);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        if (SharedPledgeGameInfo::GetInfo()->m_nStep == 1 || SharedPledgeGameInfo::GetInfo()->m_nStep == 7) {
            static_cast<void>(g_PledgeGameSystem.EndSeason(true));
            send(u"Season Ended. New Season Started.");
        } else {
            send(u"command not accepted!!");
        }
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"get_surrender") == 0) {
        const int access = checkAccess(5, 0x857d);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return false;
        }
        User* const target = builder->m_spTarget.GetUser();
        if (target == nullptr) {
            send(u"Select a target first.");
            return false;
        }
        std::array<char16_t, 128> message{};
        FormatUtf16To(
            message.data(), message.size(), u"Target user surrendered %d time(s)",
            g_PledgeGameSystem.GetSurrenderCount(static_cast<int>(target->m_nId))
        );
        send(message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"increase_surrender") == 0) {
        const int access = checkAccess(4, 0x8594);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return false;
        }
        User* const target = builder->m_spTarget.GetUser();
        if (target == nullptr) {
            send(u"Select a target first.");
            return false;
        }
        int amount = 1;
        if (tokenCount == 2 && tokens[1][0] != L'\0') {
            amount = WindowsWtol(tokens[1].data());
        }
        const int targetSid = static_cast<int>(target->m_nId);
        g_PledgeGameSystem.IncreasePledgeGameSurrenderCount(targetSid, amount);
        std::array<char16_t, 128> message{};
        FormatUtf16To(
            message.data(), message.size(), u"Target user surrender count increased to %d time(s)",
            g_PledgeGameSystem.GetSurrenderCount(targetSid)
        );
        send(message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"record") == 0) {
        const int access = checkAccess(5, 0x85b3);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        User* const builder = socket->GetUser();
        if (builder == nullptr) {
            return false;
        }
        User* const target = builder->m_spTarget.GetUser();
        if (target == nullptr) {
            send(u"Select a target first.");
            return false;
        }
        std::array<char16_t, 128> message{};
        FormatUtf16To(message.data(), message.size(), u"Target user's point is %d", target->m_PledgeGameUser.m_nPrizeCount);
        send(message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"room") == 0) {
        const int access = checkAccess(1, 0x85c9);
        if (access < 0) {
            return true;
        }
        if (access == 0) {
            return false;
        }
        std::uint32_t roomCount = 0;
        const char16_t* format = u"Error! %d is out of range!!";
        if (tokenCount == 2 && tokens[1][0] != L'\0') {
            roomCount = static_cast<std::uint32_t>(WindowsWtol(tokens[1].data()));
            if (roomCount - 1U < 5U || roomCount == 6U) {
                g_PledgeGameSystem.m_nActiveInstantZoneCount = static_cast<std::int32_t>(roomCount);
                format = u"%d room(s) active, now";
            }
        }
        std::array<char16_t, 128> message{};
        FormatUtf16To(message.data(), message.size(), format, static_cast<std::int32_t>(roomCount));
        send(message.data());
        return false;
    }

    return false;
}

