bool ResetSkillMe(CUserSocket* const socket, User*, char16_t*) {
    // Current L2Server.exe 0x005458b0.
    L2_GUARD_FUNCTION();
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }

    std::array<char16_t, 28> name;
    std::array<char16_t, 16> account;
    std::optional<std::u16string> accountText;
    {
        L2_GUARD(*user->m_lock);
        static_cast<void>(user->GetDBID());
        static_cast<void>(user->GetAccountID());
        name = {};
        CopyBuilderText(name.data(), 0x19, user->GetName());
        account = {};
        accountText.emplace(user->m_sAccountName.data());
        CopyBuilderText(account.data(), 0x0f, accountText->c_str());
        static_cast<void>(user->GetPos());
    }

    {
        L2_GUARD(*user->m_lock);
        {
            L2_GUARD(user->m_AcquiredSkillsSect);
            for (const auto& entry : user->m_AcquiredSkills) {
                const AcquiredSkillInfo& acquired = entry.second;
                if (acquired.m_bSaveToDB) {
                    user->SendDeletedSkillToDB(acquired.m_nId);
                }
            }
            user->_DeleteAllAcquireSkills(false);
        }
        user->AcquireSkills(g_SkillAcquireDB.GetAcquirableRaceSkills(user->m_data->m_Race), true, false);
        user->AcquireAllHonorsSkill();
    }
    user->ValidateChanged(VB_MAX);
    user->ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_BUILDERCMD});
    return false;
}

bool SetParamMe(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x0052088c.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setparam_me param value1 value2");
        return false;
    }

    const bool needsThirdValue = CompareBuilderTextIgnoreCase(tokens[0].data(), u"race") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"fp") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[0].data(), u"fl") == 0;
    if (needsThirdValue && tokenCount < 3) {
        const char16_t* usage = CompareBuilderTextIgnoreCase(tokens[0].data(), u"race") == 0
            ? u"//setparam_me race value[0:HUMAN, 1:ELF, 2:DARKELF, 3:ORC, 4:DWARF, 5:KAMAEL] value2[0:FIGHTER, 1:MAGE]"
            : CompareBuilderTextIgnoreCase(tokens[0].data(), u"fp") == 0 ? u"//setparam_me fp [faction_id] [point]"
                                                                         : u"//setparam_me fl [faction_id] [level]";
        socket->SendSystemMessage(u"SYS", usage);
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"fi") == 0 && tokenCount <= 1) {
        socket->SendSystemMessage(u"SYS", u"//setparam_me fi [faction_id]");
        return false;
    }

    return CMyParamSettingPacket(socket, tokens[0].data(), tokens[1].data(), tokens[2].data());
}

