bool show_ec_info(CUserSocket* const socket, User* const user, char16_t*) {
    // Current L2Server.exe 0x005671a4.
    L2_GUARD_FUNCTION();
    if (socket == nullptr || user == nullptr) {
        return false;
    }

    std::array<char16_t, 128> message;
    const int campaignId = CEventCampaignManager::Inst()->OnGoingEventCampaignId();
    if (campaignId < 1) {
        FormatUtf16To(message.data(), message.size(), u"Ongoing event campaign does not exist");
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }
    const int stepId = CEventCampaignManager::Inst()->OnGoingEventCampaignStepId();
    if (stepId < 1) {
        FormatUtf16To(message.data(), message.size(), u"Ongoing event campaign does not exist");
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"-- Ongoing Event Campaign Info --");
    FormatUtf16To(message.data(), message.size(), u"EventCampaign Id : %d", campaignId);
    socket->SendSystemMessage(u"SYS", message.data());
    FormatUtf16To(message.data(), message.size(), u"Step Id : %d", stepId);
    socket->SendSystemMessage(u"SYS", message.data());

    const int group = CEventCampaignManager::Inst()->OnJoinEventCampaignGoalGroupId(*user);
    if (group < 0) {
        FormatUtf16To(message.data(), message.size(), u"Not participation in event campaign", stepId);
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }
    FormatUtf16To(message.data(), message.size(), u"GoalGroup Id : %d", runtime::AddInt32Wrapping(group, 1));
    socket->SendSystemMessage(u"SYS", message.data());
    CEventCampaignManager::Inst()->OnShowProgressInfo(*user);
    return false;
}

