bool set_shape_shift_item(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00543058.
    L2_GUARD_FUNCTION();
    if (socket == nullptr || user == nullptr || command == nullptr) {
        return false;
    }

    std::array<char16_t, 256> slotText{};
    std::array<char16_t, 256> itemClassText{};
    char16_t* const slotToken = TakeBuilderTextToken(command);
    if (slotToken == nullptr) {
        socket->SendSystemMessage(u"SYS", u"//set_shape_shift_item [slotType] [itemClassId]");
        return false;
    }
    CopyBuilderText(slotText.data(), slotText.size(), slotToken);
    char16_t* const itemClassToken = TakeBuilderTextToken(command);
    if (itemClassToken == nullptr) {
        socket->SendSystemMessage(u"SYS", u"//set_shape_shift_item [slotType] [itemClassId]");
        return false;
    }
    CopyBuilderText(itemClassText.data(), itemClassText.size(), itemClassToken);

    int slot = ST_NONE;
    if (CompareBuilderTextIgnoreCase(slotText.data(), u"rhand") == 0) {
        slot = ST_RHAND;
    } else if (CompareBuilderTextIgnoreCase(slotText.data(), u"lhand") == 0) {
        slot = ST_LHAND;
    } else if (CompareBuilderTextIgnoreCase(slotText.data(), u"rlhand") == 0) {
        slot = ST_RLHAND;
    } else if (CompareBuilderTextIgnoreCase(slotText.data(), u"chest") == 0) {
        slot = ST_CHEST;
    } else if (CompareBuilderTextIgnoreCase(slotText.data(), u"legs") == 0) {
        slot = ST_LEGS;
    } else if (CompareBuilderTextIgnoreCase(slotText.data(), u"gloves") == 0) {
        slot = ST_GLOVES;
    } else if (CompareBuilderTextIgnoreCase(slotText.data(), u"feet") == 0) {
        slot = ST_FEET;
    } else if (CompareBuilderTextIgnoreCase(slotText.data(), u"hair") == 0) {
        slot = ST_HAIR;
    } else if (CompareBuilderTextIgnoreCase(slotText.data(), u"hair2") == 0) {
        slot = ST_HAIR2;
    } else {
        socket->SendSystemMessage(u"SYS", u"//set_shape_shift_item [slotType] [itemClassId]");
        return false;
    }

    CSPointer<CItem> item = CItemFactory::Inst().FindObjectSP(user->m_data->m_nSlotIndex[slot]);
    if (!item) {
        return false;
    }
    // Current code tests the parser's remaining pointer only after resolving
    // the item. Exactly two ordinary tokens therefore fail this late gate.
    // an ignored third token (or another remaining separator) makes it pass.
    if (*command == L'\0') {
        socket->SendSystemMessage(u"SYS", u"//set_shape_shift_item [slotType] [itemClassId]");
        return false;
    }

    const int itemClassId = WindowsWtol(itemClassText.data());
    item->SetShapeShiftingClassId(itemClassId);
    user->m_data->SetNeedUpdatePacket(0x49);
    user->ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_BUILDERCMD});
    return false;
}

