bool setdormant(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00522a1c.
    L2_GUARD_FUNCTION();
    if (socket == nullptr || user == nullptr) {
        return false;
    }

    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr) {
        user->GetSocket()->SendSystemMessage(u"SYS", u"target is not a player.");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setdormant [0 or 1]");
        return false;
    }

    const int enabled = WindowsWtol(tokens[0].data());
    if (enabled < 1) {
        if (!target->GetSocket()->IsDormantUser()) {
            socket->SendSystemMessage(u"SYS", u"this is already normal user.");
            return false;
        }
        target->GetSocket()->SetDormantUser(false, 0);
        socket->SendSystemMessage(u"SYS", u"dormant user setting canceled. please reconnect.");
        return false;
    }

    if (target->GetSocket()->IsDormantUser()) {
        socket->SendSystemMessage(u"SYS", u"this is already dormant user.");
        return false;
    }
    target->GetSocket()->SetDormantUser(true, 3);
    socket->SendSystemMessage(u"SYS", u"dormant user setting complete. please reconnect.");
    return false;
}

bool setdormanttime(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x00522ce0.
    L2_GUARD_FUNCTION();
    if (socket == nullptr || user == nullptr) {
        return false;
    }

    if (!user->m_spTarget.IsValid()) {
        user->SendSystemMessage(u"SYS", u"Target is not User.");
        return false;
    }
    User* const target = user->m_spTarget.GetUser();
    if (target == nullptr || target->GetSocket() == nullptr) {
        user->GetSocket()->SendSystemMessage(u"SYS", u"target is not a player.");
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//setdormanttime [minute]");
        return false;
    }

    const int minutes = WindowsWtol(tokens[0].data());
    if (minutes <= 0) {
        return false;
    }
    const int now = runtime::Int32FromBits(static_cast<std::uint32_t>(static_cast<std::int64_t>(std::time(nullptr))));

    int postponeHours = 0;
    const char16_t* message = nullptr;
    if (target->GetSocket()->GetDormantType() == 2) {
        postponeHours = g_NewbiePostponeTime;
        message = u"newbieuser time is changed";
    } else if (target->GetSocket()->GetDormantType() == 3) {
        postponeHours = g_DormantPostponeTime;
        message = u"dormant time is changed";
    } else {
        socket->SendSystemMessage(u"SYS", u"not dormant player");
        return false;
    }

    const int postponeMinutes = runtime::MultiplyInt32Wrapping(postponeHours, -60);
    const int markingTime = runtime::AddInt32Wrapping(
        runtime::MultiplyInt32Wrapping(runtime::AddInt32Wrapping(minutes, postponeMinutes), 60), now
    );
    target->GetSocket()->SetDormantMarkingTime(markingTime, -1);
    socket->SendSystemMessage(u"SYS", message);
    return false;
}

