bool addpledgemem(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0053df70.
    L2_GUARD_FUNCTION();
    if (user == nullptr) {
        return false;
    }

    CCreature* const selected = user->m_spTarget.GetCreature();
    User* const firstTarget = selected != nullptr ? selected->CastUser() : nullptr;
    if (firstTarget == nullptr) {
        user->SendSystemMessage(u"SYS", u"Target is not User.");
        return false;
    }
    User* const target = selected->CastUser();
    if (target->m_data->m_nPledgeID != 0) {
        socket->SendSystemMessage(SystemMessageId::ALREADY_IN_CLAN);
        socket->Send("cd", 0x2d, 0);
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 1> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//addpledgemem pledgename");
        return false;
    }

    const int worldId = user->m_data->m_nWorldId;
    std::u16string pledgeName = std::u16string(tokens[0].data());
    CSPointer<CPledge> pledge = CPledge::FindPledge(worldId, reinterpret_cast<SharedUtilsWideChar*>(pledgeName.data()));
    if (!pledge) {
        db.RequestLoadPledge(worldId, tokens[0].data());
        socket->SendSystemMessage(u"SYS", u"pledge name is not valid or not loaded yet");
        return false;
    }

    user->m_pledgeTypeWhenAskJoin = MASTER_PLEDGE;
    db.RequestUpdateUserPledge(target, pledge.get(), 1, MASTER_PLEDGE);
    socket->SendSystemMessage(SystemMessageId::JOINED_CLAN);
    CReplyChecker::FinishWaitingReplyByReplier(user);
    return false;
}

bool withdrawpledgemem(CUserSocket* const socket, User* const user, char16_t*) {
    // Current L2Server.exe 0x00555bbc.
    L2_GUARD_FUNCTION();
    if (user == nullptr || socket == nullptr) {
        return false;
    }

    CCreature* const selected = user->m_spTarget.GetCreature();
    User* const firstTarget = selected != nullptr ? selected->CastUser() : nullptr;
    if (firstTarget == nullptr) {
        user->SendSystemMessage(u"SYS", u"Target is not User.");
        return false;
    }
    User* const target = selected->CastUser();
    if (target == nullptr) {
        user->SendSystemMessage(u"SYS", u"Target is not available.");
        return false;
    }

    CPledge* const pledge = target->GetPledge();
    if (pledge == nullptr) {
        socket->SendSystemMessage(SystemMessageId::NOT_IN_CLAN);
        socket->Send("cd", 0x34, 0);
        return false;
    }
    if (target->m_data->m_bPledgeMaster) {
        socket->SendSystemMessage(SystemMessageId::CLAN_LEADER_CANNOT_LEAVE);
        socket->Send("cd", 0x34, 0);
        return false;
    }
    if (target->m_data->m_bIsInCombatMode) {
        socket->SendSystemMessage(SystemMessageId::CANNOT_LEAVE_CLAN_DURING_COMBAT);
        socket->Send("cd", 0x34, 0);
        return false;
    }
    if (CPledge::IsMemberInTeamBattleEntry(target)) {
        socket->SendSystemMessage(
            SystemMessageId::CANNOT_LEAVE_OR_EXPEL_CLAN_MEMBER_DURING_TEAM_CLAN_HALL_BATTLE_REGISTRATION
        );
        socket->Send("cd", 0x34, 0);
        return false;
    }
    if (target->m_data->m_nDominionSiegeStatus != 0) {
        socket->SendSystemMessage(SystemMessageId::CANNOT_LEAVE_OR_EXPEL_CLAN_MEMBER_IN_TERRITORY_WAR);
        socket->Send("cd", 0x34, 0);
        return false;
    }

    FOR_ALL_SUMMON_PET_IN_SUMMON_LIST(target, summon, {
        if (summon->m_data->m_bIsInCombatMode) {
            socket->SendSystemMessage(SystemMessageId::CANNOT_LEAVE_CLAN_DURING_COMBAT);
            socket->Send("cd", 0x34, 0);
            return false;
        }
    });

    int transaction = 0;
    if (!pledge->BeginTransaction(&transaction)) {
        socket->SendSystemMessage(SystemMessageId::CLAN_OPERATION_ALREADY_IN_PROGRESS);
        socket->Send("cd", 0x34, 0);
        return false;
    }

    const int raidStatus = static_cast<int>(socket->GetRaidStatus());
    const int builderPledgeType = user->m_data->m_nPledgeType;
    const std::uint32_t builderDatabaseId = user->GetDBID();
    // Log.Add(
    //     LOG_ERROR,
    //     L"[%s][%d]Request WithdrawPledge on RaidStatus "
    //     L"userDBID[%d] pledgetype[%d] socketstatus[%d]",
    //     L"BuilderCmdHandler.cpp",
    //     0x8c46,
    //     builderDatabaseId,
    //     builderPledgeType,
    //     raidStatus)
    // Previous: L2_LOG_ERROR(Log,
    //     L"[%s][%d]Request WithdrawPledge on RaidStatus "
    //     L"userDBID[%d] pledgetype[%d] socketstatus[%d]",
    //     L"BuilderCmdHandler.cpp", 0x8c46, builderDatabaseId,
    //     builderPledgeType, raidStatus)
    L2_LOG_ERROR(
        Log,
        u"[builder clan] Withdrawal requested while character %u has pledge "
        u"type %d and socket raid status %d; the database update is still "
        u"submitted.",
        builderDatabaseId, builderPledgeType, raidStatus
    );
    db.RequestUpdateUserPledge(target, pledge, 2, static_cast<PledgeType>(target->m_data->m_nPledgeType));
    socket->SendSystemMessage(u"SYS", u"Target withdraw at the pledge");
    return false;
}

