bool SetProductData(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x0053e2c8.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 5> tokens{};
    std::size_t tokenCount = 0;
    char16_t* lastSourceToken = nullptr;
    bool parsed = true;
    while (tokenCount < 3) {
        lastSourceToken = TakeBuilderTextToken(command);
        if (lastSourceToken == nullptr) {
            parsed = false;
            break;
        }
        CopyBuilderText(tokens[tokenCount].data(), tokens[tokenCount].size(), lastSourceToken);
        ++tokenCount;
    }
    while (parsed && tokenCount < tokens.size()) {
        char16_t* const token = TakeBuilderTextToken(command);
        if (token == nullptr) {
            break;
        }
        lastSourceToken = token;
        CopyBuilderText(tokens[tokenCount].data(), tokens[tokenCount].size(), token);
        ++tokenCount;
    }
    if (!parsed) {
        socket->SendSystemMessage(u"SYS", u"//set_product product_id param value");
        return false;
    }

    const int productId = WindowsWtol(tokens[0].data());
    CProductSP product = g_ShopServer.GetProduct(productId);
    if (!product) {
        socket->SendSystemMessage(u"SYS", u"Invalid product id\n//set_product product_id param value");
        return false;
    }

    std::array<char16_t, 1024> message{};
    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"minlevel") == 0) {
        const int value = WindowsWtol(tokens[2].data());
        product->SetMinLevel(value);
        FormatUtf16To(message.data(), message.size(), u"product[%d] min level is %d", productId, value);
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"maxlevel") == 0) {
        const int value = WindowsWtol(tokens[2].data());
        product->SetMaxLevel(value);
        FormatUtf16To(message.data(), message.size(), u"product[%d] max level is %d", productId, value);
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    const bool birthdayStart = CompareBuilderTextIgnoreCase(tokens[1].data(), u"birthday_start") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[1].data(), u"bs") == 0;
    const bool birthdayEnd = CompareBuilderTextIgnoreCase(tokens[1].data(), u"birthday_end") == 0 ||
        CompareBuilderTextIgnoreCase(tokens[1].data(), u"be") == 0;
    if (birthdayStart || birthdayEnd) {
        if (tokenCount < 5) {
            FormatUtf16To(
                message.data(), message.size(),
                birthdayStart ? u"//set_product product_id birthday_start "
                                u"year month day"
                              : u"//set_product product_id birthday_end "
                                u"year month day"
            );
            socket->SendSystemMessage(u"SYS", message.data());
            return false;
        }

        // Current seeds the low qword with the fifth token pointer, then
        // overwrites only year/month/day. This keeps pointer bits in
        // wDayOfWeek and leaves the upper four SYSTEMTIME lanes indeterminate.
        SYSTEMTIME birthday;
        const std::uintptr_t sourceBits = reinterpret_cast<std::uintptr_t>(lastSourceToken);
        std::memcpy(&birthday, &sourceBits, sizeof(sourceBits));
        birthday.wYear = static_cast<std::uint16_t>(WindowsWtol(tokens[2].data()));
        birthday.wMonth = static_cast<std::uint16_t>(WindowsWtol(tokens[3].data()));
        birthday.wDay = static_cast<std::uint16_t>(WindowsWtol(tokens[4].data()));
        if (birthdayStart) {
            product->SetBirthdayStart(birthday);
        } else {
            product->SetBirthdayEnd(birthday);
        }
        FormatUtf16To(
            message.data(), message.size(),
            birthdayStart ? u"product[%d] birthday from %d-%d-%d" : u"product[%d] birthday to %d-%d-%d", productId,
            static_cast<int>(birthday.wYear), static_cast<int>(birthday.wMonth), static_cast<int>(birthday.wDay)
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"limit") == 0) {
        if (tokenCount < 4) {
            FormatUtf16To(
                message.data(), message.size(),
                u"//set_product product_id limit "
                u"limitday[1/-1] limitcount"
            );
            socket->SendSystemMessage(u"SYS", message.data());
            return false;
        }
        const int period = WindowsWtol(tokens[2].data());
        const int count = WindowsWtol(tokens[3].data());
        if ((period != 1 && period != -1) || count < 1) {
            socket->SendSystemMessage(
                u"SYS",
                u"limit day must be 1 or -1, "
                u"limit count must be over 0"
            );
            return false;
        }
        product->SetSaleLimit(period, count);
        FormatUtf16To(
            message.data(), message.size(), u"product[%d] limitday = %d, limitcount = %d", productId, period, count
        );
        socket->SendSystemMessage(u"SYS", message.data());
    }
    return false;
}

