bool MatchingPoint(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x00524f84.
    L2_GUARD_FUNCTION();
    if (socket == nullptr) {
        return true;
    }
    User* const user = socket->GetUser();
    if (user == nullptr) {
        return false;
    }
    if (command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 2, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//matchingpoint command [options]...");
        return false;
    }

    User* const gateUser = socket->GetUser();
    if (gateUser == nullptr) {
        return false;
    }
    int builderLevel = 0;
    {
        L2_GUARD(*gateUser->m_lock);
        builderLevel = gateUser->m_data->m_nBuilder;
    }
    if (builderLevel == 0 || builderLevel >= 2) {
        return false;
    }

    const std::uint32_t rawType = static_cast<std::uint32_t>(WindowsWtol(tokens[0].data()));
    if (rawType > 1U) {
        socket->SendSystemMessage(u"SYS", u"//matching_point [0|1] [load|save|reload]");
        return false;
    }
    const MatchingPoint::MATCHINGPOINT_TYPE type = static_cast<MatchingPoint::MATCHINGPOINT_TYPE>(rawType);

    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"load") == 0) {
        const std::uint32_t databaseId = user->GetDBID();
        const std::uint32_t serverId = user->GetServerId();
        DxMatchingPoint packet(false, type, serverId, databaseId, 0);
        db.RequestTPacketProcess(user->m_data->m_nWorldId, 0x3a, 0x15, packet);
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"save") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//matchingpoint save delta");
            return false;
        }
        const std::int64_t pointDiff = static_cast<std::int64_t>(WindowsWtol(tokens[2].data()));
        const std::uint32_t databaseId = user->GetDBID();
        const std::uint32_t serverId = user->GetServerId();
        DxMatchingPoint packet(true, type, serverId, databaseId, pointDiff);
        db.RequestTPacketProcess(user->m_data->m_nWorldId, 0x3a, 0x15, packet);
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"reload") == 0) {
        socket->SendSystemMessage(
            u"SYS", g_MatchingPointDB.LoadLexYacc() ? u"config reload success" : u"config reload failed"
        );
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"//matching_point [0|1] [load|save|reload]");
    return false;
}

