bool KamarokaPremiumInzone(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x005249c8.
    L2_GUARD_FUNCTION();
    if (user == nullptr || !user->IsBuilder() || command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//kamaroka [param]");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"info") == 0) {
        const int round = CPremiumInstantRankingSystem::Inst().GetRound();
        const wchar_t* const state = CPremiumInstantRankingSystem::Inst().IsRaidTime() ? L"RaidTime" : L"RewardTime";
        const SharedKamarokaInfo* const info = SharedKamarokaInfo::GetInfo();
        std::array<char16_t, 512> message{};
        FormatUtf16To(
            message.data(), message.size(),
            u"Kamaroka: Round[%d] State[%s] \n"
            u"KamarokaCycle[%d;%d;%d;%d;%d;%d;%d]",
            round, state, info->m_bKamaCycle[0] ? 1 : 0, info->m_bKamaCycle[1] ? 1 : 0, info->m_bKamaCycle[2] ? 1 : 0,
            info->m_bKamaCycle[3] ? 1 : 0, info->m_bKamaCycle[4] ? 1 : 0, info->m_bKamaCycle[5] ? 1 : 0,
            info->m_bKamaCycle[6] ? 1 : 0
        );
        user->GetSocket()->SendSystemMessage(u"SYS", message.data());
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set_raid") == 0) {
        if (CPremiumInstantRankingSystem::Inst().IsRaidTime()) {
            user->GetSocket()->SendSystemMessage(u"SYS", u"//kamaroka already RaidTime. ");
        } else {
            CPremiumInstantRankingSystem::Inst().SetStatusRaid();
            user->GetSocket()->SendSystemMessage(u"SYS", u"//kamaroka set Raid Time Success. ");
        }
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set_reward") == 0) {
        if (CPremiumInstantRankingSystem::Inst().IsRewardTime()) {
            user->GetSocket()->SendSystemMessage(u"SYS", u"//kamaroka already RewardTime. ");
        } else {
            CPremiumInstantRankingSystem::Inst().SetStatusGiveReward();
            user->GetSocket()->SendSystemMessage(u"SYS", u"//kamaroka set Reward Time Success. ");
        }
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"new_round") == 0) {
        CPremiumInstantRankingSystem::Inst().AddNextRound();
        CPremiumInstantRankingSystem::Inst().InitStatus();
        CPremiumInstantRankingSystem::Inst().LoadFromDB();
        user->GetSocket()->SendSystemMessage(u"SYS", u"//kamaroka add New Round Success. ");

        const int round = CPremiumInstantRankingSystem::Inst().GetRound();
        const wchar_t* const state = CPremiumInstantRankingSystem::Inst().IsRaidTime() ? L"RaidTime" : L"RewardTime";
        std::array<char16_t, 512> message{};
        FormatUtf16To(message.data(), message.size(), u"Kamaroka: Round[%d] State[%s]", round, state);
        user->GetSocket()->SendSystemMessage(u"SYS", message.data());
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set_cycle") == 0) {
        constexpr const char16_t* usage = u"//kamaroka set_cycle "
                                          u"[days/*SUN;MON;TUE;WED;THU;FRI;SAT - 1;0;0;0;0;0;1*/]";
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", usage);
            return false;
        }

        int cycle[7] = {};
        int* currentDay = cycle;
        int semicolonCount = 0;
        std::size_t index = 0;
        do {
            if (tokens[1][index] == L';') {
                ++semicolonCount;
                ++currentDay;
            } else if (tokens[1][index] == L'1') {
                *currentDay = 1;
            }
            ++index;
        } while (index < std::char_traits<char16_t>::length(tokens[1].data()) + 1U);
        if (semicolonCount != 6) {
            socket->SendSystemMessage(u"SYS", usage);
            return false;
        }
        CPremiumInstantRankingSystem::Inst().SetKamarokaCycle(cycle);
        socket->SendSystemMessage(u"SYS", u"Kamaroka Set Cycle Success. ");
        return false;
    }
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"add_score") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//kamaroka add_score [score]");
            return false;
        }
        const int score = WindowsWtol(tokens[1].data());
        CPremiumInstantRankingSystem::Inst().RequestRegisterNewRecord(score, user);
        socket->SendSystemMessage(u"SYS", u"Kamaroka add Score Success. ");
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"//kamaroka [param]");
    return false;
}

