bool summon_ensoul(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x00562f04.
    L2_GUARD_FUNCTION();
    if (command == nullptr) {
        return false;
    }
    std::array<std::array<char16_t, 256>, 5> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, tokens.size(), tokens, tokenCount)) {
        socket->SendSystemMessage(
            u"SYS",
            u"//summon_ensoul [item_id] [normal ensoul option 1] "
            u"[normal ensoul option 2] [bm ensoul option] [enchant]"
        );
        return false;
    }

    User* const user = socket->GetUser();
    if (user == nullptr) {
        return true;
    }
    {
        L2_GUARD(*user->m_lock);
        std::array<char16_t, 28> name{};
        std::array<char16_t, 16> accountName{};
        static_cast<void>(user->GetDBID());
        static_cast<void>(user->GetAccountID());
        CopyBuilderText(name.data(), 0x19, user->GetName());
        const std::u16string account(user->m_sAccountName.data());
        CopyBuilderText(accountName.data(), 0x0f, account.c_str());
        static_cast<void>(user->GetPos());
    }

    const int itemId = WindowsWtol(tokens[0].data());
    const int normalOption1 = WindowsWtol(tokens[1].data());
    const int normalOption2 = WindowsWtol(tokens[2].data());
    const int bmOption = WindowsWtol(tokens[3].data());
    int enchant = WindowsWtol(tokens[4].data());
    if (itemId >= 1000001) {
        socket->SendSystemMessage(u"SYS", u"invalid item_class_id. cannot summon NPC");
        return false;
    }

    CObject* const object = g_ObjectDB.GetObjectW(itemId, false);
    if (object == nullptr || !object->IsItem()) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Item[%d] is not exist.",
        //     L"BuilderCmdHandler.cpp",
        //     0x9314,
        //     itemId)
        // Previous: L2_LOG_ERROR(Log,
        //     L"[%s][%d] Item[%d] is not exist.",
        //     L"BuilderCmdHandler.cpp", 0x9314, itemId)
        L2_LOG_ERROR(
            Log,
            u"[builder inventory] Item class %d is undefined or is not an "
            u"item; the command is rejected.",
            itemId
        );
        return false;
    }
    if (enchant < 0 || enchant > 50) {
        enchant = 0;
    }

    InventoryParams parameters;
    parameters.nItemClassID = itemId;
    parameters.nCount = 1;
    parameters.nEnchanted = enchant;
    if (normalOption1 == 0) {
        if (normalOption2 != 0) {
            socket->SendSystemMessage(u"SYS", u"invalid ensoul option.");
            return false;
        }
    } else {
        const auto first = g_mEnsoulOptionData.find(normalOption1);
        if (first == g_mEnsoulOptionData.end()) {
            socket->SendSystemMessage(u"SYS", u"invalid ensoul option.");
            return false;
        }
        parameters.mEnsoulOptionMap[1].insert({1, first->second});
        if (normalOption2 != 0) {
            const auto second = g_mEnsoulOptionData.find(normalOption2);
            if (second == g_mEnsoulOptionData.end()) {
                socket->SendSystemMessage(u"SYS", u"invalid ensoul option.");
                return false;
            }
            parameters.mEnsoulOptionMap[1].insert({2, second->second});
        }
    }
    if (bmOption != 0) {
        const auto bm = g_mEnsoulOptionData.find(bmOption);
        if (bm == g_mEnsoulOptionData.end()) {
            socket->SendSystemMessage(u"SYS", u"invalid ensoul option.");
            return false;
        }
        parameters.mEnsoulOptionMap[2].insert({1, bm->second});
    }

    {
        L2_WRITE_GUARD(user->m_inv);
        static_cast<void>(user->AddItemToInventory(parameters));
    }
    return false;
}

