bool VipAttendance(CUserSocket* const socket, User* const user, char16_t* command) {
    // Current L2Server.exe 0x0056786c.
    L2_GUARD_FUNCTION();
    if (socket == nullptr || user == nullptr || command == nullptr || !user->IsBuilder()) {
        return false;
    }
    if (!g_bUseVipAttendance) {
        socket->SendSystemMessage(u"SYS", u"not used vip attendance system");
        return false;
    }

    CObject* const object = user->m_spTarget.GetObjectW();
    if (object == nullptr) {
        socket->SendSystemMessage(u"SYS", u"invalid target");
        return false;
    }
    if (!object->IsPC()) {
        socket->SendSystemMessage(u"SYS", u"Target is not User");
        return false;
    }
    User* const target = object->CastUser();

    std::array<std::array<char16_t, 256>, 3> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//attendance [param]");
        return false;
    }

    UserAttendance attendance;
    VipAttendanceSystem& initialAttendanceSystem = VipAttendanceSystem::Inst();
    const std::uint32_t initialAccountId = target->GetAccountID();
    if (!initialAttendanceSystem.GetUserAttendance(initialAccountId, attendance)) {
        socket->SendSystemMessage(u"SYS", u"//attendance No UserData");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"info") == 0) {
        if (!VipAttendanceSystem::Inst().CheckDaysAndReset(target)) {
            socket->SendSystemMessage(u"SYS", u"//attendance reset days. try again.");
            return false;
        }

        const int day = attendance.GetDay();
        const bool normalAvailable = attendance.GetConfirmNormalAttendance();
        const bool pcCafeAvailable = attendance.BitTestPCCafe(day);
        const bool vipAvailable = attendance.BitTestVIP(day);

        const wchar_t* attendanceType = L"";
        if (attendance.m_cCheckType == 1) {
            attendanceType = L"[Nomal]";
        } else if (attendance.m_cCheckType == 2) {
            attendanceType = L"[Newbie]";
        } else if (attendance.m_cCheckType == 3) {
            attendanceType = L"[Dormant]";
        }

        int resetHour = 0;
        int resetMinute = 0;
        g_VipAttendanceDB.GetResetTime(resetHour, resetMinute);
        std::array<char16_t, 512> message{};
        FormatUtf16To(
            message.data(), message.size(),
            u"AttendanceType%ls \nGet Reward: %d Day - Normal[%c] PCCafe[%c] VIP[%c] \n ResetTime[%d:%d]", attendanceType,
            day, normalAvailable ? L'X' : L'O', pcCafeAvailable ? L'X' : L'O', vipAvailable ? L'X' : L'O', resetHour,
            resetMinute
        );
        socket->SendSystemMessage(u"SYS", message.data());
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"check") == 0) {
        if (tokenCount > 1) {
            const int day = WindowsWtol(tokens[1].data());
            if (day > 0) {
                const int maximumDay = VipAttendanceSystem::Inst().GetMaxDay(attendance.m_cCheckType);
                if (day <= maximumDay) {
                    VipAttendanceSystem& updateSystem = VipAttendanceSystem::Inst();
                    const std::uint32_t accountId = target->GetAccountID();
                    static_cast<void>(updateSystem.SendToAuthUpdateVipAttendance(
                        accountId, attendance.m_cCheckType, day - 1, 0, 0, 0, true
                    ));
                    socket->SendSystemMessage(u"SYS", u"//attendance check success.");
                    return false;
                }
            }

            const int maximumDay = VipAttendanceSystem::Inst().GetMaxDay(attendance.m_cCheckType);
            std::array<char16_t, 512> message{};
            FormatUtf16To(message.data(), message.size(), u"//input nDay [1 ~ %d]", maximumDay);
            socket->SendSystemMessage(u"SYS", message.data());
            return false;
        }

        if (!VipAttendanceSystem::Inst().CheckDaysAndReset(target)) {
            socket->SendSystemMessage(u"SYS", u"//attendance reset days. try again.");
            return false;
        }
        VipAttendanceSystem& resetSystem = VipAttendanceSystem::Inst();
        const std::uint32_t accountId = target->GetAccountID();
        resetSystem.ResetTimeUserAttendanceForBuilder(accountId);
        target->OnRequestVipAttendanceCheck();
        socket->SendSystemMessage(u"SYS", u"//attendance check success.");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"reset") == 0) {
        if (tokenCount < 2) {
            socket->SendSystemMessage(u"SYS", u"//attendance reset [type/*1:normal 2:newbie 3:dormant*/]");
            return false;
        }
        const int attendanceType = WindowsWtol(tokens[1].data());
        if (static_cast<std::uint32_t>(attendanceType) - 1U > 2U) {
            socket->SendSystemMessage(u"SYS", u"//attendance reset [type/*1:normal 2:newbie 3:dormant*/]");
            return false;
        }
        VipAttendanceSystem& resetSystem = VipAttendanceSystem::Inst();
        const std::uint32_t accountId = target->GetAccountID();
        resetSystem.SendToAuthResetAttendance(
            accountId, static_cast<char>(attendanceType), const_cast<wchar_t*>(L"ToBuilder")
        );
        socket->SendSystemMessage(u"SYS", u"//attendance reset success.");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"reset_time") == 0) {
        VipAttendanceSystem& resetSystem = VipAttendanceSystem::Inst();
        const std::uint32_t accountId = target->GetAccountID();
        resetSystem.ResetTimeUserAttendanceForBuilder(accountId);
        static_cast<void>(VipAttendanceSystem::Inst().CheckDaysAndReset(target));
        socket->SendSystemMessage(u"SYS", u"//attendance reset time success.");
        return false;
    }

    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"set_time") == 0) {
        if (tokenCount < 3) {
            socket->SendSystemMessage(u"SYS", u"//attendance set_time hour min");
            return false;
        }
        const std::uint32_t resetHour = static_cast<std::uint32_t>(WindowsWtol(tokens[1].data()));
        const std::uint32_t resetMinute = static_cast<std::uint32_t>(WindowsWtol(tokens[2].data()));
        if (resetHour > 23U || resetMinute > 59U) {
            socket->SendSystemMessage(u"SYS", u"//attendance set_time hour[0 ~ 23] min[0 ~ 59]");
            return false;
        }
        g_VipAttendanceDB.m_nResetHour = static_cast<std::int32_t>(resetHour);
        g_VipAttendanceDB.m_nResetMin = static_cast<std::int32_t>(resetMinute);
        socket->SendSystemMessage(u"SYS", u"//attendance time setting success.");
        return false;
    }

    socket->SendSystemMessage(u"SYS", u"//attendance [param]");
    return false;
}

