bool questhelper_set(CUserSocket* const socket, User*, char16_t* command) {
    // Current L2Server.exe 0x005281d4.
    L2_GUARD_FUNCTION();
    if (g_L2ServerType != L2ServerType::DEV || command == nullptr) {
        return false;
    }

    std::array<std::array<char16_t, 256>, 2> tokens{};
    std::size_t tokenCount = 0;
    if (!ParseBuilderTextTokenList(command, 1, tokens, tokenCount)) {
        socket->SendSystemMessage(u"SYS", u"//questhelper_set [quest/html/quest_reload] [on/off]");
        return false;
    }

    std::array<char16_t, 1024> message{};
    if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"quest_reload") == 0) {
        g_QuestHelper.reload();
        FormatUtf16To(message.data(), message.size(), u"QuestHelper Reload");
    } else {
        bool enabled = true;
        if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"on") != 0) {
            if (CompareBuilderTextIgnoreCase(tokens[1].data(), u"off") != 0) {
                return false;
            }
            enabled = false;
        }

        if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"quest") == 0) {
            g_QuestHelper.setUseQuestOpen(enabled);
            const bool useHtml = g_QuestHelper.isUseHTMLOpen();
            if (enabled && !g_QuestHelper.isLoaded()) {
                // Log.Add(LOG_NORMAL, L"Loading QuestHelper")
                // Previous: L2_LOG_INFO(Log, L"Loading QuestHelper")
                L2_LOG_INFO(
                    Log,
                    u"[quest helper] Loading data before enabling quest "
                    u"access."
                );
                static_cast<void>(g_QuestHelper.load());
            }
            g_QuestHelper.setUseHTMLOpen(useHtml);
        } else if (CompareBuilderTextIgnoreCase(tokens[0].data(), u"html") == 0) {
            g_QuestHelper.setUseHTMLOpen(enabled);
        } else {
            return false;
        }

        FormatUtf16To(message.data(), message.size(), u"QuestHelper %ls : %ls", tokens[0].data(), enabled ? L"on" : L"off");
    }

    socket->SendSystemMessage(u"SYS", message.data());
    return false;
}

